/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20150326-10","meetingId":"h27-cm03","date":"2015年3月26日","dateIso":"2015-03-26","committee":"議会運営委員会","time":"午前１０時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２７年請願第７号、区民の期待に応える品川区議会改革を求める請願","agenda":"平成２７年請願第７号、区民の期待に応える品川区議会改革を求める請願","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"意見陳述は、採決の前ではなくて、この請願者の思いをしっかりと受けとめる立場で、審議に入る前に意見陳述をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひとも意見陳述をしたいという、その請願者の思いというのは、ここに書き切れない思いがたくさんあるので、聞いてほしいということだと思うのです。そこのところはやはり区民の思いですから、私たち議員としてはしっかりと受けとめることが必要だと思うのです。だから、ぜひとも審議の前に聞くように諮っていただけますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、ここには書き切れない思いをぜひとも聞いていただきたいと、そういうことでの申し出ですから、そういうふうに思っている方もいらっしゃるかもしれませんので、委員長としてもぜひここで委員会として諮っていただいて、そして、はじめに意見陳述を聞いてから審議に入る、しかも議会のことだからと委員長はおっしゃられますけれども、議会のことだからこそ、区民の声をしっかりと聞いて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"言わんとすることは、今回、請願を出された方の趣旨は十分に受けとめられて、同じ会派の方が出席されているのですから、それに対してさらに本人が意見陳述するというのは、ちょっとどうなのかなと思います。我々はやはり、今回出された趣旨、理由等について客観的に判断するということで、私は、別段委員長の采配は間違っていないと思うのですが、どうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の須貝委員の発言はおかしいと思います。もちろん紹介議員が受けとめないと請願ができませんので、会派として受けとめますけれども、意見陳述というのは、ここに書き込めていない、もっと多くのたくさんの願いをぜひ聞いてほしいという区民、請願者に与えられた意見陳述の場です。なので、ぜひ諮っていただきたいと思いますので、委員長、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"もう１回だけお聞きしたい。このＡ４版の用紙に入る文面しか提出してはいけないのですか。例えば、これが５枚になろうが、１０枚になろうが、だめなのですか。その方がきちんと自分の意思を明確に、もっと伝えたいことがあるというならば、私は、それはできないはずはないと思うので、少し言われた意味がよくわからないです。","respondent":"伊藤委員長、原区議会事務局長","answer":"少し前に進めします。私としては、決して意見陳述の申し出を断っているわけではありません。既に朗読が終わりましたので、本件について、事務局長の説明をお願いいたします。請願の趣旨が４点ございまして、そこに絡むところで、現状での、この間の取組みについてご説明させていただければと思います。","voiceIndex":11,"id":"exchange-006"},{"speaker":"渡部委員","kind":"質問・要望","question":"この１番については、２点教えていただきたいと思います。４番に関しましては、確かに今ご説明のあったような感じなのですけれども、規則の変更をしたりすることによって、いろいろ書くことは可能なのですかね。であれば、もっと親切なのは、その請願結果がどうだったとお伝えしたうえで、２週間、３週間後に議事録が上がりますから、そちらをご確認くださいのほうが、逆に親切なのかと思います。","respondent":"原区議会事務局長","answer":"冒頭のところで、傍聴席のところを、まず最初にご説明させていただきました。この傍聴席というのは、物理的なスペースの中でどう受け入れるかということで、他区の状況もそれぞれ、部屋の広さや委員会の開催の仕方、区によって違うと思います。","voiceIndex":16,"id":"exchange-007"},{"speaker":"渡部委員","kind":"質問・要望","question":"先に４番なのですけれども、冒頭に私のほうでこのような形でと申し上げました。例えば、会議録をつけてお送りするとすれば、採択、不採択等の通知は、３週間後であれば、こちらがお求めになっていることは可能だということ。逆に申しますと、願意に沿いがたいという形であれば、概ね審議が終了してどれくらいで着いているのか。改めてもう１回、そこを先にお願いします。","respondent":"原区議会事務局長","answer":"そういう意味では、これは議会のあり方検討会でも議論があって、そこについてはなるべく早く区民の方にお知らせをしていこうと、ただし、中身については正式な議事録としてのものではございませんというただし書きをつけているという形になります。","voiceIndex":18,"id":"exchange-008"},{"speaker":"渡部委員","kind":"意見","question":"わかりました、理解しました、４番はわかりました。１番は、今お話を聞いていたところですと、なかなか難しいのかなと思います。例えば、本当にそれを実行していこうとなりますと、これからしっかり時間をかけて、委員会自体の開催をどういうふうにしていくべきなのかというところから入っていかないと、今の段階では解決が難しいのかということを感じました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"請願の理由の中で、インターネット中継ということが出ています。逆に、それができてから３週間後に採決のご報告をするとなると、真摯ではないかなと思うので、その点に関しては、もし可能であれば、通知の中にホームページのアドレスと参照してくださいという文言を入れていただければいいのかと思いますが、その点についてお伺いします。","respondent":"原区議会事務局長","answer":"そちらのほうを直前に変えるということになりますと、５つの常任委員会ですから、私ども、書記を含めて１０名の職員が委員会に張りつく形になってありますので、直前にそこを変えるとなりますと、委員会のご案内とか、あるいは各委員、傍聴者へのご案内等々が。","voiceIndex":21,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に入手をしていないというのが３９.７％で、４割くらいの方が入手していないということで、区議会で、区民の立場の代表の議員が区政をチェックしながら、区民要望を出して、働いている中身をもっともっと知っていただきたいという意味において、この傍聴の問題はすごく大きいと思うのです。皆さんにご意見をお伺いしたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問・要望","question":"最初の請願の趣旨で、１番目は、やはり物理的な場所、部屋云々もあるし、私は今、総務委員会にいるのですが、本当に傍聴者ゼロということがほとんどですかね。３番目は、各会派で事前にそれぞれ議論しているので、私は、皆さんはここできちんと意見を言っているのではないかと思います。今回の請願の趣旨というのは、私はどうなのかなという疑問を感じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"この間、自民党、民主・改革ネット、またほかの委員からもご意見をいただいて、確認したい点、またこちらの請願の趣旨であるところの現実の対応とかを聞いていただいたので、それを踏まえてですけれども、そのうえで確認があった中で、まず１点、これについては、もう既に須貝委員もおっしゃいましたけれども、入れ替え制で行うとか、こういう現実的な対応をしていただいているということで、また。","respondent":"原区議会事務局長","answer":"そこで、いろいろな意見が出たときに、その意見を全て載せてくるというのはなかなか難しいということもあると想像します。それを幾つかの意見にまとめて確認を取っていくというのもなかなか難しいと、私どもも理解しています。","voiceIndex":26,"id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"最後の今のところだけ確認で、現状と課題の部分もいただいて、事務的な部分では非常に悩ましい部分であると思います。先ほどの正確性という部分では、例えば、大きな予算に反対しながら、いかにもさもやっているような発言をするとか、そうしたことも含めて、正確性というところは非常に求められる部分があると思うのです。そのような意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"検討した結果、可能だということになれば、傍聴規則を変えればいいだけのことですから、ぜひそれはご検討いただきたいと思うのですけれども、事務局としていかがか、ということが１点です。そういうことで集めていくわけですから、請願の署名を訴えるときと同じような思いを、議員の皆さんにも聞いていただきたいというのが、私は、請願者の思いだと思います。","respondent":"原区議会事務局長","answer":"他区の状況ということですけれども、私どもも常に他区の状況にはアンテナを張り、本会議場の磁気ループの設置等々についても、そういったところで積極的に対応していると理解しておりますので、これについては、今後も継続していくと理解しています。","voiceIndex":29,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本当にさまざま、私もこの間、開かれた議会というところではぐっと進んできて、改善されている部分というのは確かにあると思います。４番は、先ほどから、皆さんからも工夫できないかというご意見がありましたので、私は、ＰＤＦをつけて返していくことで、やっていくということで、ここで決められたらいいと思っているのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"今回のこの請願は、区民の方の率直なご意見で、本当に真摯に受けとめたいと、私は先ほどから言っていますけれども、この間の政治離れ、もうじきまた選挙がありますけれども、昨年の区長選挙の投票率２３.２２％ですよ。前回の区議の選挙が４０.５８％なのですよ。政治離れについて、どうですかね、皆さん、今の状況。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-017"},{"speaker":"渡部委員","kind":"質問","question":"先ほど、どこかの委員が、されてきていると、他人ごとのような言い方をしましたけれども、議会改革を自分たちでしっかりと進めてきているわけですから、今回は意見も十分に出していますので、このまま諮っていただいてよろしいかと思いますので、私たち内部にかかわることですので、意見陳述は、今回は必要ではないと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-018"},{"speaker":"つる委員","kind":"提案","question":"今、渡部委員からもありました、またこの間、各委員からそれぞれご意見も出たし、またそれぞれの趣旨について発言がされて、相当程度、皆さんのほうから確認がなされた。逆に、提案も含めてあったと思いますので、私たちとしてはこの陳述については必要ではないと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-019"},{"speaker":"石田（し）委員","kind":"意見","question":"我々も、今さまざま議論をした中では、私としては十分、今回の請願の思いも含めてのお話をさせていただきましたので、我が会派としても、今回は特段あえて陳述を聞く必要はないという判断をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本請願の中に、ぜひ意見を言わせていただきたい、意見陳述させていただきたいというのが盛り込まれている請願です。現状の議会においては、ここが不足しているという指摘が含まれていますので、ぜひ本委員会においてしっかり受けとめて、意見陳述をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-021"},{"speaker":"須貝委員","kind":"意見","question":"今回、品川区議会改革に対して、このような請願を出していただきまして、本当に、逆に私なんか、ありがとうありますと言いたいと思います。品川区議会もどんどん変わっています。ただ、今回の請願に関しては、申しわけありませんが、私としては、この趣旨に沿いがたい、ちょっと違うということで、これには賛成できないということ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-022"},{"speaker":"渡部委員","kind":"意見","question":"この間、議会改革をしっかりと各議員それぞれ会派、個人でしてまいりました。されていません、してまいりました。であれば、これが採択できるのか、採択できないのかということであれば、私たち既にやっているところもありますし、今の説明の中で、なかなかできてこないところもある。そのようなことを鑑みますと、結論を出して、不採択ということでお願いをいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-023"},{"speaker":"つる委員","kind":"質問・要望","question":"今日、結論を出す。そのうえで、この請願については、この請願趣旨の中の２にもありますが、会議規則の中で明記されて、紹介議員の説明を求めることができると、また求めに応じなくてはならないとある中で、先ほど須貝委員の質疑の中でありましたが、議会運営委員会の中にも、その紹介議員が属する会派の代表として出席をされて、応分の趣旨を踏まえたご意見があったかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-024"},{"speaker":"石田（し）委員","kind":"提案","question":"結論を出すで、先ほどから我が会派の意見というのはお伝えをいたしました。今回の請願の趣旨においては、既に取り組んでいるもの、また現状として難しいもの、そういった内容が書かれていまして、さらには、先ほど事務局長のほうからも、我々が提案をしている工夫の中でやっていただけるような話もあったので、そういった意味では、既に十分に対応されていると思っていますので、不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本日、結論を出すということで、態度ですけれども、区民参加の区政を進めていく意味で、今の対策は大変不足をしていると思います、足りません、区民が不満に思っていられるのは当然だと思っています。区民に開かれた議会、議会の傍聴の促進とか、議会の情報の公開、また、広報活動など促進を求めているこの請願は当然と受けとめています。採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5140#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":22925,"voices":51}},{"id":"h27-20150526-7","meetingId":"h27-cm05","date":"2015年5月26日","dateIso":"2015-05-26","committee":"厚生委員会","time":"午後 ３時０５分～午後 ３時５２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５０号議案 品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第５０号議案 品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この改定によって影響を受ける人数、第１段階と第２段階でそれぞれ教えていただきたいということと、今この対象になる方についてお知らせというのがどういった形で送られているのか、もとの０.４５で送られているのか、０.４で送られているのかという確認ですね。この改定に当たって、国から入ってきたお金というのが幾らなのかということをお答えいただけますか。","respondent":"永尾高齢者福祉課長","answer":"国から入ってくるお金につきましては、こちら、政令に基づきまして、国庫負担金が２分の１、都が４分の１、区が４分の１ということで補填されるということになっておりまして、まだ金額については確定はしておりません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"前期、第五期のときに既に０.４の保険料率だったと思うのですけれども、それで、今回第六期のときに、そのまま維持して０.４のままで行って、そこに国の軽減の額が０.０５入ってくるということで、０.３５にすることができなかったのかという、そこの考え方をお聞きしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"そうすると、その上の方の、第７から第１４段階の方が納得して保険料を納めていただかないと補填もできない状況になりますので、こういうことも考えながら料率というのを定めているものです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"そういった説明でわかりました。そこの考え方はいかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"一方、今説明しているのは第一号被保険者のことですけれども、第二号被保険者の方はほとんどサービスを利用していないで毎月お金を支払っているわけですから、そういう方からも補填されている制度ということを考えますと、低所得者だけを見て変更するというのは。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"意見","question":"第１段階、第２段階の方で非課税の方もいらっしゃって、税金はかからないけれども、この保険料はかかってくるということになっておりますので、やはり大きな負担になっていますので、この軽減と、やはり所得に応じた保険料の支払いというのが必要になってくると思いますので、さらなる、今２,０００万円にとどまらず、ほかの区でもやっておりますので品川区でも取り組んでいってもらいたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-004"},{"speaker":"横山委員","kind":"質問・要望","question":"１点ご質問させていただきたいのですけれども、今二号被保険者の方の話が出たのですけれども、ほとんどの方が掛け捨てというところで、サービスを利用されていないという状況があります。お願いいたします。","respondent":"永尾高齢者福祉課長","answer":"区といたしましては、国の率をそのまま横引きしまして、現在のというか、今回ご議論いただきます料率からさらにその同じ率を差し引いた料率にしようかというふうに考えているところです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"やっぱり議会は議決をしていくわけで、そこら辺のことを踏まえるのであれば、資料は普通の委員会でもいち早くということはよく言うわけですから、これはやっぱり少し配慮をしていただければなと思っています。私はそこはやっぱり説明をしていくべきだろうと思うし、そこはもう一度二号被保険の方々にも、そこら辺の点は配慮をする。","respondent":"永尾高齢者福祉課長","answer":"２つ目のこの条例の改正、平成２９年度までというふうにしておりますけれども、消費税１０％の見込みがあるのであれば平成２８年度まででというようなご意見でございましたけれども、確定しているのであれば平成２８年度までというふうに行いますけれども。","voiceIndex":14,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"意見","question":"お願いだけしておきます。最初制度ができたときはそういう話もあったけれども、私が思っているのは、まさに今おっしゃったように、どうしても高齢者が増えてきていると。そういうことにはならないわけだから、今の段階では。それは今のこの制度の中でしっかり区が説明する責任があると思うので、そこについてはお願いだけしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほど、財源の問題なのですけれども、この０.０５の軽減率のところで、幾らになるかというのはまだわからないということなのですけれども、その割合が国が２分の１、都が４分の１、区が４分の１という説明があったような思いがしたのですけれども、そこのところがよくわからなくて、私は国から全額来るのかなというふうな思いがしていたのですけれども。","respondent":"永尾高齢者福祉課長","answer":"保険の制度の仕組みの中で、公費の部分を増やすという考え方になっているので、そのルールにのっとって２分の１と４分の１と４分の１というふうになっているものです。","voiceIndex":17,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そういうところからすれば、特に住民税非課税世帯、非課税者の方、非課税世帯、特にここのところが本当に大変な状況というのがあると思うのですけれども、介護保険料も国保料も後期高齢者保険料もどんどん上がるばかりという状況の中で年金が引き下げられてという、そういう中で。","respondent":"永尾高齢者福祉課長","answer":"それで、消費税１０％になったときの料率を考えますと、低所得者、段階１、２の方は０.２５になる。それで、第３段階が０.３、第４段階が０.６５になるという見込みが出ているところです。","voiceIndex":19,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"所得の本当に、品川でいえば２,０００万円を超えれば、どんなに所得があろうと同じ金額、１７万８,０８０円ですか、こういう形になるわけですけれども、私はもっとここのところは多段階化も考えて、低所得者の方の引き下げというふうなところも検討していただきたいというふうに思っているところです。","respondent":"永尾高齢者福祉課長","answer":"区は区独自の部分をきちんと見ていかないと、やっぱり将来継続してきちんとしたサービスが受けられるような安心感というのが必要ですので、その辺はニーズも把握しながら、ご意見もお聞きしながら、これからも考えていきたいと思っています。一般財源の投入の件です。","voiceIndex":21,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点では、私は改めて、２,０００万円以上の方が８００人ということで聞いておりますけれども、ここの先をさらに検討した場合どうなるのかという試算をぜひともしていただいて、示していただきたいというふうに思っているところです。それからもう一つ、６５歳以上の方の基金についても、さらなる活用もぜひともお願いしたいということを意見として述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認をします。私の考え違いだったら言ってください。そうなってくるときに、基準額が多くても軽減していくといったって、例えば低所得者対策としても、それはなかなか見合う形にはなっていかない。このままいけば制度がそうなってしまう。そういうところが今の話でもなかなか聞こえないから、改めてそこのところは聞きたいなというところがあります。","respondent":"永尾高齢者福祉課長","answer":"国のほうもそういうところはきちんと認識はされておりまして、保険者の裁量のきく部分というものも増やしてきているところですので、やっぱりそういうものもうまく活用しながら区の実態に合わせた制度にしていきたいというふうに思っております。","voiceIndex":24,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"資料１の改正の趣旨で、これを趣旨と言っていいと思うのですが、今までの説明の中で、今回の措置は低所得者対策なのだというお話があるのですけれども、国からそのような目的、趣旨でしっかりお話が来ているのかどうかということの確認、また、そのほかに何か、国から聞いている趣旨、国の目的があるのであれば教えていただきたいのが１つです。","respondent":"永尾高齢者福祉課長","answer":"それで、その予算審議が、国会のほうの事情がありまして４月にずれ込んだということで、本当はもともとは３月の末までに予算が可決するという見込みを立てて、区のほうでも立てていたし、それを見込んで、実は予算のほうも、平成２７年度の当初予算のほうも。","voiceIndex":26,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"なるほど、わかりました。いずれにしても、低所得者の方々のための保険料率の今回の改定ということで、ましてや消費税率の増税分を充てているという本来の目的に沿った改正ですので、財源はしっかり確保できているわけですから、また介護サービス、地域包括ケアという考え方もありますので、またしっかり今年度も事業を進めていただきたいなと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3414#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":14191,"voices":41}},{"id":"h27-20150526-9","meetingId":"h27-cm05","date":"2015年5月26日","dateIso":"2015-05-26","committee":"文教委員会","time":"午後 ３時０５分～午後 ４時２１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４９号議案、平成２７年度品川区一般会計補正予算","agenda":"第４９号議案、平成２７年度品川区一般会計補正予算","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"今回、５月に承認後、保育施設の計画というようなことで考えました。もう一つ、昨年、待機児童数の４割程度と言いましたか、半分近くと言いましたか、荏原地域だったと聞いておりますけれども、この傾向は今後も続くのか、それとも何らかの対応というのでしょうか、そういうものは何かお考えがあるのか、緊急対策を続けてきましたけれども、その成果等をあわせて教えていただければと思います。","respondent":"今井待機児童対策担当課長","answer":"２点のご質問です。初めに、待機児童の数ですが、平成２７年４月１日付の待機児童の数は２１５名です。平成２６年度の当該年度の数が１２８名ですので、８７名プラスされまして、ことしの４月１日は残念ながら待機児童数は２１５名で増加しております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"浅野委員","kind":"提案","question":"地質調査については問題がないという結果が出たということですけれども、劇団四季のほうがたしか問題があったと聞いておりますけれども、そのすぐ隣ということもあって、多分、綿密な調査をされたのではないかと思いますけれども、それでも大丈夫と判断されたかと思いますけれども、その点、何か問題があると、小さい子どもたちですから、影響も大きいかと思いますけれども。","respondent":"今井待機児童対策担当課長","answer":"地質調査の関係です。劇団四季が実施したときには、これは民間の劇団四季側が調査したのですが、出たところが、今回の施設計画と真反対のＪＲの駅側のところです。路線のほうに１カ所出たと聞いております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"最終は６月中旬ということですけれども、変わらないデータという形で、結果としていただけると伺いました。そのようなことは想定されているのか。５年を超えてまだ待機児童の解消ができていないというような状況については、最長でどの程度、これは建物を建てた結果としていつまで使えるのか、そこら辺も教えていただけたらと思います。","respondent":"今井待機児童対策担当課長","answer":"今後、そこのあいている部分、特に４歳児・５歳児についてどのようにやっていくかは、事業者とともに検討させていただきたいと考えています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"浅野委員","kind":"確認","question":"定員が３００人ということですと、必要な保育士についても地域に確保しなければならないのではないかと思いますけれども、どのぐらいの保育士を予想されているのか、また、保育士の確保はどのような方策を考えられているのか、それとあわせて、大丈夫でしょうねということを確認しておきたいと、そのように思います。この点についてどういう方策を考えられているか教えてください。","respondent":"今井待機児童対策担当課長","answer":"保育士確保につきましては、これは運営事業者をこれから公募型プロポーザルでやっていきますが、一番の肝でございまして、保育士確保は既に平成２７年度の予算で保育従事職員等の家賃借上げ支援につきましてお認めいただいたところですが、この園舎の借上げ支援のほかに。","voiceIndex":12,"id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"どうもありがとうございました。保育士が足りなくて、保育のサービスが減ってしまうということがくれぐれもないように、ぜひともいい事業者を選定していただければと思います。引き続き荏原地域にも尽力いただければと要望いたしまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"質問","question":"浅野委員から先ほどお話があった保育士の確保ですけれども、私は小児科医なので、むしろ医院とか医療関係がどうなのかが心配な点がありまして、その辺のご検討はどうなのか、この２点についてお伺いしたいのですけれども。","respondent":"今井待機児童対策担当課長","answer":"ただ、今後また改めていろいろ協議のご依頼をしていく中でご検討いただく部分はあるかと思いますので、引き続き協議は進めさせていただきたいと思います。","voiceIndex":15,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"敷地面積が約１,６３６m2ということですけれども、駐車場としてはもう少し広いと思いますが、この全体の広さをお伺いしたいと思います。それと園庭があるのか、ないのかを伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"それからもう一点ですが、園庭についてですけれども、こちらは少し中庭のような空間を設けまして、そこでプール等の水遊びはできる空間は確保していきたいと考えておりまして、それが予定では大体２００m2程度と考えておりますが。","voiceIndex":17,"id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"中庭というぐらいのプールが置けるような２００m2ということで、３００人の定員で２００m2だけというところでは、園庭はないということでいいんですね。ですので、もともと２,７００m2あるのでしたら、そこを６割使ってということですけれども、全部使うことはできないのでしょうか。伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"駐車場も含めてという形ですけれども、ここの駐車場をつくった経緯は、大井町の全体の利用の中でイトーヨーカドーができる、いろいろな商業施設ができる中で、近隣の商業施設の方々の利用も含めて駐車場にしてほしいというご要望をいただきながら検討を進めてきたものですので。","voiceIndex":19,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そもそも劇団四季の駐車場ということで、そんなに劇団四季も入れるだけ、劇団四季の定員がどれくらいかは私もまだ調べていないのですけれども、それにしても広い駐車場だったので、あちらにこの商業施設を使う人の駐車場を一緒にして、そして、今ある駐車場を保育園として使えるという工夫もして屋外遊戯場をつくっていく検討もしていただきたいと思いますけれども、いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"そこはＪＲから伺っているところによりますと、ＪＲ側が駐車場として貸している用地だと考えていますので、民間事業者はそれぞれの考え方の中で運営しておられますので、品川区としては、今あります区有地の中できちんと対応してまいります。","voiceIndex":21,"id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこを何とか工夫してというところで検討をお願いしたのですけれども、ＪＲとも協議をしていくとか、そういったことは子どもたちの屋外遊戯場は切実なお父さん・お母さんの願いですので、これを設置していって、そして３００人の定員の保育園をつくっていくという、保育園に屋外遊戯場がなく、そして、公園まで子どもたちが歩いて、そして保育士さんたちが連れていってというのは。","respondent":"今井待機児童対策担当課長","answer":"先ほど、この施設自体が暫定施設と申し上げました。ここのエリアは再開発の事業で全て進めているエリアです。そういった中で、さらにＪＲの用地を借りて行うことは、区としては難しいと考えております。","voiceIndex":23,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点、その屋外遊戯場でお伺いしたいのですけれども、園庭がないので、代替地として公園という位置づけで、そこの規定は詳しくあるのでしょうか。指定管理者制度を使っているのですが、ここはなぜ指定管理者でなく民間委託であるのかというのと、委託の内容がどういった中身で、今後チェックができるのかどうか、そこをお伺いしたいのが２点目です。","respondent":"今井待機児童対策担当課長","answer":"今後の待機児童対策ですけれども、品川区の子ども・子育て計画でも既に発表していますし、本年度の当初予算でも既にありますが、来年の４月に向けて私立保育園につきましては４施設開設するということ。","voiceIndex":25,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今後の計画ですが、先ほども子ども・子育て計画を着実に進めていくということだったのですけれども、現実的に子ども・子育て計画に上がっている数字を追いかけていけば、ここのところ増えている需要に対応できるのかというところ、よその区の例を見ると、実際に伸び率よりも多目に実際に膨らんできているところにおいては、都市部であるというところ、多目に予測を立てながら。","respondent":"今井待機児童対策担当課長","answer":"ですので、私どもも、公定価格に示された運営費は事業者に運営委託費としてきちんとお支払いするとともに、大規模保育特有の人数による主任保育士の加算ですとか、そういうことも含めて検討してまいりたいと考えています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"委託の件ですけれども、実際に指定管理者の制度だと、事業者の把握している職員の人数や、賃金、待遇は、求めれば出て、議会の中で議論できるのですが、これからどちらになるかわかりませんけれども、プロポーザルで受けた民間の事業者になった場合に、区立の認可保育園ということで、どこまで議会が求められるのか、そこの点を教えていただきたい。","respondent":"今井待機児童対策担当課長、金子子ども未来部長","answer":"今後、さらに保育需要の伸びが想定される部分もありますけれども、来年につきましては、この数で一定の数の待機児童の解消ができるものと見込んでおります。しかしながら、今回、皆様ご案内のとおりだとは思いますが、なかなか保育士が確保できないというところから、国のほうでも１人平均９,０００円のアップを盛り込んでいる考え方があります。","voiceIndex":29,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"今のところ、ありがとうあります。まだよくわかりませんけれども、これは事業者に１人を雇うところで例えば国から９,０００円とか、そういった中身の算定になってくるわけでしょうか。もう少し詳しく教えてほしいのと、その辺がきちんと働く労働者に、保育者に回るようなチェックもできるのか、その辺も教えてください。","respondent":"金子子ども未来部長","answer":"先ほど申し上げましたとおり、私どもの算定としては、今、そういった賃金のさまざまな補助を踏まえて計算していくということはありますけれども、最終的には、例えば事業者については年齢構成なり、あるいは経験。","voiceIndex":32,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひしっかりとチェックをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-015"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"何点かまとめてお伺いします。１つは、入り口が皆さん方ご承知のように１カ所しかないわけですから、そこはＪＲの職員と、それから劇団四季のお客様が使うと。ただ、逆に言うと品川区は５年間それを認めてしまったのかなとなると、かえって違うメッセージが出てくる可能性があるので、その辺はどういうお考えなのかということをまず確認をさせていただきたいと思います。","respondent":"今井待機児童対策担当課長","answer":"詳しくは、行財政改革または都市開発の所管にはなりますけれども、あくまでも区としては暫定施設としまして一部の利用という形で考えておりますので、大井町全体の再開発の気運といいますか、その検討を後ろ向きにするものでは全くございません。","voiceIndex":35,"id":"exchange-016"},{"speaker":"伊藤副委員長","kind":"質問","question":"単純な話です。それから、仮に５年間たった後、さまざまな理由で再開発が進む可能性が出てきたと。これが例えば５年先なのか７年先なのかわからないけれども、いずれにせよ、品川区が今おっしゃったように進める再開発の大きな方向性の中の施設なのであるから、それがなくなるときに、そこにある子どもたちを優先的にどこかの園に入れていくなり、検討していくべきだと思いますが、いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"今も保育園の周りには黄色い看板といいますか、そういうものを立てて注意喚起するということを少し手前からやっておりますので、それも含めて検討していきたいと考えています。","voiceIndex":37,"id":"exchange-017"},{"speaker":"伊藤副委員長","kind":"質問","question":"品川区がＪＲと協議をしてつくったのでしょうから、ＪＲもそのことを理解している。いろいろ場所もいいところですよね。だから、そういうふうに、せっかくこの場所につくるのであるなら、先のことも考えて、なかなかお答えしにくいとは思うのだけれども、対処すべきだと思いますが、いかがでしょうか。","respondent":"金子子ども未来部長","answer":"ただ、このエリアの中で、大井町の駅に非常に至近なところですので、そういう意味では品川区全体の待機児童数の動向を見ながら、このエリアの中でどのくらいの保育需要があるか、こういうものは今後の推移も含めてきちっと把握した上で。","voiceIndex":39,"id":"exchange-018"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"開設期間のところだけ確認しますけれども、とりあえず５年間、とりあえずという言い方はおかしいけれども、５年間ということで、当然、協議がさまざまな形で進む可能性も出てくる可能性はありますよね。つくるわけですから。","respondent":"金子子ども未来部長","answer":"そういう意味では、そういった施設をあわせて、将来どういうふうに構想していくのかも非常に大きなポイントだと考えていますので、そういう意味では少し広目なところで広範に考えていく必要があるのではないかと考えています。","voiceIndex":41,"id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認させていただきたいと思います。１歳から５歳の子どもの入園の大まかな受け入れの数を教えていただきたいのと、あとは先ほど伊藤副委員長からもありましたが、登園の安全性の確保という部分でいうと、今、ＪＲの広町住宅の跡地で取り壊し等がある中でそういった部分もしっかり配慮して、どうやって安全性を確保するのかというところを教えていただきたいと思います。","respondent":"今井待機児童対策担当課長","answer":"公募期間は、もし明日アップできましたら、６月１０日に締め切りをいたしまして、説明会が６月１５日を予定しております。さまざまな書類審査、そしてヒアリング審査などを含めまして、７月中旬には事業者を決定してまいりたいと考えております。","voiceIndex":43,"id":"exchange-020"},{"speaker":"大倉委員","kind":"確認","question":"ぜひ煙とか、ほこりという部分では、子どもたちには内庭が２００m2あるということで、そういった部分の配慮をお願いしたいと思います。１点、確認ですけれども、これを延長したときに、先ほど園舎のリース料が１カ月１,０００万円ということだったのですけれども、これはだから１カ月ごとに延長期間分だけ増えていくということでしょうか。","respondent":"今井待機児童対策担当課長","answer":"今回のリース契約は、全ての建物の設計から運営時のメンテナンス、そして解体工事も含めてのメンテナンスになりますので、もし期間を延長した場合には、再リース契約を結ぶ形になると考えておりますので、そのときまた適切な金額を算定してご審議いただければと考えています。","voiceIndex":45,"id":"exchange-021"},{"speaker":"高橋委員","kind":"質問","question":"先ほど、土壌の汚染がないということでゴーサインが出たということですが、ここに出てきた増設計画は、土壌が大丈夫だということになってから計画を立てられて、それで今回、こういった形で議案として出されたのだとすると、どれぐらいの期間でこういう計画を立てられたものなのでしょうか、お尋ねしたいです。","respondent":"今井待機児童対策担当課長","answer":"一般的に貸し付けのほう、私ども、実際に調整を始めたのは、今回の当初予算の事前調査経費を実際に提案する検討の中で始めてきたものですので、１２月後半ぐらいから検討を進めてきたものです。","voiceIndex":47,"id":"exchange-022"},{"speaker":"高橋委員","kind":"意見","question":"今のご答弁からすると、平成２７年度の予算の中でこういったことが入っていて、それで幸いにも土壌汚染がないということでゴーサインがすぐそこで出ているという話が、平成２８年４月に開設しようという、私は３００人のものをつくることは賛成で、大変ありがたいことだと思って、それの前提ですけれども、ここで出てきたのが私はわからないので、それだけ準備されていたとすれば、そういう計画があるのだと。","respondent":"金子子ども未来部長","answer":"今回、一番最初に出発してきたのは、先ほど課長が申し上げたところから出発しているところは間違いのないところですけれども、まず、６月の終わりまで貸しているというところから、本来だと地質調査もそれ以降でなければできないことになるわけです。","voiceIndex":49,"id":"exchange-023"},{"speaker":"高橋委員","kind":"質問","question":"経緯を説明していただいてどうもありがとうあります。もう一つは、ここの保育所が、今、新制度のお話がありましたけれども、新制度という言い方よりも認定こども園というか、その仕組みの新しい中のではないとしていったその理由と、それを含めて全体のほかのものも含めて、もう新制度とは言わないですけれども、そちらの園についてどのような進め方をしていくのでしょうか。","respondent":"今井待機児童対策担当課長","answer":"今後の認定こども園の考え方ですけれども、今、私立保育園についても認定こども園に移行したいという希望を寄せていらっしゃるところはありますけれども、実際にポピンズナーサリースクール西五反田が認定こども園に移行する形になったわけですけれども。","voiceIndex":51,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"しかしながら、園庭の問題も先ほど取り上げましたけれども、大規模化と園庭のない保育園ということでは、子どもたちが日々生活をする成長の場ではいかがなものかと、改善を求めていきたいと思います。委託の問題でも、区立の保育園の中でワーキングプアを生んではならないということで、賃金・待遇の面の把握をぜひしていただき、私たちが知りたいときにはぜひ答えていただきたいと思います。賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4852#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":21931,"voices":65}},{"id":"h27-20150527-5","meetingId":"h27-cm05","date":"2015年5月27日","dateIso":"2015-05-27","committee":"総務委員会","time":"午前１０時００分～午前１０時４８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"３月３１日ぎりぎりということですけれども、そうなった背景や要因について伺いたいと思います。冒頭の説明で経済状況を踏まえてという話がありましたけれども、国の法律の改正で、区がということでは決してないですけれども、３月３１日ぎりぎりになったその背景や要因、経済的情勢を踏まえてとはどういうことか、そこをご説明いただきたいと思います。","respondent":"黒田税務課長","answer":"この１年延期ということが決まりましたのが、平成２６年の暮れに、国のほうと申しましょうか、政府の中で、経済状況等を勘案したときに、平成２７年度の税制改正の検討をそのときにされていたわけですが、二輪車については既に税条例改正した自治体がほとんどだったわけですが。","voiceIndex":5,"id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"１年見送りの内容については、十分わかります。それで、品川区の入りの部分、総額で平成２８年度以降の額と、現在の額と、数字の単価で違いはわかるのですけれども、区全体でどのくらいの差額というのでしょうか、どのくらいの違いが出てくるのか、大まかでつかんでいるのはどのような感じなのかを教えてください。","respondent":"黒田税務課長","answer":"平成２７年度の軽自動車税の納税通知は５月１１日に発送させていただいておりまして、その課税台数をもとに延期がなかったということで影響額を算出しまして、台数としまして全部で２万４,３５０台、金額としましては２,８１２万円余の金額が。","voiceIndex":7,"id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"わかりました。すみません、細かいことですけれども教えてもらいたいのは、車種区分で「原付」と書いてありますけれども、５０ｃｃ以下からミニカーまでの４種類について区分が原付になっていますけれども、表示はこのような仕方なのですか。","respondent":"黒田税務課長","answer":"こちらの法律上の区分ですけれども、原動機付自転車というのは１２５ｃｃ以下のバイクと５０ｃｃのミニカーがありまして、これが排気量ごとに５０ｃｃ以下ですと白いナンバー、５０ｃｃを超えまして９０ｃｃ以下ですと黄色いナンバー。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"今回の条例改正、軽自動車税の標準税率の引上げをするのを１年間延期した。現実論はどうなのですか。今まで伸びていた軽自動車に対して、本来なら税率を上げてもいいわけですが、上げられないということは、やはり消費が落ち込んでいるという認識で捉えていいのでしょうか、それによって今回見送ったというようなことが中身なのでしょうか。その辺、ご見解をお聞かせください。","respondent":"黒田税務課長","answer":"平成２５年１１月に報告がなされているのですが、そもそもは自動車に区分される１,０００ｃｃクラスの車と軽自動車、６６０ｃｃですが、環境に与える負荷ですとか、全体の税制の体系としてどうなのかという議論がありまして、今回。","voiceIndex":11,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"１点だけ。区民の消費の動向やそういうものの影響も大きな要因だったのですか。それについて先ほどお聞きしたのですが、どうなのでしょうか。","respondent":"黒田税務課長","answer":"消費という段階は、税の立場で言いますと、バイクの免税額が１,０００円と２,０００円という形で１,０００円違うところが、どの程度新たにバイクを買い替えるというところや、今持っているバイクを１年持っているところの消費動向に影響するというのは。","voiceIndex":13,"id":"exchange-005"},{"speaker":"あべ委員","kind":"意見","question":"４月１日からの条例改正ということですけれども、これの引上げが決まり、その後、延長が決まりということで、事務的には二度手間、三度手間になっている。それから、例えば納付などの書類などについても、またつくり直しのようなことも事務的には発生すると思いますけれども、そういった直前での変更によるコストは算出されていますか。","respondent":"黒田税務課長","answer":"課税する事務では、税率はコンピューターでデータベースに登録されていますので、そこを変更するという意味では大きなコストはかかっておりませんが、延期が決まったということで広報紙に記事を載せさせていただいたりという事務は発生しておりますけれども。","voiceIndex":15,"id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"国の姿勢について自治体としても、何か最近どうも年度末にバタバタと成立してということが多いように感じるのですけれども、こういったことに対しては地方としても全体として国に対して言っていくというようなことは、他の自治体と話は出ないのでしょうか。言われるままにバタバタ尻拭いをしているような印象を受けるのですが、いかがでしょうか。","respondent":"黒田税務課長","answer":"ただ、それを受けてどのように国政の場で判断されるかは、あくまで国の判断によりますので、私どもとしましては、法律が成立した以上、それに合わせて事務を行うという適切な事務をしておりますので。","voiceIndex":17,"id":"exchange-007"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうした要望活動があるようであれば、なおスケジュール的なものについても、こういったものは突発的なことではないわけで、人が決めるものですので、そういったことも自治体の事務ということも念頭に置いてスケジュールを組んでいただきたいというふうなことも加えていただければと、これはご検討いただきたいということで要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、税制の改正ですから、とても重いものがあると思いますので、そういう意味では、直後の議会にかけるのは当然ですけれども、何らかの情報提供や連絡があってもよかったのかなという点は思います。前回の任期が４月末ですので、もちろん区議会は選挙をやっていたことはありますけれども、税制の改正ですので、それは重みがありますので、その点は工夫していただけたらと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-009"}]},{"id":"topic-02","title":"第４９号議案 平成２７年度品川区一般会計補正予算","agenda":"第４９号議案 平成２７年度品川区一般会計補正予算","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"同時に、この時期なので具体的な数字はまだ確定していないかと思いますけれども、平成２６年度決算で基金の合計が７７７億円だったのですけれども、現時点では増える見通しなのか、どれぐらいなのか、そういうところも見て財政調整基金の繰入金に充てたのか、その辺の品川区の財政状況も伺いたいと思っていたので、平成２６年度の基金が増える見通しなのか、今どれぐらいの状況なのか。","respondent":"秋山財政課長","answer":"ということで、繰越金が正確に把握できないということで、今回、繰越金を財源ということでは控えておりまして、財政調整基金が適当であると判断したです。現在の基金の見通しですけれども、出納閉鎖期間ですので、詳しいことはまだ出ていないというところが今言える部分です。","voiceIndex":33,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"現在の見通しだけでもと思ったのですけれども、もし状況が説明できたら伺いたいと思います。つまり、何が伺いたいかというと、いつぐらいからこの検討を始めていたのか、その辺の経過をご説明いただきたいというのが１つです。今回、こういう形にしたのはなぜなのか、経過も含めてご説明いただけたらと思います。","respondent":"秋山財政課長","answer":"区の方針があったのか、検討はいつからかですけれども、ご承知のとおり、今、計画をしている土地は駐車場にしているイトーヨーカドーにお貸しをしているということで、これは本年の６月末までという契約の期間でございました。","voiceIndex":35,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"所管からはいろいろな要望があるけれども、最終的な判断もあるでしょうから、そういう意味で、昨年来から検討していたその中身が、区の土地、民間の土地、国有地、どういうスタンスで検討を進めていったのか、ほかに検討しているものがあるのか、検討の結果だめになったものがあるのか、そこの中身を伺いたいと思います。この状況の判断というのも誰がどういう基準で行うのかを聞きたいと思ったのです。","respondent":"柏原企画調整課長","answer":"具体的なものに対しては、こういったところはどうだろうかと所管部門で調べてきて、ここはどうだとか、また、我々企画部門であるとか総務部門、そういう情報を持っているところは、相互に連携しながらそれぞれに検討している。","voiceIndex":37,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後にもう一つだけ。せめて駐車場部分だけでもＪＲの土地になれば、今の保育園の隣に園庭はつくれるわけなので、民間にもぜひとも区の事情を理解していただいて協力願えないかと、そういう働きかけは今後もできないものなのか、そこを伺いたいと思いますけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"１点目、区立認可というお言葉が出ていますが、我々は待機児童対策を主眼にいろいろな手法、総合的な手法ということでこれまでも考えてまいりましたので、そういった中で待機児童対策をするためにはどうしたらいいのかという中での検討ということで。","voiceIndex":39,"id":"exchange-013"},{"speaker":"本多委員","kind":"質問","question":"早期開設に向けて前倒しにする対応は、非常に柔軟ですばらしいと思います。それで聞きたいのは、園舎の借上げですけれども、いろいろ検討されてこういうやり方に決まったのだと思いますけれども、リースなので、プレハブですか、どのくらいの質のものなのか、それとあとは建設したり買い上げたほうが、その辺の検討はどうだったのかを教えてください。","respondent":"秋山財政課長","answer":"リース工法であれば、設計、それから施工、期間中のメンテナンス、解体費用まで含めて１つの契約でできるのも一つの利点ですから、その辺のことを総合的に勘案して、今回、リース契約をしていくです。","voiceIndex":41,"id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"先ほど来、総合的に判断ということでお話しいただいたのですけれども、５年を目途にということですけれども、その目途が過ぎた場合に総合的判断によって判断基準として、今、総務委員会ですが、やる、やらないという部分で財政的なものを優先させるのか、それとも待機児童の対策として、どちらのほうを優先しながら判断されていくのか、そこのところをお伺いしたいのですが。","respondent":"秋山財政課長","answer":"もちろん、一方、財政的な負担についても、大きな要因であることは承知していますけれども、そのどちらか二者択一ではないのではないかとは考えておりますし、もちろんそれは両方ともある程度大きなファクターの中の２つだとは考えておりますので。","voiceIndex":43,"id":"exchange-015"},{"speaker":"あべ委員","kind":"確認","question":"金額の中で、今、解体まで含めて一括でというお話がありました。ということは、この園舎借上げの全体の中での６億２,０００万円、この中に解体費用も入っていて、全体を月割りすると１カ月分が１,０００万円になるという計算でよろしいのでしょうか、ということをまず確認させてください。","respondent":"秋山財政課長","answer":"この６億２,０００万円ですけれども、１カ月１,０００万円で、今の想定では６２カ月という形で、総額で６億２,０００万円という形になってあります。１カ月１,０００万円という、そういう計算です。","voiceIndex":45,"id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"先ほど来、一応５年間と年頭に置いてはいるけれども、状況によってそれが延長される可能性もあるというお話が出ております。延長された場合は、これは月１,０００万円でいくのですか。あるいは、でも、解体費用自体は期間が延びると総額が上がるわけではないので、５年間を超えていくと、月額は下がって当然だと思いますが、その辺は契約の中でどのような形なのですか。","respondent":"秋山財政課長","answer":"その分、既に部材についてはお金を払っていますので。ほかのリース物件の例によると、大体半額ぐらいにはなるのではないかと。いろいろな使い勝手ですとか、いろいろリース会社によって違いますけれども、なるのではないかという想定はしております。","voiceIndex":47,"id":"exchange-017"},{"speaker":"あべ委員","kind":"質問","question":"５年間を過ぎたところで、一旦、契約更改のような形になって、その中で金額が変わっていくということでよろしいのでしょうか。でなければ、５年後以降は幾らと数字で出ているのか、何らかそういうことかと思いましたが、詳しく教えてください。","respondent":"立川経理課長","answer":"こちらは延長を前提として契約しているわけではございませんので、前提としましては、その時点で協議して決めていくということになろうかと考えているところです。","voiceIndex":49,"id":"exchange-018"},{"speaker":"あべ委員","kind":"確認","question":"再開発の進捗を見ながらと言いながら、５年というのはかなりフィックスした期間と受けとめてよろしいのか、何か特別なことがない限り５年で閉じるというぐらいなイメージでの柔軟性と考えていいのかと、今、受けとりましたが、確認させてください。","respondent":"秋山財政課長","answer":"一応、５年間の期間ですけれども、契約上５年間ということは、当然フィックスしないと契約できませんので、終わりが決まっていなければ契約できませんので、５年間というのは契約上はそうなってありますけれども、先ほどからご説明させていただいたように。","voiceIndex":51,"id":"exchange-019"},{"speaker":"中塚委員","kind":"意見","question":"意見を述べて態度を述べます。しかし、５年限定でなく、待機児童解消に必要な延期やさらなる認可保育園の増設が必要だと思いますし、また、園庭の問題を含めて保育の質や人材の確保もしっかりと進めていかなければいけないと思いますので、根本的には認可保育園の増設をさらにしっかり進めていくことが大事だということを指摘して賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-020"},{"speaker":"あべ委員","kind":"意見","question":"私も意見を述べた上で態度を申し上げたいと思います。それから、品川区内最大の保育園となりますので、質の確保、運営面での配慮というものをぜひお願いしたいということ。それから、初の暫定保育園でもあります、開けるより閉めるほうがはるかに大変だと思いますので、その面でも公募者等々に問題や不利益が生じないようにということをぜひ留意していただいた上で賛成をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2014#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":14660,"voices":64}},{"id":"h27-20150527-10","meetingId":"h27-cm05","date":"2015年5月27日","dateIso":"2015-05-27","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時３３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5142#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":1345,"voices":11}},{"id":"h27-20150608-6","meetingId":"h27-cm06","date":"2015年6月8日","dateIso":"2015-06-08","committee":"区民委員会","time":"午後 １時００分～午後 ３時３３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"南委員","kind":"提案","question":"そういうので、私は急ぐべきではないということをぜひ言っていただきたいと思っているのが一つと、あと、これ、いろいろな情報が入るのですけれども、個人の１２桁の番号はもちろんですけれども、名前、住所、生年月日、性別、基本的な状況、この性別のところが今、国会でも問題になっているようで、性同一性障害でしたか、そういうことで、自分の心と体が違っていて、体は男性でも心は女性だとか。","respondent":"久保田地域活動課長、山崎商業・ものづくり課長、立木産業活性化担当課長、井浦戸籍住民課長","answer":"当然、区の掲示板ですから、空いたスペースに張ってもらうというものでございまして、張る際には区の掲示物をどかしてもらったりすると困りますので。景況調査の５１０事業所の対象ですけれども、これは無作為抽出ということで、毎回違う事業所に景況調査をお願いしているという状況です。就業体験事業の対象者になりますけれども、１回目は区民のみで行いました。２回目、３回目以降は区民、区民以外の方も対象としております。","voiceIndex":41,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、空いているところに張るのは当然ですけれども、そこに地元の町会からの要望があって、そういうものに取り替えてやっているのだということなのですけれども、ごめんなさい、私は区民委員会を何年かやっていなかったので、その情報は全然知らないで申し訳なかったのですけれども、認識を新たにしたいと思っていますけれども、そういう地域の要求のもとで取り替えているという。","respondent":"久保田地域活動課長","answer":"今、ふれあい掲示板のお話ですが、新しいふれあい掲示板はいわゆる旧、今まで使っていたものの下段の部分がございませんので、上の、上段の部分の中で張っていただけるように、申請等があったときには丁寧に説明をしてまいります。","voiceIndex":46,"id":"exchange-002"},{"speaker":"田中委員","kind":"質問","question":"１３ページの地域支援係のところですけれども、本当に新人なもので、そんなことも知らないのかと言われたらあれなのですけれども、区政協力委員というのは若い方はいらっしゃるのですか。","respondent":"久保田地域活動課長","answer":"区政協力委員ですが、町会・自治会長に委嘱をしているものですので、町会・自治会長の年齢に応じたものです。私どもでつかんでいるのが、町会・自治会長の平均年齢が、平均７２歳ぐらいということになってありますので、そういう方々で構成されているというものです。","voiceIndex":51,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"この区民の要望等を正確に把握して区政に反映させることとかも見て、この目的が、若い方の声というのはなかなか通りにくいということですか。","respondent":"久保田地域活動課長","answer":"この区政協力委員会に臨む前には、地域で準備会等で話し合いをされているということもありますし、町会・自治会の中でそれぞれの地域で抱えている課題について、区にこういう機会を通して直接物を言いたいということもありますので。","voiceIndex":53,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"もう一個。２６ページの3)ですけれども、地域環境実態調査、コンビニなどにある有害図書についてですけれども、これは陳列をきちんとしているとかいうことですよね。ただ、高校とか、学校が近いコンビニでも普通に並んでいるものとか、それは言えるのですか、ここに並べないでくださいとか、そういうことは。","respondent":"久保田地域活動課長","answer":"そちらのほうから警察や、また、東京都の所管のところからコンビニエンスストアとか書店に必要があれは指導しているといったものでございまして、直接的に地区委員が指導しているものではございません。","voiceIndex":55,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"要望ですけれども、有害図書が分かれているといっても、ちょっと仕切りがあって分かれているだけで、中身が見えないようになっていても表紙が結構過激だったり、過激な表現があったりとか、小学生とかもそういうものを見ていたりするので、なるべく違う場所に置いてほしいと思うのです。そういう要望をもしも出せたら、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-006"},{"speaker":"藤原委員","kind":"質問・要望","question":"事務事業概要なので、事務事業についてはよくわかるのですけれども、組織改正についてお伺いしたいのですけれども、今まで地域振興事業部の部長がお一人で、課長たちという形になっていて、私はそれでよくこの組織は動いているなと思っていたのですけれども、今回４月の改正で２つになったわけですね。何の意味があるのでしょうかと。","respondent":"安藤文化スポーツ振興部長、小川オリンピック・パラリンピック準備課長","answer":"もう一つは、２０２０年になくなるのかというご質問ですけれども、組織改正については専門的な部署が考えることになると思いますけれども、今私どもは２０２０年以降もレガシーということで、２０２０年以降も引き続き、継続していくと。私から４点目のご質問についてお答えいたします。区といたしましては、オリンピック・パラリンピックに向けての組織については、素早い対応をしてまいりました。","voiceIndex":65,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"なぜそんなことを聞くかというと、これもこの間伺った区民の方は団体だったのですけれども、自然食だとか、そういう自分たちで例えばおみそづくりだとか、お豆腐づくりとか、そういう自分たちで食を大事にして、そういう活動をしている団体のようで、つくりたいのだけれども必ずしも近くにある文化センターが調理講習室が設備されていなくて、３カ所ぐらいしかなかったのかな、八潮の地域センターと。","respondent":"間部文化観光課長","answer":"ただ、今いろいろなところで、例えば平塚橋等でも高齢者施設の建替えを行っているのはご存じのところだと思いますけれども、シルバーセンターについても多世代の利用ということも今検討されていますので、そういう中で文化センターについても今後改築のときには。","voiceIndex":68,"id":"exchange-008"}]},{"id":"topic-02","title":"少年少女スポーツ普及支援事業助成","agenda":"少年少女スポーツ普及支援事業助成","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"すみません。単純計算をして６６以上団体があった場合は、毎年与えられる助成がもらえる団体がかわっていくのかということと、それ以下の場合、予算に達成しない場合はこの予算の行方はどうなるのかということ。子ども全体へスポーツへの関心を持ってもらうようになるべく学校教育へのボールの設備の充実だったりとか、そういう強化もあわせて行うことが求められると思います。区のお考えを教えてください。","respondent":"池田スポーツ推進課長","answer":"事業が２０２０年のオリンピックで終わってしまうのか、それとも単年度で終わってしまうのかというご質問がございましたけれども、こちらはとりあえずは目的と趣旨ということで２０２０年のオリンピック・パラリンピックの開催に向けてということが書いてありますけれども。","voiceIndex":75,"id":"exchange-009"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（し）委員長","kind":"提案","question":"ないようですので、今後の委員会運営について私のほうから提案があります。本年の区民委員会におきましても、当委員会に係る所管事務の中から年間を通して協議していきたい課題、また常に意識しておくべき事項等について委員の皆様よりご意見、ご要望を聴取し、そうした課題、事項を本年の区民委員会のテーマに掲げ、所管事務調査および行政視察を通して具体性を深めていきたいと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2722#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":52154,"voices":91}},{"id":"h27-20150608-7","meetingId":"h27-cm06","date":"2015年6月8日","dateIso":"2015-06-08","committee":"厚生委員会","time":"午後 １時００分～午後 ３時５０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、生活保護の話があったのですけれども、品川区が、昨年度１５.６‰で、東京都が２２.１‰、全国でも１７.１‰ということで、なぜ低くなっているのかということ。それから、生活保護が、今年度から生活扶助費も下げて、冬季の加算も下げられるということで、この影響を受ける人数と、変わることによって、これからどうなっていくのかということをお聞きしたいと思います。","respondent":"伊東生活福祉課長","answer":"ご質問のあったところですけれども、生活保護の相談があった場合は、こちらのほうとしては、相談者の実情をよく聞いたうえで、該当すれば、当然生活保護ですし、そうでなければ、今で言う生活困窮者自立支援法のほうでの支援を視野に入れつつ、対応しておるところです。","voiceIndex":49,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"生活保護のところでは、国会の厚生委員会でも、付帯決議で周知をするようにということになっておりますので、ぜひ、広く周知をしていただきたいと思います。そこで、障害者が、エレベーターが停止して帰宅できないということがありまして、福祉避難所の体制等、そういったときの受け入れの要望がありまして、今、どういうふうに考えていらっしゃるかをお聞きしたいと思います。","respondent":"永尾高齢者福祉課長、大串福祉計画課長、中山障害者福祉課長","answer":"在宅介護支援センターのほうでご相談あった方については、ケアマネージャーが個別で紹介をしているという状況になっております。緊急通報システムの周知ですが、こちらについても、ホームページ等々を活用して周知を行っておりまして、今現在、４月、５月の実績。なかなかに難しいところではあるかとは思うのですが、日中であれば、エレベーターに乗れないときに、どこかの、例えば区のいろいろな施設でも結構ですし。","voiceIndex":51,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、一人の障害者の方が家に帰れなくて、野宿になるのではないかみたいな事態にもなりましたが、一応、知り合いの方のうちに上げてもらって何とかなったということだったのですけれども、これからこういったこともあると思いますので、ぜひこれも考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"意見","question":"そこら辺の考え方は、ソフトについては今年決めるという話ではないわけですが、だけれどもやはり、この三、四年以内にはその部分はやっていくべきだろうと思っているのですけれども、感覚的なものは、それでいいのかどうかということだけ聞きたいと思います。","respondent":"榎本（圭）福祉部長","answer":"第六期事業計画の重点事業にも挙がっていますけれども、実際上、２０２５年は第九期になるのですけれども、なるべく早くそういうものに向けて形をつくっていきたいと考えております。","voiceIndex":56,"id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ここのところは、かなり負担が大きいのではないかという思いがしています。それから、先ほども、保護率が１５.６‰で、東京都が２２.１‰、全国が１７.１‰ということで、かなり全国よりも、東京都よりも低いという状況になっているのですけれども、なぜ品川区がこれだけ低いという状況になっているのか、区としての捉え方がありましたら、お聞かせいただきたいと思います。","respondent":"松山高齢者地域支援課長、伊東生活福祉課長","answer":"総合事業の要支援者の考え方ですけれども、これまで、旧いきがい課で実施おりました一般介護予防事業も含めまして、今後、多様な介護予防事業を行っていくうえで整理するという観点もありますので、要支援者については。ご質問の職員態勢の部分ですけれども、確かに、職員数としては、こちらに示してある数字ですが、そのほかに高齢者世帯自立支援員という、非常勤ですけれども、各１から５係のほうに配置しておりまして。","voiceIndex":58,"id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"多い方は、一人で１００名を超えている方もいらっしゃるとお聞きしています。さまざまいろいろな課題を抱えた方を見ていただくということになりますので、ぜひそこの体制については、今後も充実していく方向でお願いしたいと思います。ここから要介護のほうに移っていく方が多いと思いますので、そこら辺の連携はよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-006"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"厚生委員会所管の施設で避暑シェルターになるところは、あるのかどうなのか。たしか、避暑シェルターになると、たしか水分の補給もできるようになると思うのですが、その箇所数だけ教えてください。","respondent":"松山高齢者地域支援課長","answer":"シルバーセンターが、その避暑シェルターとしての役目を果たしております。","voiceIndex":78,"id":"exchange-007"},{"speaker":"いながわ委員","kind":"意見","question":"シルバーセンターは何カ所かあると思うのですけれども、違う所管の施設で、シェルターと書いた旗がその施設の中に入ってはためいていたのです。こういうものは外に出さないと意味がないと思いますが、そういうところにも十分配慮していただいて、外から見えると、ここはシェルターになっていると利用される方がいらっしゃると思いますので、ぜひ、そういうところも気をつけていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"私も、先ほど、質問させていただいたけれども、地域包括ケアは、ほんとうに今やっていくべきだろうと思っています。特に今、動き出しているところもあるのはそこら辺かと思うので、大原則は地域包括だけれども、今入れる医療、介護、健康づくり、こういうところから入りながら、１年間やっていけることはたくさんあると思うので、積極的に取り上げていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3416#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":52826,"voices":85}},{"id":"h27-20150608-8","meetingId":"h27-cm06","date":"2015年6月8日","dateIso":"2015-06-08","committee":"建設委員会","time":"午後 １時００分～午後 ４時３３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１の幹部職員紹介","agenda":"の１の幹部職員紹介","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"品川区議会自民党・子ども未来の鈴木真澄です。１７年目にして初めて建設委員会をやります。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":4,"id":"exchange-001"},{"speaker":"安藤委員","kind":"意見","question":"日本共産党品川区議団の安藤たい作と申します。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-002"},{"speaker":"つる委員","kind":"質問","question":"公明党のつる伸一郎です。よろしくお願いします。私も委員としては建設委員会は初めてですので、教えていただきながらよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-003"},{"speaker":"筒井委員","kind":"意見","question":"維新・無所属品川の筒井ようすけと申します。私も全くの新人です。しっかりと皆様と協力して、この品川区のまちづくりに、そして品川区の発展のために微力ながらしっかりと寄与してまいりたいと思いますので、今年１年、何とぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-004"}]},{"id":"topic-02","title":"の２の事務事業概要","agenda":"の２の事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この計画に対する区の評価をお伺いしたいのと、あわせて私は、この中身はすごくいい中身だと考えています。品川区も特定整備路線の整備は、そこに莫大な税金と労力を費やして東京都と連携してこれを進めるという方向ですが、特定整備路線の整備をやめて、税金と労力は国が示すような耐震化の推進と感震ブレーカーに費やすべきだと私は思っていますが、区の考えはいかがでしょうか。","respondent":"中村都市計画課長","answer":"特定整備路線のことに関連して、今、防災・減災計画、これは国で広域的な計画ということで定めて推進していくという性質のものと認識しています。その中で、品川区は特に木密地域の多い、あるいは道路が狭いといった地域特有の課題があります。","voiceIndex":63,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"こちら、国の大もととなる減災対策の計画の中に、道路という記述がないです。これについてどう考えるかということをお伺いしたので、それをお答えいただきたいのと、あわせて、とはいっても、この２つの住宅耐震化は２０２０年までに９５％やると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区全体の防災計画に関わって、国がこういう方針を出しているので、そこに対する区の考え方はすごく重要な、防災全体を考える上ですごく大切な点だと思いますので、ぜひそちらは答弁いただきたいのですけれども。","respondent":"藤田都市環境部長","answer":"そういう中では、今進めている特定整備路線の整備ももちろん必要だと考えていますし、委員も先ほどお話がありました耐震化を進めることですとか、そういったようなこと、それから火災を発生させないためのさまざまな施策について。","voiceIndex":67,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"そのテーマは、以上です。そこで、用途地域の合理的な配置についての区の考え方は何かあるのでしょうか。区としては用途地域をこのように配置していくという基本的な考えがあるのであれば、伺いたいと思います。","respondent":"中村都市計画課長","answer":"用途地域に関しましては、それぞれ建物等が地域によって規制のかかり方が別で、これがこの用途地域を定めるところによりまして、これを目標として建てる建物の制限によってまちづくりを誘導していくというような考え方です。","voiceIndex":69,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"区としてはそういうふうに考えているということですね。それで、この用途地域の変更の要望などが地域から上がった場合は、区としてはどのように対応していくのか、用途地域を区が主体的に変更するときはどういうときなのかをお伺いしたいのが、この用途地域問題についての質問です。それとあわせて、公営住宅の問題についてもお伺いします。","respondent":"中村都市計画課長、矢木住宅担当課長","answer":"そういった中で、今の用途地域が定められているわけですけれども、例えばそれが上位計画によってその地域のまちづくりの方針が変わっているとか、あるいは、その地域一帯で住環境等の確保。私どもといたしましては、公営住宅の総量的な供給の増というよりは、「住み続けたいまちしながわ」の実現に向けて居住環境の向上でありますとか、耐震改修や長寿命化等々の計画で。","voiceIndex":71,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"だから、私は、今、課長が言ったような答弁だけでは、そうした方々は区外に出ていかなければならなくなるように思ってしまうのですが、それはどうなのでしょうか。","respondent":"矢木住宅担当課長","answer":"今のご質問ですが、まずは住宅総数が余りぎみであるというところの中では、そちらの民間のストックの有効活用、すなわち、なかなか余っている住宅をうまく供給できないという、そういうところの中で、例えば住宅の相談でありますとか。","voiceIndex":74,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"続きまして、退官自衛官の採用というところで、本日は人事や組織図の話もありましたので、お伺いしたいのですけれども、今回、２３区で初めて退官自衛官の方が採用されたということですけれども、採用の目的と経緯をもう少しお伺いしたいのですが、ホームページ等に紹介がありましたけれども、自衛隊での知見を活かしていただきたいということですけれども、まずお伺いしたいのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"それでこれからやっていくわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-012"},{"speaker":"安藤委員","kind":"意見","question":"どうして、最初は今、部長が先に立って、まず防災の全体の話をして、その後、課長がお話ししたわけですけれども、どういった役割をこれから果たしていただけるのかということはすごく大事な点だと思うので、そういった意味で聞いたのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと納得いかないのですけれども、では、答えられれば答えていただきたいということで、品川区のほうが自衛隊にぜひ防災政策を充実させるために来てほしいと要請したのか、それとも自衛隊から品川区に要請したのかをお伺いしたいのと、これからの話ですけれども、ホームページ等ではなかなかわからないといいますか、実際、部長がこれからどのような業務で活躍するのかをお伺いしたいです。","respondent":"松代防災まちづくり部長","answer":"消防に関しましても、消防の連携は区民の身近なところでの火災に対する対応というところでは、大きな力を各消防署と連携を図ってやる、これは大きな成果としてやっていただいているところです。今般、自衛隊から、このたび曽田部長が来ていただきました。","voiceIndex":83,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"ですから、そこは庁というなら、私は消防庁からというのが普通の発想だと思うのが１つと、それに対してどうでしょうかということが１つと、あとは具体的には、これから部長が力を上げるという点では、地域防災計画とか区の国民保護計画をさらに充実させる、改訂とは言わないまでも、あるいは、この計画の地域防災計画、区国民保護計画の充実ということなのでしょうかということをお伺いします。","respondent":"松代防災まちづくり部長","answer":"その中に、地域防災計画を定め防災に当たる、減災に当たる、そういったことで東日本大震災以降、東京都から示された被害想定に基づく地域防災計画を改訂し、その中でさまざまな今後の対応等についての計画を立てました。","voiceIndex":85,"id":"exchange-015"},{"speaker":"西本委員","kind":"確認","question":"３つだけ確認をさせてください。３点目は、大崎駅西口のバスターミナルですが、観光まちづくりということですが、これは路線バスの運用というところまでの話し合いはされているのか、されていないのかというところを教えてください。","respondent":"中村都市計画課長、溝口都市開発課長","answer":"特定整備路線、東京都の今の進捗状況ですけれども、こちらの補助２９号線、放射２号線、補助２８号線、いずれも事業認可は既に取得されておりまして、また。そういった中では、できるだけ早く今後の跡地での方針については求めていきたいと考えているものです。続きまして、大崎駅西口のバスターミナルの整備です。","voiceIndex":87,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"それと、ＪＲ東日本との交渉ですが、ＪＲ東日本の今の考え方はどういう状況なのか、まだまだ用途についての考えが定まっていない状況なのか、なかなか相手があるものですから、品川区も早くやりたいというところがあるのでしょうが、そこの交渉の度合いはかなり難航しているものなのか、少しずつ動いているというところなのか、それだけお聞きします。","respondent":"中村都市計画課長、溝口都市開発課長","answer":"しかしながら、今、権利者１人ずつ順番にということではなくて、並行して各地域を進めているですので、話がまとまったとすれば、進捗率が上がるときもあれば、また。いずれにしましても、早い時期に皆様に今後の跡地利用についてお話しできるように、ＪＲ東日本と引き続き協議を続けていきたいと考えているところです。","voiceIndex":90,"id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"は委員会の中でいろいろと話し合っていきたいと思いますが、先ほどから、これからの流れ方ですけれども、委員長から仕切りをしていただきました。やはり関連する討議内容は、当然、議論が必要かとは思いますが、建設委員会で話をしなければいけないことについては、しっかりと仕切りをしていただいて、上手な委員会運営をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-018"}]},{"id":"topic-03","title":"の「東京における都市計画道路の整備方針（第四次事業化計画）中間のまとめ」の公表","agenda":"の「東京における都市計画道路の整備方針（第四次事業化計画）中間のまとめ」の公表","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ですから、本計画の前に、パブリックコメントをやるのか、やらないのかお伺いしたいということと、実際にこのスケジュールですと、品川区に対して優先整備路線はどこがありますかという感じで、都から意見照会が来ると思います。その時期はいつごろなのかということが２点目です。３点目として、実際に今、東京都と優先整備路線について区は話し合いをしているのかどうかお伺いします。","respondent":"中村都市計画課長","answer":"ですので、改めてこの道路の位置等について確認をし合うということはございませんけれども、選定に当たりましては、今後、年度末までのまとめの間で東京都と区市町が連携して、連携ということは情報交換あるいは検討を行いながら、最後のまとめを行っていくスケジュールです。","voiceIndex":98,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"パブリックコメントは最初で最後となりますと、具体的に何号線を指定する、しないという具体的な計画に関しては、住民は物を言えないということだと思うので、大問題だと私は思っております。ですから、今の時点で区が優先整備路線に入れたいと思っている路線はどこなのかを聞かせていただきたいということです。","respondent":"中村都市計画課長","answer":"現在までに第三次優先整備路線ということで計画を進めておりましたけれども、まさにこれからこの１５項目、あるいは６項目につきまして検証項目を踏まえて検討していくですので、現在、区でも具体的な場所が決まっているということではございません。","voiceIndex":100,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、私は何が言いたいかと言いますと、これは問題だと思いますけれども、部長もこの「中間のまとめ」をつくるに当たって、多分、検討会に参加していたと思いますが、区としては、この「中間のまとめ」の方向をどういうふうに考えて、あるいは、どういう考えをこの「中間のまとめ」をつくるに当たって東京都に意見を言ってきたのか、そこら辺をお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"そういったところで地域の安全、そして、にぎわいが確保できる、そういったまちをつくるという目標が、品川区内の地域の特性としての目標であると考えて東京都に向き合ってあります。","voiceIndex":102,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"それは、先ほど言ったように必要性の検証しかしていないというところですし、その検証項目の中もゆるゆるだということが根拠なのですけれども、品川区としては、この整備方針を必要ではない道路が廃止になるような具体的中身になっていると思っているのでしょうか。","respondent":"中村都市計画課長、藤田都市環境部長","answer":"この検証項目につきましては、適切であると認識しております。今後の予定のところの真ん中の大きな、ちょっと角のとれた丸の中に「優先整備路線の選定」ということで、この辺の中には、皆様からの意見を踏まえ、検討した上で、選定の考え方をまとめというふうに書かれてあります。","voiceIndex":104,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"品川区の平成２５年度の現況でいうと、６０％になっています。都市計画道路は、一体、品川区の中に何本あるのかというところを加味しているので、それと、特定整備路線が入ってきて、それとの優先順位も今後どうなってくるのか、都市開発道路という選定と、プラス特定整備路線が出てきているわけですから、それらの優先順位はどうなっているのかということを教えてください。","respondent":"中村都市計画課長","answer":"優先順位ですけれども、今、委員申されました特定整備路線との関係、特定整備路線のほうは平成３２年までに目標年次を定めて東京都としても事業を進めているものですので、これについては優先とか優先ではないというところとはまた違うところで、平成３２年までの完成目標です。","voiceIndex":107,"id":"exchange-023"},{"speaker":"西本委員","kind":"提案","question":"その中での区の考え方がどこに反映できるのか。パブリックコメントはわかりますけれども、区の考え方、いろいろ検討会があって、その中でいろいろ提案しているのだろうと思いますが、そのすり合わせの段階で東京都の考え方と品川区の考え方がマッチングしない部分があるのかどうなのか、それとも要望がきっちりと言えているのかどうか、そこをお聞きしたいのですが。","respondent":"中村都市計画課長","answer":"この優先整備路線の選定に当たりましては、区ではこの検証項目を踏まえて検討した後に、これは東京都へ区として意見を言っていく場が、今後、また検討会等が何回か開催が予定される中でしっかりと意見を述べていくということを考えてあります。","voiceIndex":109,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"１２本とありました。当然、道路を広げればいいという話ではなくて、広げるためには、その周りをどういう状況にしていったらいいか、再開発というふうにもっていくのか、そこをトータル的に考えていかないと、道路はうまくいかないと思いますけれども、その辺のリンクの仕方はどういう考え方なのでしょうか伺います。","respondent":"中村都市計画課長","answer":"そういった中では、十分に説明等において理解を深めながら進めていくという姿勢です。","voiceIndex":111,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"結局、土地をとられてしまうわけですから、そうすると、上に高くしていくのかとか、まち全体をどういうまちにしていくのか。品川区は密集市街地ですから、そうなると、そこを解消しつつ道路を拡幅しながら安全・安心なまちづくりというところの試案を持っていって開発していかなければいけないのではないかと思います。その考え方は区としてどういうふうに考えてもっていこうとしているのでしょうか。","respondent":"中村都市計画課長、藤田都市環境部長","answer":"ですので、こういった災害に強いまちづくりの事業と、そして、この都市計画道路の事業、こういったものが現在のところうまくリンクさせて、そして進んでいるという認識です。その辺については、この項目にあわせて東京都も含めて、パブリックコメントの意見も含めて、さまざまな観点から今後検証して。","voiceIndex":113,"id":"exchange-026"},{"speaker":"筒井委員","kind":"意見","question":"計画決定から４５年以上たっているところもありまして、そうした状況の中、またさらに今後１０年間でまた検討を加えるというのは、一体どういう根拠なのか、なぜ１０年間になるのかという根拠を示していただければと思います。","respondent":"中村都市計画課長","answer":"ここでは将来、五次を定めるとは示してはおりませんけれども、１０年単位ですので、引き続き検討がなされていくと考えております。","voiceIndex":116,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"計画決定を受けた土地の所有者もおりまして、いつまで、実際計画が着手されるのはいつなのかということでお困りの方もいらっしゃいますので、私としては、逆にスピード感を持って決定を実行するのかどうかを早目に区としてもお願いをしたいということを考えております。その点、区としてはどういったお考えなのかをお聞かせいただきたいと思います。","respondent":"中村都市計画課長、松代防災まちづくり部長","answer":"その辺については東京都に申し入れを行うと同時に東京都と連携して、品川区もそういったところで計画についてなるべく早くお示しできるような、そういった考え方で計画道路の事業が進められていくよう。加えて、そのほかの路線も、交通ネットワークという観点から整備計画を立てております。そういった意味では、いまだまだ道半ばですので、そういったものはしっかり今後も実施していきたい、このように考えているところです。","voiceIndex":118,"id":"exchange-028"}]},{"id":"topic-04","title":"の区民住宅（空き室）入居予定者登録募集","agenda":"の区民住宅（空き室）入居予定者登録募集","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"現状での空き室がどのぐらいあるのかをまず教えてください。","respondent":"矢木住宅担当課長","answer":"ご質問の件ですが、実は空き室の入居予定者募集は、空き室があるかないかではなく、登録して、それで空きがあればすぐ入れるし、なければ登録順で入れるようなシステムになってあります。","voiceIndex":126,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それは十分に理解しており、現状で空きがあるかないかということの確認です。","respondent":"矢木住宅担当課長","answer":"現状の空き室につきましては、トータルで１００戸弱の空きがあります。","voiceIndex":128,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"状況はわかりましたけれども、長期に空いている部屋がありますが、そこら辺をどう埋めていくのかという、そちらを確認したかったわけです。今回のは募集だから、内容は違うといえば違うけれども、そこら辺をもう一回、お答えいただきたいと思います。","respondent":"矢木住宅担当課長","answer":"こちらは、指定管理者を通じまして申し込みの募集をしていますが、一層の募集の勧誘をいたしますとともに、今後の推移を見まして、また空き室の解消に向けて、家賃等々を含めまして検討が必要かとは考えております。","voiceIndex":130,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"なるべくその辺も空いたまま、結局は区の負担として出ている、その辺は委員会が初めてで状況はわかりませんので、ぜひお考えいただきたい。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-032"},{"speaker":"西本委員","kind":"意見","question":"今、１００弱ありますということですが、まず、家賃は、いろいろと空き対策として家賃を下げていただいたりということをしていると思いますが、その後、どういう対策がオーナーと、私は、品川区の持ち物、結構、空いているところは決まっていると思いますけれども、そことはどういう話し合いになっているのか、そして、今、普通のアパートやマンションの空き家も、結構、品川区の中にはあるということなので。","respondent":"矢木住宅担当課長","answer":"建設型につきましても、近傍同種家賃的なものは調査しているのですが、なかなかそれとも均衡上の中ではそれほど乖離はない中で、あとは設備等々に検討せざるを得ない段階に来ているのかとは考えてあります。","voiceIndex":133,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"２０年近く、それなりの期間があると思いますけれども、一番空きが多い区民住宅であと何年ぐらいあるのかがわかれば教えてください。それと、滞納されて裁判にもかかっているケースが結構あると思います。ですので、なかなか選別はできにくいと思いますが、そこの回避をするための方策は何か考えられているのかを聞きたいと思います。","respondent":"矢木住宅担当課長","answer":"第２点、滞納整理の手法ですが、こちら、昨年来申し上げているところではありますが、なかなか滞納が込んでしまうと、特に区民住宅の場合、十何万円というところがございまして、２カ月、３カ月というと、なかなか返しにくくなってしまう。","voiceIndex":135,"id":"exchange-034"},{"speaker":"西本委員","kind":"意見","question":"その後のことを、退去の方々、本当に努力されていて、非常に頑張っていると感じるのですが、入居のときになかなか経済状況もころころ変わってしまうという現実もあって、そうそう簡単にいかないのはわかってはいますけれども、入居のときに何かチェック機能が働かせられるような、そういう条件をもう少しきつくお願いするとか、余りにも高額になって裁判になって、で。","respondent":"矢木住宅担当課長","answer":"遅くとも半年程度をめどにオーナーには１年前から話し合いを本格的に始めるのですが、半年前には皆様のご都合があると思いますので、入居後の条件でありますとか、敷金、家賃、家賃はこの辺が一番多うありますので、その辺の条件を提示していただくようにお願いしています。","voiceIndex":137,"id":"exchange-035"}]},{"id":"topic-05","title":"の耐震診断が実施されない特定緊急輸送道路沿道建築物の公表","agenda":"の耐震診断が実施されない特定緊急輸送道路沿道建築物の公表","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"公表期間ですが、平成２８年３月３１日までということですけれども、なぜそこまでなのかという考え方と、この公表期間を過ぎたらどうなるのかをお伺いしたいのと、あと診断済みが１７３件ということですけれども、診断がまず第一歩だと思いますけれども、補強を実際にしないと、そこが大事だと思いますが、補強に実際この１７３件の診断から進んだ件数は何件になるのでしょうか。","respondent":"鈴木建築課長","answer":"それと、耐震診断済みの中で補強工事を行った件数ですが、補強工事の費用につきましても支援事業を設けて実施しております。こうした新事業を使わないで補強工事を行った件数の把握は、今、手元にはございませんが、東京都の支援事業を利用して補強工事を行った件数は１１件です。","voiceIndex":143,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"補強工事、都の新事業を受けたのが１１件だということですが、すみません、その前に耐震補強が必要だと診断されたというか、その診断の結果の内訳をお伺いしたいのが１つでした。そういった点で、マンションで区の耐震補強を進める上で課題になっている点はどこなのかをお聞きします。","respondent":"鈴木建築課長","answer":"そうしたところ、なかなか費用面、あるいは従前の規模が建たない等々につきましては、費用的なところでは、都と連携しまして耐震補強工事につきましても相当手厚く支援事業を行っておりますし、また、従前規模が建たないところにつきましても、国が促進法を改正しましたし。","voiceIndex":145,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"すみません、ちょっと質問の仕方があれだったのかと思いますが、診断対象建築物が２０５棟で、診断済みが１７３棟、今、未診断の課題はよくわかりました。診断済みの１７３棟のところで、耐震が必要だとなったところはどれぐらいあるのか、その内訳も伺いたいと思って質問しました。","respondent":"鈴木建築課長","answer":"申し訳ございません、今、診断結果ＮＧ、耐震性がないとなった建物の数字は手元にはございませんけれども、いろいろ担当、あるいは個々のやりとりを聞いていますと、旧耐震、耐震性がないという結果になる確率は非常に多いと認識しています。","voiceIndex":147,"id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問","question":"耐震の診断をしない中で、公表はされるけれども、これから区のほうもいろいろ折衝していく中で、どうしても耐震にならなかったときにどうするのか。多分、自分の知っているところで空き家になっているところがあるので、今は全然使っていないところがあると思います。そういう場合には、持ち主はどういう状況か今はわからないけれども、耐震しないでそのまま残ったときにはどうするか、後の問題を伺います。","respondent":"鈴木建築課長","answer":"今ご指摘の中に空き家等がある場合は、この事業の中で除却費の助成もありますので、必ずしも設計をして補強工事と進んでいかなくても、除却費の制度もありますので、そういったところを丁寧に説明していきたいと考えています。","voiceIndex":149,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、無意味というか、余り意味をなさないのではないか。本当に区の目的としてしなければいけないというふうに考えるならば、もう少し効力のある方法、処置をとるべきだろうと思いますが、あとは理解を求めていく。結局、公表しても不利益を被るわけでもないし、余り意味がないような気がするのですけれども、その辺の考え方というか、それはありますでしょうか。","respondent":"鈴木建築課長","answer":"ちょっと説明が、先ほど３月３１日公表が過ぎればという話をさせていただきましたけれども、実は公表に当たって東京都が条例に基づく意見聴取を各所有者の方にしております。","voiceIndex":151,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"地震はいつあるかわからない。だから、法律が決まっていて、今後その形でされていくわけですから、いずれにしてもこういうことが起きますというのは、今の段階から言ってあげたほうが、後になって「いや実は罰則規定がありまして」と言われても、それなりの覚悟というものがある程度の期間必要だと思うので、それの公表も、何か時期的なところで東京都と打ち合わせ、すり合わせをしているのでしょうか。","respondent":"鈴木建築課長、藤田都市環境部長","answer":"氏名を公表した後に、今後、さらに働きかけを強く所有者にしていって、その上でどう所有者の方が対応していただけるか、あるいは、そういった個別の事情がどうそれぞれにあるのかを勘案しながら、最終的にそうした命令。そういう中で、この条例だけでなく、ほかのさまざまな建て替えを促進するような施策とあわせて進めることが、今後、補強が進んでいく、建て替えが進んでいく。","voiceIndex":153,"id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"この題名に推進する条例、推進なのですね。ですので、将来にわたってどうしていきたいのかと、そして、災害があったときの対処としてこういうふうに全体的に考えているということをしっかり伝えていただいて協力をいただけるように、まず認識不足だと私は思いますので、その辺を考慮しながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"確認","question":"これは、マンションと住宅だと規模が違うのですけれども、一般の住宅だと、耐震診断を受けるに当たって３０万円から５０万円かかるのですが、その中から品川区では住宅に対する耐震診断の助成金があると思いますけれども、これは私の確認ですけれども、耐震診断済の方、マンションの所有者、または未診断の土地の所有者に対して、東京都もしくは品川区が耐震診断の助成ができているのかどうか。","respondent":"鈴木建築課長","answer":"特定緊急輸送道路対象の建物につきましては、東京都の事業として区でも事業におきまして連携をして実施しております。２１棟につきましても、対象とすれば全て対象となっています。","voiceIndex":157,"id":"exchange-043"},{"speaker":"筒井委員","kind":"質問","question":"ですから、東京都ホームページ、しかも一般の区民からしたら、なかなかそこまで検索しないだろうということが考えられますので、案ですけれども、広報しながわにこういった未診断の建築物がありますと載せるか、もしくは東京都のホームページにそういう情報がありますということを告知するような方法があってもいいのかと思いますけれども、そのあたりを当局はどう考えているのでしょうか。","respondent":"鈴木建築課長","answer":"委員ご指摘のとおり、個別にヒアリング、聞き取りをしておりますと、診断未実施公表についても、「いいですよ」と言う方も確かにいらっしゃいます。","voiceIndex":159,"id":"exchange-044"},{"speaker":"つる委員","kind":"質問","question":"今のご報告をいただいた中で、そうすると、１７３分の１６４分の１１棟が工事済みという説明だったと思いますけれども、そうすると、昭和５６年以前なのだけれども、先ほどの筒井委員の中でもあったとおり、助成だとか何だとかを活用せずに、個別でそれまでの期間、だから、２０年近くの間の中で何らかの手立てを尽くしていただいていたから。","respondent":"鈴木建築課長","answer":"基本的には、補強せずにそのまま診断をしてオーケーだったと。壁が多かったり、配置がよかったりというところで、診断した結果オーケーだというところがその数字です。","voiceIndex":163,"id":"exchange-045"}]},{"id":"topic-06","title":"の平成２７年度品川区電力節減方針","agenda":"の平成２７年度品川区電力節減方針","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"環境課からのご説明だったのですけれども、同時に環境課としては地球温暖化防止に取り組んでいるというご説明があったのですが、節電の目的ですけれども、温暖化防止という目的も入っているのでしょうか。","respondent":"三ツ橋環境課長","answer":"全体は品川区地球温暖化対策実行計画第三次に基づいて、その趣旨は二酸化炭素の排出量の削減にありますけれども、東日本大震災を受けて電力の供給不足が考えられますため、数値の目標を掲げ、電力節減に取り組んでおります。今年度も引き続き実施しております。","voiceIndex":169,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"節電の努力はすごく大事だとは思っています。同時に、じわじわと進んでいる温暖化を防止するためにも大事なのではないかと思っています。節電目標と同時に、自然エネルギーの区内の普及、特に区民みずからが小さな規模で自分たちのところでエネルギーをつくれるという、そういう自然エネルギーの普及についてもセットで目標ですとか方針を持つという意味だと思いますが、区はどのようにお考えでしょうか。","respondent":"三ツ橋環境課長","answer":"地産地消の考え方ですが、先ほど事務事業概要の中でもご説明しましたように、太陽光発電設置助成などを進めております。引き続きこの考えに基づいて実施してまいります。","voiceIndex":171,"id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"努力としてやっていくということですけれども、私が聞いたのは、こういった節電目標はアクセス目標で、いついつまでにどれぐらいまでにということも掲げているので、ぜひ自然エネルギーの普及についてもこうした方針といいますか、目標を持って取り組む必要があると思います。そういった目標を持つ考えはないのでしょうか。","respondent":"三ツ橋環境課長、藤田都市環境部長","answer":"実際に太陽光発電設置助成は区として行っておりますけれども、ほかのものを考えていくに当たり、非常に慎重に考えなければいけない問題だと思いますので、目標としては掲げておりませんが、引き続き考えてまいりたいと考えています。温暖化の部分と品川区の電力節減方針の２つの話ですけれども、まず、電力節減の方針そのものは、東日本大震災を受けて、その後、電力供給がなかなか思うようにいかない。","voiceIndex":173,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"その部署、部署によって目標値が掲げられる、全体的に１５％ということなのか。ただ、部署によってはできないです、福祉施設の管轄になっているところは、当然、１５％は無理かもしれない。今までの実績等を踏まえてどのようなやりくりをしながらトータル的にマイナス１５％に向わせても、いろいろな部署の中での１５％を引き出すという形に目標を掲げていくのか、考えはいかがでしょうか。","respondent":"三ツ橋環境課長","answer":"このパーセンテージにつきましては、昨年度は、ほとんどのところが１５％となっておりますけれども、例えば保育施設やまた高齢者施設など、そのようなところはなかなか達成度が、避暑シェルターなどを掲げているところもありますけれども、非常に難しい。","voiceIndex":176,"id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"ですから、そういうことを考えると、区民サービスは低下はしています。昼間はやはり暑いのです。それでなおかつ、前年度はマイナス１５％まで行っていますという、それをよしとするのかです。申し訳ありませんという形で区民の皆様に例年のようにお願いしていくのか、だけれども、今年はそれとはまた違う方向で、多少これぐらいはいいのかなというようにしていくのか、その辺の考え方はどうですか。","respondent":"藤田都市環境部長","answer":"なかなか厳しい条件の中での施設利用もあろうと思うので、その時々では施設の中で臨機応変に対応できるようなことも考えていかなければいけないと思いますので、施設を運営する中でのいろいろな判断もありますので、その辺は現場主義的なことも踏まえながら。","voiceIndex":178,"id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"大体１５％という形なのでしょうが、区民サービスという考え方ですね。「最近の区はどうしちゃったの。ご協力ください」というのはきっちりと示したほうがいいと思います。平成２３年度のときには、かなりいろいろ言いましたが、そこまでにもならなくても、皆さん、納得した形でやっていますが、今はあまり納得していないので、そこはお願いしたいと思いますが、いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"今回、区民へのご協力のお願いですが、実際に暑い現状もございまして、非常に皆様に影響がある可能性もありますので、特にご協力というお願いはしていく方向なのかと思いますので、そのあたりは検討させていただきたいと思いますので、よろしくお願いいたします。","voiceIndex":180,"id":"exchange-051"},{"speaker":"筒井委員","kind":"質問","question":"節電する施設ですけれども、小・中学校、清掃事務所などや運動公園施設などという書き方になっていますけれども、具体的にどの施設がそういう施設になっているかを事前に区民の皆さんにお伝えするような情報公開することはお考えでしょうか。","respondent":"三ツ橋環境課長","answer":"実際に全施設に関して節電は取り組んでいただけるものです。その一方、避暑シェルターというものも掲げておりますので、その避暑シェルターについては、のぼりなどを掲げておりまして、もっとこちらが涼しいですというお知らせはしております。","voiceIndex":182,"id":"exchange-052"},{"speaker":"筒井委員","kind":"質問","question":"ということは、品川区の全公共施設がそういった状態になるという理解でよろしいのでしょうか。","respondent":"三ツ橋環境課長","answer":"全施設に関しまして、まずは１５％を掲げている、そして、その中でも避暑シェルターというものが存在するです。","voiceIndex":184,"id":"exchange-053"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先ほど部長のご答弁の中で、平成２２年度に比べて平成２３年度が２５％ぐらい下げていると。平成２４・２５・２６年度は１５％を切っているでしょうけれども、どのぐらいの数字になっているのか。徐々に上がっているのか、それともずっと維持できているのか、その確認をお願いします。","respondent":"三ツ橋環境課長","answer":"平成２３年度につきましては、マイナス２５％でございました。平成２４年度につきましては、マイナス１４.５％でございました。平成２５年度につきましては、マイナス９.１％でございました。そして、昨年度、平成２６年度につきましては、マイナス１０.８％でございました。","voiceIndex":186,"id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"意見","question":"どうしても暑いと、先ほど区民サービス低下ということも言っていたけれども、徐々に、自然に変わっていってしまう、意識が薄れてくると思いますので、これだけやってまた呼びかけをして、皆さんの意識をもう一度戻していってもらうためにも、ぜひよろしくお願いしたいと思います。","respondent":"藤田都市環境部長","answer":"数が多いので、絶対量的には多くなってくるので、そこが１５％を少し切るような形であると、それの積み上げ分が全体に反映してくる形になっておりますので、それぞれの施設の中でまずは電力節減の意識をしっかり持ってもらうために。","voiceIndex":188,"id":"exchange-055"}]},{"id":"topic-07","title":"の４、その他","agenda":"の４、その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"老朽化したマンションの再生、耐震化も含めてなされるという重要な課題だと思いますけれども、これ、品川区の大崎西口駅前地区を東京都の募集に対して応募した理由をお伺いしたいのと、駅前だから再開発でいろいろやることになるかもしれないですけれども、なかなかこういう手法で区内各地でマンション再生は、できるところとできないところがあるのではないかと思いますが、これは。","respondent":"溝口都市開発課長","answer":"１点目の今回区が応募した理由ですが、たまたま老朽マンションが一定集積した地区において、まちづくりを検討している地区がございましたので、そこのまちづくりを進めていく上で、一つの今後の事業性を含めて地域の合意に資するような事業が。","voiceIndex":194,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"かなり説明が難しいというか、なかなか難しいと思ったのですが、これまでも西口駅前地区は建て替え等などで課題があったのでしょうか。再開発準備組合がたしか立ち上がっているところだと思いますけれども、今までのような再開発をやってきたところを、今回、モデル事業に選定することで何が違うのか、何が変わるのですか。その辺がわからなかったので、もう一度お伺いします。","respondent":"溝口都市開発課長","answer":"そういったものを区の中でもさまざまなマンションの再生に向けた取り組みにつなげられると考えていますので、そういった中での判断で、今回、モデル事業として応募し、東京都から選定されたと認識しているものです。","voiceIndex":196,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"今、準備組合ができているところだということですが、地権者の方々の意向に今回のモデル事業はマッチングしたのかということです。結局これは構想がいろいろ、要は今回の事業はどうしていくかという話だと思います。話し合いでこういうまちがいいと言うだけでは意味がないので、実際それをもとにして再開発という形になろうかと思いますが、それはどういう意味でもって、いくのですか。","respondent":"溝口都市開発課長","answer":"ただ、この再開発準備組合は昨年立ち上がったばかりの組合になっていますので、今後やはり皆様方に当地区、マンションを含む再生をどのようにしていくのか、また、駅前にふさわしい魅力的なにぎわいのあるまちづくりをどのように進めていくのか、そういったところをこれから順次。","voiceIndex":198,"id":"exchange-058"},{"speaker":"西本委員","kind":"質問・要望","question":"これからのこととしては、それを具体化していくというところまで踏み込んでいかないと、せっかくいい案が出ても、それが実現されなければ絵に描いた餅になってしまうので、そこはきっちりと東京都と予算上の措置もしっかりとっていただくような形でやっていただきたいと思いますが、そのめどはどういうふうに考えられていますか。","respondent":"溝口都市開発課長","answer":"もう一つは、東京都のほうでこのプレス発表の中でもありますけれども、都市計画を含めてしっかり技術的な助言をしていくと聞いておりますので、そういったところでは、調査していく段階でこういったものができないのか、また。","voiceIndex":200,"id":"exchange-059"},{"speaker":"安藤委員","kind":"確認","question":"この資料についての確認ですけれども、調査費の話が出たのですけれども、今後の予定の都の財政的支援と計画等にかかわる助言とありますけれども、都がこのモデル事業に関してどういった役割を果たすのかがよくわからなかったのですけれども、財政的支援とは具体的にはどういうことですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-060"},{"speaker":"西本委員","kind":"意見","question":"次回の建設委員会でということですが、この１４類型が具体的にどういうことか、そして、どういう行為なのかが、私は運転免許を持っていないのでよくわからないので、何かそういう、具体的なものがわかる資料があればわかりやすいかと思うので、その準備をしていただけると助かります。","respondent":"田口交通安全担当課長","answer":"それで人とぶつかりそうになったとか、そういった危険な行為が出た場合に、「あなた、違反ですよ」ということで切符を切られる、摘発される。個々具体的にそういったものも準備をします。免許証のない方でもわかるような工夫をしますので、よろしくお願いいたします。","voiceIndex":211,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"発生した５月３０日の小笠原諸島沖地震ですけれども、首都圏を中心に１万９,０００基のエレベーターが緊急停止したということですが、品川区内でも件数でいいますと、実態がどうだったかをお伺いしたいのですが。","respondent":"鈴木防災課長","answer":"ご質問にありました地震についてですが、区内で人的被害はございませんでした。それから、建物被害もありませんでした。ただ、区で報告いただいたものに関しては、エレベーター内の閉じ込みが１件ありましたが、大井消防署がすぐ駆けつけて救出されたという報告を受けております。","voiceIndex":216,"id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4136#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":63281,"voices":219}},{"id":"h27-20150608-9","meetingId":"h27-cm06","date":"2015年6月8日","dateIso":"2015-06-08","committee":"文教委員会","time":"午後 １時００分～午後 ４時２５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、幹部職員紹介","agenda":"の１、幹部職員紹介","exchanges":[{"speaker":"鈴木（博）委員","kind":"意見","question":"自民党・子ども未来の鈴木博です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":4,"id":"exchange-001"}]},{"id":"topic-02","title":"の２、事務事業概要","agenda":"の２、事務事業概要","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"５ページの総合教育会議、総務課事業ということなのですけれども、ここで決まったことは教育委員会のほうにも報告がされると思うのですが、これのスケジュールなんかがわかれば教えていただきたいと思います。これをどんなふうに。考え方を教えていただきたいと思います。","respondent":"品川庶務課長","answer":"１点目、総合教育会議ですが、スケジュールとしましては、年２回から３回ぐらいを予定しています。第１回目は明日６月９日となります。それ以降の日程については、現在決めていないというか、調整段階です。","voiceIndex":33,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、報告が来たら、この文教委員会で報告がされるのかというのと、あと、校舎の改築のところは、老朽化度合いと児童の数と地域のバランスということですけれども、ここを何とかしてほしいというような、学校側からの実態の声なんかも気づいていない部分はあると思うので、そういったところも対応していただけるということでいいですか。お聞きいたします。","respondent":"品川庶務課長","answer":"総合教育会議について文教委員会で報告するかという点ですが、基本的には議事録等を公開する予定ですので、文教委員会で報告する考えはございません。","voiceIndex":35,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"学校の校舎の改築のところですけれども、やはり使っている方が一番わかると思うので、バランスというところもあるとは思うのですが、実態把握をしながら、早急にすべきところはしていただきたいと思います。平成２５年度から減ってきてしまったのですが、平成２７年度はどうなるかをお伺いしたいと思います。","respondent":"野呂瀬学務課長","answer":"放射性物質検査ですけれども、基本的には昨年度並み。ですから、平成２７年度も平成２６年度と同じようにやっていく、こういう考えです。","voiceIndex":37,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"確認","question":"そうしたら、確認ですけれども、年間２回、そして、ストロンチウム検査も年間１回という確認でよろしいでしょうか。","respondent":"野呂瀬学務課長","answer":"それは各学校ごとでやっています。そうすると、学校ごとになると、年間１回という。それで、セシウムのほうは毎月２回ずつやっているということですので、各学校からすると、昨年度分ですけれども、年間２回という形になります。","voiceIndex":39,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、あと教育総合支援センターのところで、４３ページの一番最初のところにはご説明があるのですけれども、そこにソーシャルワーカーだったり、スクールカウンセラーはたしか巡回相談員に変わったということなのですが、とても重要な役割を担っていくだろうと思うので、もうちょっと詳しく、何人いて、その方たちがどれくらい回っていて、さっきもちょっとおっしゃっていただいたのですけれども。","respondent":"村尾教育総合支援センター長","answer":"それを本年度から、小学校と、それから関連する中学校も回りながら、それぞれ子どもたち、児童・生徒のさまざまな現状、また課題について対応できるような仕組みを今進めているところです。巡回相談にかかる経費につきましては、４,２１６万８,０００円です。","voiceIndex":41,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"ごめんなさい、予算だけ聞いてしまったのですけれども、人数、ソーシャルワーカーが何人で、どれだけ学校を回っている、週に何回とか。それで、ソーシャルワーカーが何人いてどれだけ回るのか、巡回相談員は何人でどれだけ回るのかというのを、小・中学校別に教えていただけますか。","respondent":"村尾教育総合支援センター長","answer":"スクールカウンセラーと、それから警察のＯＢということになります。ソーシャルワーカー４名については、特に定期的に回るというよりも、現在は、それぞれ課題のある学校とか、要請のあった場合にということ、また、現在は各中学校を月１回は巡回をしているという流れです。","voiceIndex":43,"id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"意見","question":"それで、スクールカウンセラー、巡回相談員が各校を回って、課題を把握してということがあるのですけれども、課題となったものというのは、学校や教職員みんなで話し合う場というのはつくられていませんか。","respondent":"村尾教育総合支援センター長","answer":"もちろん巡回相談員は、各学校のケース会議等にも参加するような立場です。もちろん各学校に行って、校長、養護教諭、また、各学校に特別支援コーディネーターという教員が１名います。","voiceIndex":45,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教職員の健康管理のところなのですけれども、１９ページのところに載っていますが、地域の方からも、学校はいつも夜遅くまで電話が鳴っている、電気がついている、また、教職員の方々も結構ハードなスケジュールだということもたびたび伺っていますけれども、教職員の方々の健康管理の中身、実態をどこで知ることができるのか、どういうところで報告されているのか、教えていただきたいと思います。","respondent":"品川庶務課長、村尾教育総合支援センター長、野呂瀬学務課長","answer":"１点目ですが、総合教育会議の報告につきましては、先ほど申しましたように、議事録等が公開されていますので、委員会等でやる考えはございません。この文教委員会等での報告につきましては、実際には８月３１日までの採択ですので、それが終わり次第、まとめて報告するです。学級編制の考え方ですけれども、先ほど申し上げたとおり、国の法律では１学年３５人、これは決まっていますので、守っていかなければいけない。","voiceIndex":47,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"総合教育会議なのですが、報告する考えはないと言った中身においては、なぜなのか。ぜひ質疑の時間を設けていただきたい。でないと、どこで議論したらいいのかわからないので、ぜひそこは再考していただきたいと思いますが、もう一度答えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"意見","question":"おおよそはわかっておるつもりなのですけれども、また改めてというと、どこの時点になるのかと。今日は本当に全体的な状況をつかんでいきたいというところなので、特にスケジュールとかその辺とか、どういう位置づけにあるのかを把握しながら、その時々を、意見を言っていかなくてはいけないと思っているので、十分それはわかっているつもりなので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なので、ぜひ総合教育会議のところの報告は再考していただきたい。わかりました。図書館のところなのですけれども、平成２７年度から品川図書館以外が全部指定管理になったので、すごく中身的に注目をしています。ぜひ事業者も載せていただきたいし、傾向なんかも知っていきたいと思うので、その辺の報告もぜひお願いしたいと思いますが、いかがでしょうか。","respondent":"木村品川図書館長","answer":"今、おっしゃられた、実際の４月以降の中身でありますとか、事業者のことでありますとか、ご報告をしてまいりたいと考えていますので、よろしくお願いいたします。","voiceIndex":55,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"どこかで指定管理者の、指定先というのは教えていただけるのですか。そこをぜひ。どこにも表示がないので。","respondent":"木村品川図書館長","answer":"図書館流通センターという企業と、それからウーヴという、子どもに本の読み聞かせをするＮＰＯ法人の共同事業体になっております。","voiceIndex":57,"id":"exchange-013"},{"speaker":"鈴木（博）委員","kind":"質問","question":"簡単に聞きたいところがあります。１つは、教職員の健康管理なのですけれども、１９ページに「ＶＤＴ」と書いてあるのは何なのでしょうか。それがまず１つと、それから、あともう一つは、３２ページの学校保健の健康診断というところの寄生虫卵検査、これはまだ書いてあるのですけれども、多分今年度から廃止になったはずだと思うのですが、これはいかがですか。","respondent":"品川庶務課長、野呂瀬学務課長","answer":"１点目、ＶＤＴの検査ですが、こちらは、パソコン等で目の疲れ、それから肩のこりとか、そういうものがあるかどうかという検査をするものです。寄生虫卵検査につきましては、法は改正されたのですけれども、施行が平成２８年４月ということですので、今年度が最後の寄生虫卵検査ということになりますので、平成２７年度は入っております。来年度は入ってこない年になります。","voiceIndex":60,"id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問","question":"２つありまして、３７ページの小中一貫教育推進で、フォーラムもやるということで、フォーラムの中に小中一貫教育の法制化を踏まえた今後の品川の教育の在り方について発信するとあるのですが、そのために推進委員会でおそらく話し合いをされているのか、あるいは研究されているのかと思うのですが、法制化するとなると、現在の仕組みを大きく変えたり、小学校。","respondent":"渋谷指導課長","answer":"品川区では、昨年度から全ての９年生に対して４技能の一斉テスト、先ほど、国のほうでもそんなものを考えているということが新聞報道されておりましたが、したがって、先駆けて実施しておりますので、そういったものを含めまして、その課題を客観的に明らかにしたものについて。","voiceIndex":64,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"４７ページの、品川区いじめ根絶協議会、年３回終わって、今年は同じぐらいの回数をして、テーマは何にしていくというのはあるのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"本年度も基本的には年３回予定しております。議題につきましては、現在、こういう議題で進めるという確定したものはございません。それぞれ意見を出していただきながら、では、どういうテーマでやっていきましょうかというのを、１回目に相談する予定です。","voiceIndex":66,"id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、では、昨年のネットいじめ、テーマで議論されたことは、この中に「情報発信・意見交換により」ということで、これを発信されているのかもしれないのですけれども、どこで見られるのかわからないのですけれども、傍聴できるのか、それで公開されているのかを伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"それを各学校、また保護者等に配布して、協力をいただくということになっております。","voiceIndex":68,"id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは、私たちは手にして見るとか、画面にして見るということはできないのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"その辺については、もし可能であれば、ホームページ、またはいじめ根絶協議会のリーフレットにつきましては、この場でお示しすることはできると思います。","voiceIndex":70,"id":"exchange-018"},{"speaker":"伊藤副委員長","kind":"確認","question":"教育委員会の基本方針の中の、確かな学力の定着の後段、(4)に「ＩＣＴ環境を整備し」とあるのですが、１点だけ確認なのですけれども、地区委員会でもらった資料の中に、斉藤さんというサイトはご存じですか。だから、やはりこれは、今日確認しておきたいのは、非常にこれから大きな問題になっていくと思うのですよ、総合的な対策をとっていかないと。だから、改めて、品川区の対応をお聞かせください。","respondent":"村尾教育総合支援センター長","answer":"私ども、本当にネット関係につきましては、日進月歩でさまざまな、やってもまた次のものが出てくるということについては十分認識しているところです。","voiceIndex":72,"id":"exchange-019"},{"speaker":"伊藤副委員長","kind":"質問","question":"だから、例えば、その中で「品川区」や「いじめ」やいろいろな言葉を登録して、システマチックに品川区がそういう、教育委員会関係者が情報を知るシステムを、品川区だけでつくるのは難しいでしょうから、やはりほかの区なり、それから東京都と連携してつくっていかないと、どんなに行政は子どもたちを知ろうとしても、相当深いところに入っていく可能性があると思われるので。","respondent":"村尾教育総合支援センター長、塚本委員長、金子子ども未来部長、伊崎子ども育成課長、廣田子ども家庭支援課長、竹田保育課長、今井待機児童対策担当課長","answer":"おっしゃるとおり、今後、区といたしましても、やはりそういうものが、東京都のほうと連携をとるとか、また、全区的にどんな動きがあるのか。ほかになければ、教育委員会の事務事業概要につきましては、これで終了いたします。今年は、子ども育成課と子ども家庭支援課のところが、昨年度までの青少年育成課と子育て支援課の事務事業から再編成しておりますので。１９ページに行っていただきまして、青少年の地域貢献活動につきましても一連の取り組みを進めており、(9)にあります「役立ち隊」の育成等に加え。","voiceIndex":74,"id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"児童センターのところの３５ページに、親子のひろば、０歳児、１歳児、２歳児、３歳児向けというのであるのですけれども、今、児童センターの前を通ると、お母さんたちが子どもを連れてすごくにぎわっているのは、この親子のひろばなのでしょうか。わからないもので、何をしているのかと思っていつも見ているのですけれども、それをまずお聞かせいただきたいと思います。","respondent":"伊崎子ども育成課長","answer":"そのほかに、毎日、親子サロンといって、親子連れの方、ご自由にお使いいただける場所がありますので、それで常時、お子さん連れのお母様がいらっしゃるという状況になっております。","voiceIndex":85,"id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、親子のひろばの設置の目的というか、どういう考え方で設置されているのかというのが見当たらないと思っているのですが、そこを教えていただきたいと思うのですけれども。","respondent":"伊崎子ども育成課長","answer":"紙面の関係上、全ての事業についてのご説明は省かせていただいているのですが、親子のひろばは、それぞれの年齢ごとに子どもの発達ももちろん違いますが、お母さんたちの悩みもそれぞれ違ってきますので、同じ年齢層の方たちが集まって、お子さん同士の遊びもそうですが。","voiceIndex":87,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"奨学金のところですけれども、６１ページ、貸付者の人数だけが載っているのですけれども、ここに相談に来られている方というのはカウントしていないのか。やはり相談に来られる方というのも、何らかの苦労があるのかと察するのですが、そういうところで、相談はどれぐらい来ているのかというのは把握されているでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"ひとり親の相談の中で、ひとり親でありますと、５０ページに、母子相談の内容というところで、母子福祉資金の相談というのが、件数が載っておりまして、修学資金だけではないのですが、こちらのほうに相談件数は計上しています。","voiceIndex":89,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"合計すると、０歳、１歳、２歳の本当に希望の多いところが合計８３９人になるのですけれども、小規模とか認証に入っているお母さんの中から、認可を希望していても入れないとなると、２歳になったその後の行き場がないという心配がかなり私のところにも届いているのですけれども、３歳以降の受け皿の考え方というか、基本的なところを教えていただきたいと思います。","respondent":"伊崎子ども育成課長、今井待機児童対策担当課長","answer":"その後、１０年の期限つき、時限立法で計画をつくって、各自治体が次世代に対する支援を実施していくようにということで進めてまいりましたが、昨年度、また１０年、時限立法ということで延びております。地域型保育事業につきましては、今後、新制度の中で、３歳児以降の受け皿を一定確保するような制度構築が求められておりますので、平成２７年度から５年以内に、３歳児の受け皿を区としても調整していく予定です。","voiceIndex":91,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日聞きたいのは、参考2)のところが本筋なのですけれども、具体的に、この間、本当に平成２７年度から地域型も入ってきたということで、微妙に新規の申込み数、入園数、待機児数も変わってくるのですけれども、今日お伺いしたいのは、新規の申込者数から入園児数を引いて、具体的に、私たちは未入園児、希望して入れなかったお子さんの数、この参考2)の例からすると。","respondent":"伊崎子ども育成課長、今井待機児童対策担当課長","answer":"これにつきましては、この会議の中で足りたか足りないかという議論をするのではなく、そもそも計画の策定主体は区ですので、区の中でまず、単年度ごとに事業の実施状況等を確認しまして、会議で報告をし。今ご質問がありました、２,７９９人の平成２７年度の新規申込者数から入園児数を除きました、いわゆる入れなかった数、１,０１５人の年齢別内訳につきましては、こちらのほうはお出ししておりません。","voiceIndex":94,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"それを把握していないと、どの年齢でどういう場合の方の対策を立てたらいいのかというのがわからないと思うので、私はあえて、いつもというか、うちの会派では、ここの時期しかお伺いできないので、新年度の数が精査された段階でお伺いしているのですけれども、どういう場で伺ったらここの、実際的に、だから、０歳、１歳、２歳のどのくらいの方が困っているのかというのは。","respondent":"塚本委員長","answer":"飯沼委員、今日、概要説明なので、もちろん全部の数字がおそらく出るということはなかなか難しいと思うので、答えられる範囲でということでお願いします。","voiceIndex":97,"id":"exchange-026"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１つは、２３ページのプレママ・プチママタウンと、父親のための親育ちワークショップというのがここに書いてあるのだけれども、いつも思うのですが、これだけ実施して、これだけ参加者がいましたという報告をいただくのですけれども、つる議員なんかも参加したみたいですが、実際にそれでどのぐらい満足したかとか、どのぐらいよかったとか、そういうフィードバックというか。","respondent":"伊崎子ども育成課長、廣田子ども家庭支援課長","answer":"父親のための親育ちワークショップについては、参加人数、申込み率が大変よかったということで、今年は参加者を増やして実施するということで進めていくものです。家庭相談員につきましては、家庭裁判所等で調停員とかを務めた方のＯＢの方にお願いしております。","voiceIndex":104,"id":"exchange-027"},{"speaker":"浅野委員","kind":"質問・要望","question":"こういうときだから聞けるところまでということで、２カ所教えていただきたいのですが、１６ページの「明るい家庭づくり」（家庭の日）啓発事業というところで、この中には、例えば、旗の掲出をしたりとか、懸垂の幕をするとか、イベントその他の紹介ということで、家庭の日における区民活動を推進しますとあるのですが、実際、各家庭でどのぐらい行われているのかとか、どのような実態なのかというのを。","respondent":"伊崎子ども育成課長","answer":"なかなかそれがどのくらい家庭の中で、例えば、読まれて活かされてというところになりますと、昨年度についてはまだ検証というところには至っておりませんので、今後、そういったものがどのような効果があったのかというところは、何らかの形で。","voiceIndex":108,"id":"exchange-028"},{"speaker":"浅野委員","kind":"質問・要望","question":"自転車のレンタル、厳しいだろうなというふうに感じておりまして、当初から電動アシストにしたらどうかという話があったのですが、確かに高いということもあって、このような実態になっているかと思いますけれども、それでも需要があるということであれば、継続していっていただきたいということと、そういう意味では、支援という部分に目を配って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-029"},{"speaker":"伊藤副委員長","kind":"確認","question":"だけれども、さまざまなケースがあって、いろんな家庭がある場合、その後のアフターケアをどうしていくのかということも非常に気になるので、そのことの確認と、それから、就学、例えば、６歳になったときに、当該の学区域の小学校にどうも通学していないとか、そういう後追いについてどうなのかということの３点かな、確認したいと思いますので、よろしくお願いします。","respondent":"伊崎子ども育成課長、野呂瀬学務課長","answer":"その結果につきましては、当然、児童相談所のほうでかかわっていく部分、あるいは、転出をしている場合は転出先の児童相談所あるいは区市町村できちんと対応していくという、これは全国的なルールでやっております。就学児童、生徒につきましては、今、子ども育成課長の答弁したとおりですけれども、同じような形で、基本的実態調査をして、この実態調査でわからないところにつきましては、入管等で。","voiceIndex":111,"id":"exchange-030"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"公的機関の受診履歴ということのご指摘がありました。だから、プライバシーもあるのでなかなか難しいと思うのだけれども、そういうことを当然、誰しもがゼロにしたいと思っているわけであって、だから、公的機関の受診履歴については理解するのだけれども、実際にそういうお子さんがいらっしゃるということの、目視なり確認する方法をやっていただきたいという希望はあるのですよ。","respondent":"伊崎子ども育成課長","answer":"しかしながら、お子さんの状況によりましては、やはり生命の危険を感じるという場合も出てきますので、そういった場合は児童相談所と連携しながら対応していくことになると考えていますが、ただ、今、難しいのは、法制度上、その子がいて。","voiceIndex":114,"id":"exchange-031"},{"speaker":"伊藤副委員長","kind":"質問","question":"要は、こういう不幸な事件をゼロにしたいのは、皆さんそう思っているわけでありますので、この話し合いというのは現状の中では難しいと思いながら質問するのだけれども、でも、そういう法改正なり新たな仕組みをつくっていかないと、やはりほかの自治体であった例が、どうしてかまたもやあるわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"部長のご説明にあった中で、子ども育成課の中にすまいるが入って、児童センターに所属するというのが平成２７年度からとあったのですが、平成２６年度にそういう仕組みにしなければいけないというか、課題があって、それで、それを解決するためとか、さらによりすまいるの運営がうまくいくため、どんなところからこういった児童センターのほうに所属替え、あるいは明確にしたというのでしょうか。","respondent":"伊崎子ども育成課長","answer":"それに当たりまして一体化をしたところですが、人事面からもいろいろございまして、平成２６年度までは、言ってしまえば、すまいるスクール係という１つの大きな係で、３７カ所出先を持つという、通常ない形の係でございましたが、それを児童センターの中に組み入れることで。","voiceIndex":117,"id":"exchange-033"}]},{"id":"topic-03","title":"平成２６年度品川区立学校における体罰等実態把握","agenda":"平成２６年度品川区立学校における体罰等実態把握","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"第三日野小学校のこの体罰というのは、この生徒の子は何年生で、性別はどちらでしょうか。","respondent":"渋谷指導課長","answer":"体罰の被害を受けた子どもは、６年生の男児です。","voiceIndex":124,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺の経過を教えていただきたいのと、一番心配なのは、この体罰を受けた児童またはご家族の方へのその後のケアというか、どういうことがされていたのかというのと、あと、この体罰が起きてしまった背景というか、原因などもどのように調査されたり、対策がとられているのかということも聞かせてください。","respondent":"渋谷指導課長","answer":"ケアについてですが、きちっと担任の先生と子どもとの関係ができるまで、約１カ月強ございましたが、教室には直接子どもとかかわらないというような期間をとりまして、じっくりと子どもと人間関係が構築できるような対応をとらせていただいたところです。","voiceIndex":126,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"停職１カ月ということだったのですけれども、これで済んだのでしょうか。ご家族の方の感情とか、その辺は特別なかったのでしょうか。ちょっと聞かせていただきたいと思います。","respondent":"渋谷指導課長","answer":"ご家族のお気持ち等々、なかなか個人のことなので、難しいところではあるのですけれども、事案が発生したのは５月１４日で、その後、６月２日に日光移動教室がございました。","voiceIndex":128,"id":"exchange-036"}]},{"id":"topic-04","title":"臨時福祉給付金および子育て世帯臨時特例給付金の実施","agenda":"臨時福祉給付金および子育て世帯臨時特例給付金の実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"お願いします。それで、やはり前回が１万円だったのに、３,０００円になってしまう。併給できるからというのをお聞きしたので、では、併給できるのは何人ぐらいなのかというのをお聞きしたかったのですけれども、これだけ下がってしまった理由は何でしょうか。","respondent":"廣田臨時給付金担当課長","answer":"考え方として、平成２６年度につきましては、平成２６年４月から消費税が上がりまして、平成２７年９月までの期間を見込んだ数字ということです。","voiceIndex":137,"id":"exchange-037"}]},{"id":"topic-05","title":"認可保育園等の新規開設","agenda":"認可保育園等の新規開設","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"質問ではなくて、委員長にお願いがあるのですけれども、ただいまのご説明の中での株式会社の認可保育園、また、区立幼保一体施設、あと小規模保育事業という３つなのですけれども、さまざまな保育施設ができていますので、ぜひ視察を考えていただきたいと思いますので、よろしくお願いいたします。","respondent":"塚本委員長","answer":"わかりました。こちらの理事者と、また委員長、副委員長で検討します。","voiceIndex":143,"id":"exchange-038"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋（し）委員","kind":"意見","question":"小学校が逃げて、幼稚園のほうは園内で待機という判断の違いは、それぞれの校長先生と園長が判断されて、要するに、校長先生のほうの判断で外で、あと、園長の判断で中でというところなのですが、何もなかったのでそれぞれいいのですけれども、そこはどういった違いが出たのかなと思いました。","respondent":"品川庶務課長","answer":"こちら、違いというところは、当初、火事のため煙が大分出ていたということで、まだ火事当初のときは煙が薄かったので、小学生のほうはすぐ移動という形になったのですが、幼稚園のほうは、やはり煙が少しでも出ているということで。","voiceIndex":154,"id":"exchange-039"},{"speaker":"塚本委員長","kind":"提案","question":"ほかによろしいでしょうか。本年の文教委員会におきましても、当委員会における所管事務の中から、年間を通して協議していきたい課題、また、常に意識しておくべき事項等について、委員の皆様よりご意見・ご要望を聴取し、そうした課題・事項を本年の文教委員会のテーマに掲げ、所管事務調査および行政視察を通して、具体性を深めていきたいと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4854#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":61196,"voices":157}},{"id":"h27-20150608-5","meetingId":"h27-cm06","date":"2015年6月8日","dateIso":"2015-06-08","committee":"総務委員会","time":"午後 １時００分～午後 ３時３３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"総務部の平成２７年度主要課題の中に、非核平和都市品川宣言がありますけれども、平和事業にかかわって伺いますが、今、国会で質疑されている戦争法案、安倍首相は平和安全法制と呼んでいますけれども、品川区はこの戦争法案は、憲法に照らして違憲立法だと考えているのか、この事業のかかわりで伺いたいと思います。","respondent":"江部総務課長","answer":"平和に関するお尋ねの中で、国の法案ですが、こちらにつきましては、これまでの品川区の方針といたしまして、国政にかかわることについて言及する立場にはございませんという立場です。","voiceIndex":59,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"改めて伺いますけれども、これでどうして核兵器の廃絶や恒久平和が実現するのか、区民の生命・財産が守れるのか、この点を伺いたいと思います。教育大綱の策定ですけれども、区が示す大綱がどのような内容なのか、伺いたいと思います。ぜひ、早くに、区民はもちろん、議会にも日程を示すべきだと思いますけれども、この点についてもいかがでしょうか。","respondent":"江部総務課長","answer":"総合教育会議、本日から見て明日というのは確かに性急ですが、１週間前にホームページで公開しているところでございまして、当初のプレス発表の中でも、５月か６月ごろ、大体１回目が開催予定ということでございましたので、特に支障はないと思うものです。","voiceIndex":61,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"総合教育会議について、大綱についてどのような内容かと伺ったので、その中身についてと、それと今、１週間前に発表しているから問題ないのだと、それは問題だと思うのです。今回の事態を受けて、マイナンバーにかかわらず、品川区はたくさん情報を持っているわけですから、何か新たな対策を今検討をしているのか。不安も広がっているだけに、現状をご説明いただきたいと思います。","respondent":"江部総務課長、仁平情報推進課長","answer":"１週間前は遅過ぎるのではないかという点につきまして、第１回を実施するに当たりまして、かなり検討を要したという事情もございまして、ぎりぎり１週間となったのですが、日にちだけでしたら、もう少し早くお知らせできたのですが。こちらのほうも、現在、区民の方々の情報を管理する立場としまして、同じような安全対策を十分検討していきたいと考えています。","voiceIndex":63,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、最後にまとめて、経理課と監査についても伺いたいのですけれども、経理課については、契約日のことなのですが、大井町駅前、広町の区有地ですけれども、現在は劇団四季と駐車場に貸して、この駐車場が６割、今後、保育園になるという話はもう既に補正予算のときに説明があるのですが、残りの４割について、６月で契約が切れるという話ですから、この残りの４割についての契約日というのはいつなのか。","respondent":"江部総務課長、立川経理課長、齋藤監査委員事務局長","answer":"総合教育会議での協議事項につきましての議会報告の考え方ということにつきましてですが、こちらにつきましても、明日の総合教育会議で。新規の契約として７月１日から、これまでどおり時間貸し駐車場ということで、現在、契約者の選定手続を進めているところです。議員の選任ですが、地方自治法第１９６条に、いわゆる識見監査員と議員のうちから監査委員を選任するという規定があります。","voiceIndex":66,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"契約日について、私の言い方がまずくて、７月１日から新たな契約が始まると思うのですけれども、その契約をするのがいつなのかということを伺いたかったので、それを教えてください。","respondent":"立川経理課長","answer":"６月１１日に入札を実施いたしまして、入札後すぐ契約ということになります。","voiceIndex":70,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後について、契約として、総務委員会なのか、それとも用途にかかわって、駐車場というのは、いわゆるまちづくりという要素があると建設委員会なのか、また、保育園の部分は文教委員会なのか、いや、公有地活用で一括して行財政改革特別委員会なのか、いろいろ議会でも調整がもちろん必要だとは思いますけれども、今の契約に関して、ぜひ。","respondent":"立川経理課長","answer":"今回の普通財産の土地の貸付けにつきましては、公有財産管理規則に則り行っておるものですので、契約等を延期する考えはございません。議決案件につきましては、地方自治法に定められておりますので、その規定のとおり実施していきたいというふうに考えております。","voiceIndex":72,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしたいのですが、今回、企画部の中で、企画調整課、財政課というふうに明確に分かれたのですが、実際、どちらが主導権をとるのか。例えば、企画が今後、品川区の区政運営、計画を立てるに当たっては、必ず予算というものがなければ、予算という計画は立てられない。明確に説明できるようにしてもらうとありがたいのですが、教えてください。","respondent":"柏原企画調整課長","answer":"そこで役割が分かれている部分もあるのですけれども、ただ、先ほど申しましたように、予算というのはやはり一番大きなファクターでありますので、そこの部分については、例えば予算の作成とか策定段階においては。","voiceIndex":74,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"それだと、今後、品川区のいろいろな事業計画云々に関しては、企画調整課のほうに質問する、説明を求めるということでいいのですか。何かをやるには必ずお金が絡む。でも、どちらに聞いたらいいのかというのが迷うところが今あるので、そこはどうなのですか。","respondent":"柏原企画調整課長","answer":"ただ、財政計画とか、どうしてもお金が絡んでくるところがあります。そこの部分については、我々でお答えする部分もあるでしょうし、場合によっては財政課としてお答えする部分もありますので、何かお困りのことがあれば企画調整課で聞いていただいて結構です。","voiceIndex":76,"id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"細かいことですが、広報広聴課の中で電子アンケートというのがあったのですけれども、１５ページ。これは随時実施とありますけれども、あまり私、認識していない。これはどの程度、平成１５年からどんな感じでされていったのでしょうか。","respondent":"中元広報広聴課長","answer":"平成２５年度に少しシステムを修正していますが、実際に運用を行っております。実績としては、平成２６年度２件、実施をさせていただいてあります。中身としては、しながわガイドについてと区ホームページについて実施をしたところです。","voiceIndex":78,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"選挙管理委員会なのですけれども、つい昨日ぐらいだったでしょうか。要は、選挙人登録に関するタイムラグで、二十歳になってすぐに引っ越してしまったら、二十歳を過ぎていても登録ができないというようなことが国の方でも話にでておりましたけれども、こういうことというのは、自治体レベルで何か救済策を設けることはできるのでしょうか。","respondent":"工藤選挙管理委員会事務局長","answer":"現在のところ、公職選挙法の中でそのような形で、いわゆる救済という形であれ、今の制度の中では選挙権が発生しないですので、各自治体で救済という部分は難しいというふうに思っております。","voiceIndex":80,"id":"exchange-010"},{"speaker":"あべ委員","kind":"意見","question":"であれば、もう国の動向を見守ってということになるのかと思いますが、今後、１８歳への選挙権引き下げなどもありますので、広く選挙権がきちんと行使されるような形で、新しい制度をご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":82,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"今後、やはり区民の意見を広く聞くというものは大事だと思うのですけれども、どういうふうにもっと広げようとしているかとか、力を入れようとしているかとか、その辺の考えを教えていただけますか。","respondent":"中元広報広聴課長","answer":"本年度につきましては、テーマ別方式を２回ほど予定してございまして、現在はまだ調整中のところです。今後につきましても、区民の方々から直接意見を聞ける機会ですので、このような機会を大切にしていきたいと存じ上げているところです。","voiceIndex":83,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"公募方式というのは、広く募って、来た人はみんなという意味ですか。","respondent":"中元広報広聴課長","answer":"やはり会場の制約もありますので、人数を抽選等で絞らせていただいてあります。","voiceIndex":85,"id":"exchange-013"},{"speaker":"あくつ副委員長","kind":"質問","question":"企画部の１７ページのシティプロモーションなのですけれども、予算特別委員会でも同じ質問が出たと思うのですが、今後のスケジュールというか方向性というか、シティプロモーションとしての打ち出しをいつぐらいの期間にお考えなのか、今後のスケジュールを教えてください。","respondent":"中元広報広聴課長","answer":"今後のスケジュール感、大雑把なところですけれども、現在、戦略プラン案の最終調整を図っているところでございまして、今後は当総務委員会のほうにも、今月下旬のところの総務委員会でご報告をさせていただいた上で、またまとめてまいりたいと思っているところです。","voiceIndex":89,"id":"exchange-014"}]},{"id":"topic-02","title":"特別区全国連携プロジェクト","agenda":"特別区全国連携プロジェクト","exchanges":[{"speaker":"本多委員","kind":"質問","question":"それぞれの特色を出す必要があるかと思うのですけれども、その点と、あとは、これは全国の市町村と交流等を図られるということで、従来の市町村交流とどこがどういうふうに違うのか。行政間のつながりとか、情報を共有したり、人と人の交流とか、すごいすばらしいことだと思うのですけれども、ただ、それにかかわってくる予算面とか、その辺は従来とどう違うのか、その辺を教えてください。","respondent":"柏原企画調整課長","answer":"この連携に当たってのやり方という部分だろうかと思いますけれども、２３区が画一的というところではなくて、このプロジェクトが立ち上がって、全体として動く話がたまたまその東北六魂祭のお話であるとかといったところがあって。","voiceIndex":95,"id":"exchange-015"},{"speaker":"あべ委員","kind":"質問","question":"ちょっとよくわからないのですけれども、立ち上げとありますね。誰がいつ立ち上げて、どういうふうに立ち上げることを進めて、予算は一体どこから出てきて、誰が事業を回していくかというのが、この１枚ではどうもよくわからないのですけれども、時間と主語を入れて経緯を教えていただけますか。","respondent":"柏原企画調整課長","answer":"そういったところから、地方の発展に協力するためにどういった対応ができるのかというのを２３区の特別区長会のほうで検討してきたといったところです。","voiceIndex":97,"id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"お金はどこから出てくるのでしょうか。実際に運営する自治体がホームページを維持するだけでもコストはかかるでしょうし、それ以上に、先ほど２,３００万円というような数字も出てきましたし、これは新たに各区から一定額を毎年徴収というか、拠出するような形でやっていくのか、その都度ごとに集金をされるのか、どういうことになっているのでしょうか。","respondent":"柏原企画調整課長","answer":"先ほどの六魂祭のお金につきましては、これは特別区長会のほうで、この六魂祭に支援事業費で出しますということで、２,３００万円なのですが、これは公益財団法人の東京都区市町村振興協会の助成金の制度を使って、それを助成金ということで活用したというものでございまして。","voiceIndex":99,"id":"exchange-017"},{"speaker":"あべ委員","kind":"質問・要望","question":"全体に、いいことのような気もするのですけれども、例えば地方の課題というのは、すごくたくさん重たいものがあって、例えば限界集落で人口が足りませんとか言われても、２３区としてはどうしようもないわけですし、少子化対策したい、子どもを産む世代の女性がいませんとか、産業が足りませんとかと言われても、２３区として、では、うちの企業を送ってあげるとか、そんな解決はできないわけではないですか。","respondent":"中山企画部長","answer":"そういうツールでやっていこうというふうな一つですので、これで根本的に変わるものではありませんが、こういう方法もとりながら、それぞれが繁栄していく、よりよい地方創生の形をつくっていくための一歩目であるというふうにお考えいただければと思います。","voiceIndex":101,"id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"どんなアンケートを送ったか文面もわからないので、何とも言えませんけれども、地方の課題を聞いて、では、それを２３区が何とかしてあげましょうというような関係のプロジェクトにしてはいけないし、そんなことはできるわけないと私は思っているのです。重ねてお答えいただいていいですか。","respondent":"中山企画部長","answer":"それを少しスケールメリットと申しますか、そういうツールを使おうですので、前段のような背景といいますか、きっかけのようなものを前面に出してやるようなものではございませんので、ご指摘のような趣旨も踏まえながら、特別区全体で取り組み、また。","voiceIndex":103,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば、交流というのはとても大事だと思うのですけれども、都市や地方の問題の解決にどういう関係をここで見ているのか、ちょっとそこを伺いたいと思います。この資料の趣旨のところ、おそらく特別区長会で出された資料の抜粋なのかとは思うのですけれども、例えば、地域の活性化が求められているとありますが、これは２３区を指しているのか、それともそれ以外の地方を指しているのか。","respondent":"柏原企画調整課長","answer":"ですので、最初の説明であれだったかもしれませんけれども、これも全てということではありませんので、特別区と全国と連携しながら、ここにありますとおり、共存共栄に向けた形で両方が活性化することが日本にとって先への一歩なんだという趣旨で動いているものです。","voiceIndex":105,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"私も議員になって、いろいろ行政視察で行きますけれども、東京に吸い取られているというような感じをいろいろなところでよく伺うだけに、まずは、共存共栄とこちらから言う前に、自分たち自身が、また２３区自身が人、金、物の一極集中を進めてきたことへの真摯な検証や対策を自ら進めていくという視点がまず必要なのではないかと私は思うのですけれども、その点についてはいかがでしょうか。","respondent":"柏原企画調整課長","answer":"これは特別区が地方に対して、共存共栄という言葉を言っていますけれども、地方に対して何か、言葉は悪い言い方かもしれませんが、何かおせっかいしようとかということではなくて。","voiceIndex":107,"id":"exchange-021"},{"speaker":"あくつ副委員長","kind":"質問","question":"２,３００万円支出をして、どういう効果があったのかということと、あと、この前、私もＥＣＯフェスティバルに伺って、雪が会場にあって、先ほど北上市という例を出されましたけれども、これは先ほどのアンケートをとっていく中で交流が生まれたということなので、今回の動きの中で生まれたということで例に出されたのかどうかということ。","respondent":"柏原企画調整課長","answer":"六魂祭等のイベントの経緯です。アンケート等は実施はしておるのですけれども、まだ共通的に何か情報を得るようなツールはでき上がっていないというところもあります。","voiceIndex":109,"id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"意見","question":"アンケートのほうは、まだ分析結果でフィードバックはないということでよろしいかと思うのですが、まだ集めている最中なのですけれども、先ほど私もいろいろな議論を聞いていて、多分、受け取ったほうも趣旨がよく伝わっていないのかなというところもあるでしょうし、先ほど部長からも、最初の一歩だというお話もありましたので、決して悪いことではないと思うのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"こっちから、あんたのところ大変だろうと、だから一緒に組んで、ともに共存共栄、活性化に協力すると言っても、また、大都市は大都市で抱えている悩み、今後の大きな問題点もあるし、では、自然の流れに逆らって、構造変化が変わっているのに、それを手助けして、どこまでできるのだということもあると思うので、せっかく特別区長会でこういうふうにやっていくということですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"私も、基本的には全国で連携していくというのはすごくいいことだと思います。ぜひ、そういうふうに進めていっていただきたいというのが意見なのです。質問としては、さっきご質問が出ましたけれども、このアンケートの中身とか、どういうアンケートをとるのかとか、それからそれへの答えがどういうものなのかとかということを、私たちは知ることができるのでしょうか。","respondent":"柏原企画調整課長","answer":"アンケートの部分については、詳細の部分はまだおそらく、どこまで出るかというのは確認はしていないのですけれども、概略の部分でお話ししますと、地方の方に対して、住民とか企業に関する提案が何かありますかというようなことを聞いたりだとか、それから。","voiceIndex":113,"id":"exchange-025"}]},{"id":"topic-03","title":"債権放棄","agenda":"債権放棄","exchanges":[{"speaker":"吉田委員","kind":"意見","question":"この債権の放棄についてはわかりましたが、私、全然把握していなくて、どうしても破産手続とかになると債権放棄せざるを得ないと思うのですけれども、こういう事例は、どれくらい起きる、または起きることを見込んでいらっしゃるものなのか。","respondent":"福島会計管理者","answer":"こちらは、見込みというのはなかなか難しいのですけれども、例えば、一番多いのは奨学金の貸付けで時効になったりですとか、あるいは今回のような使用料、あるいは住宅ですとか、そういうところはあります。","voiceIndex":119,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"そうしたら、聞き方を変えまして、今まではどんな感じというか、１年間でどれぐらいあったのでしょうか。もちろん年によって違うと思いますけれども。","respondent":"福島会計管理者","answer":"まとめて第３回定例会で全体の報告をさせていただきたいというふうに思っております。","voiceIndex":121,"id":"exchange-027"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"一つだけ。平成２２年度が基準になっているわけですよね、マイナス１５％の。今までもマイナス１５％を目標にして行われてきたのだと思いますが、その実績は教えていただけますか。だから、マイナス１５％を目標にしてきたが、どれくらい実績が上がっているのか。","respondent":"江部総務課長","answer":"平成２２年度を基準といたしましたということは、まず、最大需要発生日というのが平成２２年の７月にあったということから、そこから比較しての１５％なのですが、たしか記憶によりますと、年によって達成できた年と１５％にいかなかった年とあるかと思います。","voiceIndex":127,"id":"exchange-028"},{"speaker":"あべ委員","kind":"確認","question":"一点だけ、ここでわかれば確認したいのですけれども、この避暑シェルターですが、これは区施設でされていますか。民間で手を挙げたところなどもなっているのでしょうか。おわかりだったら。わからなければ、また別であるのでしょうが。","respondent":"江部総務課長","answer":"ちょっと環境課で把握しているかは今わかりません。","voiceIndex":131,"id":"exchange-029"},{"speaker":"あべ委員","kind":"確認","question":"民間でそういうふうなものをお持ちの方もいらっしゃるみたいなので、両方で可能であれば活用できればと考えていますので、ご確認いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-030"},{"speaker":"本多委員","kind":"意見","question":"この過去の調査項目等を見て、いろいろと考えてまいりました。たくさんあるのですけれども、その中で２つだけ絞って、一つは人材育成。これは行政に限らず、民間に限らず、全ての角度から人を育てるという観点。シティプロモーションと同じですけれども、そういった幅広い意味で着眼していただければと思います。ほかにもたくさんあるのですけれども、まず２点を案として述べさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":136,"id":"exchange-031"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"それと、先ほど自民党の本多委員のほうからありましたけれども、去年やったばかりですけれども、シティプロモーションということについては、これも先ほどのお話だと、間もなく報告が出るというようなことでおっしゃっていられていましたので、もうちょっと幅広い観点ですけれども、取り上げていただきたいという気持ちがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-032"},{"speaker":"中塚委員","kind":"意見","question":"もう一つは、マイナンバー制度、番号制度、特に個人情報のセキュリティ対策が現状どうなっているのか、どういう対策が今は必要になっているのか、現状を十分に把握した上で調査研究を深めたいと思いますので、マイナンバー制度についてというよりも、個人情報のセキュリティについてというのを特に中心にやりたいということで、その２つです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":138,"id":"exchange-033"},{"speaker":"あべ委員","kind":"質問・要望","question":"内容の前に、今後の所管事務調査を決めていくスケジュールを委員長、副委員長のほうでどのようにお考えなのかを教えていただきたいと思います。今回、意見聴取して、次回に向けてということなのですか。そのスケジュールをまず教えていただけますか。","respondent":"松澤委員長","answer":"６月１２日までに、とりあえず調査項目を各会派でありましたら、今は意見聴取をしていますけれども、出ない場合は出していただいて、それを正副委員長、理事者等と協議して進めていきたいというふうに思います。","voiceIndex":139,"id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"会派の中でまだきちんともんでいないので、書面のほうにしたいと思いますけれども、一つ考えているのは、やはり情報化と言ったらいいのですか、議会も本年度、ＩＣＴ化というのは取り組みたいと思っているのですけれども、品川区のほうでも、よりＩＣＴ化を図っていくとともに、特に情報発信の部分です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-035"},{"speaker":"須貝委員","kind":"意見","question":"今回、企画調整課ができたということで、今後、企画部のほうでも考えていくのでしょうけれども、できれば大都市の問題等について考えていったほうがいいのではないか。地方は地方の悩みがあるのでしょうが、都市は都市で、また多くの人口を抱えて、これからどういう方向性を持って、抱負を持って品川区が取り組んでいくのかということも、所管事務調査として考えたほうがいいのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":142,"id":"exchange-036"},{"speaker":"中塚委員","kind":"意見","question":"次回以降でいいのですけれども、今の話ですと競馬組合のほうからお話があったということですけれども、もしわかれば、ほかの区議会がどういう対応をされているのか、次回以降、わかるところでご説明いただけたらと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":144,"id":"exchange-037"},{"speaker":"須貝委員","kind":"提案","question":"地方へ行って、電車に乗って、飛行機に乗っていって、ほとんどの町並みにシャッターがおりていたり、実際、予算が毎年削減されている状況を見ると、そこで視察して参考になることは少ないのではないかというふうに思うのですが、その辺のことも、やめるということも考えられたらいかがでしょうかという提案をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":146,"id":"exchange-038"},{"speaker":"あべ委員","kind":"意見","question":"むしろ予算がないからこそ、いいアイデアが出てくるようなところもありますし、これまで行ったところも、当たり外れという言葉を使ってはいけないのかもしれない、やはり品川区としてすごく参考になる内容を学べたところもたくさんありますし、あるいは防災関係など、その場でなければわからない被災地の事情などは、やはり行ってよかったと思いますし、どちらかというと無理くり感があったようなこともあり。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":147,"id":"exchange-039"},{"speaker":"中塚委員","kind":"意見","question":"テーマは次回以降ということですけれども、今日少し話になったので、今、品川区政が抱えている問題が何で、それを解決するには現地に行って見たり聞いたり、また、状況を把握しなければわからないという状況に、やはり委員会としてもよく議論を深めていくところから始まるのかと思うのです。テーマは次回までに考えておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2016#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":50280,"voices":149}},{"id":"h27-20150609-14","meetingId":"h27-cm06","date":"2015年6月9日","dateIso":"2015-06-09","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時３０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"簡潔に、羽田空港の件につきまして質問します。この説明を、八潮地域での開催ということがご検討いただけるのか、お知らせいただきたいと思います。そして６月２１日付の広報でこのことを載せるということでありますが、この内容を少しお知らせいただきたいのと、例えばこのお知らせを八潮地域の皆様に全戸配布していただくような、そのことのお考えがあるかどうか、お知らせいただきたいと思います。","respondent":"中村都市計画課長","answer":"それと６月２１日付の広報の内容ですけれども、私が先ほどご説明を申し上げました新しい飛行経路案というものが、今検討されていますというような記事の内容というふうに聞いてあります。","voiceIndex":37,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"提案","question":"何点かまとめて確認します。国家戦略特区のところで気になったのが、資料の別紙３「国家戦略特区における品川区想定事業案の関係」の表の、追加提案事業が、提案したということは聞いたんですけれど、その後どうなったのかということをぜひ知りたいです。いつ頃これが審議されるのか。それから採択された後、品川はどういうふうに考えていくのかということの確認をお願いしたいということです。","respondent":"柏原企画調整課長、中村都市計画課長","answer":"聞くところによりますと、別の区でも似たような提案をするというような話もございましたので、東京都だけではなく国のほうにも提案しながら、この追加提案事業１については何とかできないかということで、話を進めているところです。騒音の測定ですけれども、こちらは基礎的なデータといたしまして委員ご指摘のとおり、大変重要なものであると認識しております。この測定の場所につきましては、慎重に選定してまいりたいと考えています。","voiceIndex":39,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"オリンピックを当然見込んでこのことを品川区も計画していたんでしょうから、それは当然東京都にとってもプラスになると思われるので、なぜこういうことについて東京都がなかなか判断してくれないのかということが、もしわかったら教えてください。それから、場所によっては季節の要因も違ってくるでしょうし、建物の密集具合によっても相当違ってくるわけじゃないですか、騒音の測定というのは。","respondent":"柏原企画調整課長、中村都市計画課長","answer":"ただ、我々も１年間、東京都とこの特区の関係をずっとやりとりしていますと、かなり区側も積極的なプッシュといいますか、をしないと、なかなか難しいというのは、これは都に対しても、国に対してもそうなんですが。騒音の測定につきましては、高度によって違うですが、今、品川区内１,５００フィートあるいは１,０００フィート、またそれ以下のエリアについても、これはそれぞれの地域の実情もございまして、国土交通省のほうでは飛行制限が。","voiceIndex":42,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ただ、対象地域が何百万人住んでいる地域だから、それは理論的にできない話だと思うのですけれども、でもせっかく国土交通省からそういう話をいただいている以上は、せめて品川区・大田区も含めて、この地域だけに限ってはもっときめ細かい説明会といったらいいのか、大井町駅周辺だけでなくて、先ほど出た八潮団地も含めて、そういうようなことを品川区としては当然要望していってもいいと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"最大の対策というのは、この案自体をきちんと、中止も含めて見直していくということだと思うんですね。やはり品川区に果たしていただきたいというか、果たさなくてはいけない役割ですけれど、繰り返しになるかもしれないですが、区民の住環境と安全を守るために役割を果たすべきだと思っていまして、例えば新宿のほうですと、こんな要望をしているようです。そこをお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"その上で地域の住民の方への説明と、それから国のほうへも、またさらに必要な情報について求めていきながら、その辺の地域に対する対応について、区としても国へ要望を伝えつつ、調整をしていくという形になると考えています。","voiceIndex":46,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、しっかり説明してもらうことが大事だということは、もう重々わかりました。そうした説明会ですけれども、具体的な中身でちょっとわからなかったのが、第１段階、第２段階とありますけれども、第１段階がこのようなオープンハウス型ということになって、第２段階は違う形で説明会を開くということなのか、そこら辺がちょっとわからなかったので、あわせてお伺いします。","respondent":"中村都市計画課長","answer":"それと説明会の進め方ですけれども、オープンハウス型が国から示されておりますけれども、これは広く一般の皆様方の意見を聞きたいということから、こういった形になったですけれども、この後このいただいた意見等をもとにしまして。","voiceIndex":48,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"全体として狙いとしては、品川区がこの事業を区内でやる狙いとしては、どこに軸足を見ているのかというのもあわせてお伺いしたいんですけれども、外国企業や労働者の皆さんが、快適に働いて居住できる都市をつくろうという、そういう目的になるわけですか。","respondent":"柏原企画調整課長","answer":"それをとらまえて区として何ができるのか、区のほうも今後の国際化に向けての対応であるとか、にぎわいの創出であるとか、そういった区の幾つか持っている施策に通じるものがある部分については。","voiceIndex":50,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"でもなぜそんなに主体的にやりたいんですかというのが、今の答弁でわからなかったので聞きたかったんです、そこをもう一遍お聞かせいただきたいと思います。","respondent":"柏原企画調整課長","answer":"そういったところで国際化であるとか、住んでいる方がより快適に住みやすく、またほかの自治体から品川区に住んでいただけるように、そういったところを進めていきたいということの一つとしては、この国家戦略特区という手法が有効であろうというところがありますので。","voiceIndex":52,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですからこうした矛盾が出てくるのではないかと思いました。最後に、今言ったようなところで、品川区でこの特区事業を実施していくことの、区民にとってのメリットといいますか、どうしてもわからないので、もし何かあれば教えていただきたいと思います。","respondent":"中山企画部長","answer":"この特区制度は、冒頭から説明申し上げているように、いろいろな経過の中で国際的なこの間の声も含めて、ビジネスをしやすい、それだけでなくて区民にとってもメリットがあるというものをいろいろ考えながら提案していくわけです。","voiceIndex":54,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"今の経済状況、区民の生活状況からしても、保険料など負担増が続いていますし、厳しさが増していますし、貯蓄ゼロ世帯はどんどん増えているわけですけれども、これだけ私たちから集めた税金を基金としてどんどん積み上げているというのは、やはり異常ではないかと私は思うんですが、公共施設整備基金と財政調整基金、義務教育施設整備基金、地域振興基金、それぞれについて、増やしている。","respondent":"秋山財政課長","answer":"公共施設整備基金、財政調整基金、義務教育施設整備基金、地域振興基金の目標額というか、考え方ですけれども、財政調整基金につきましては、これはいろいろな評価はありますけれども、例えば一般財源が８００億円相当ありますので、その１０％を２年間分ぐらい積み立てておけば。","voiceIndex":56,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"そもそもこの基金が増えている状況があるんですけれども、増やせなければ増やせないわけであって、増やそうと思って増やしていると思うんですけれども、どういうふうにして増やしているのかというのをあわせてお伺いしたいと思います。増やしたくても増やせないときは多分あると思うんですけれども、どのようにして品川区はこの基金を積み上げて増やしているのか、そこら辺もお伺いしたいと思います。","respondent":"秋山財政課長","answer":"基金に関しては、一般の家庭で収入と支出のことを考えていただければよくおわかりになるかと思いますけれども、今の時点で税収が伸びております。","voiceIndex":58,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"私がさらに、ちょっとこの場ではあれですけれど、歳出の分ですね、何を抑えているかというのは、税収が伸びているというのは人口は増えていますし、住民税増えていますから、そういうのはわかるんですけれども、なぜ歳出も抑えて、どこを抑えているのかというのもちょっと今日答弁できる範囲で答弁していただいた後、これも深めていきたいところなので、ぜひよろしくお願いしたいと思います。","respondent":"秋山財政課長","answer":"その中身につきましては、必要なところに必要なものを使っているという認識ですので、特にどこが足りている、足りていないというようなことは、今申し上げることではないと考えております。","voiceIndex":60,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"羽田空港を１点だけお伺いしたいんですけれども、きめ細かく説明会をこれからしていくというお話ですが、改めてお伺いするんですけれども、この説明会の目的についてお伺いします。","respondent":"中村都市計画課長","answer":"この説明会の目的ですけれども、まずはこの新しい提案の飛行経路案、この中身について地域の皆様方に理解していただきたいというところが、国が目的とするところというふうに聞いてあります。","voiceIndex":62,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"中身について理解してくださいということもあると思うんですけれども、私はこの説明会をする地域の方が、いろいろな不安とかがある中において、説明することによって安心をするということが一番の目的だと思うんですけれども、改めてそこは、いわゆる理解だけしなさいというのだったら、上から落として、これこれこういう状況で、こういう理由があるから理解しなさいで、それでは説明会の意味が。","respondent":"中村都市計画課長","answer":"そういったところで今回の国の説明会のご案内の中にもありますけれども、意見、質問、また懸念等、こういったものを伺ってまいりますということで、その中には当然不安等のご意見もありますでしょうし、そういったものを伺った上で、さらに次の対策を考えていくというのが。","voiceIndex":64,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"で、羽田空港に入っていくと。この辺についてはいかがでしょうか。","respondent":"中村都市計画課長","answer":"そういった中で、この飛行経路そのものが市街地の上空を飛ぶということに対しましては、国としてはやはり安全対策を万全に整えるという、そういったことを努力として行うということが最大の方法であり、これは予防しかないですので、そういった説明がありますけれども。","voiceIndex":66,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長の答弁もわかるんですけれども、大惨事が起きないいわゆる予防といいますか、をしてくださいと。でも、１００％飛行機は落ちませんとは言えないわけですよね。だからそこがものすごく、この案件、難しいですよね。そのことだけは頭によく入れて、担当部署としては区民の安心・安全を守る一番身近な自治体なわけですから、やっていっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"ここの再開発、当初はこういう特区という話もないところから始まっているので、再開発ということでしてきたところで、後追いでこの特区ということでの事業が想定されるようになってきているのかと、そういう経緯かなと思うんですけれど、今後この２つをどういうふうに、関係というか、相互に影響していくというか、この同じ地区の中でどのようなことを進めていくのかというところでの説明を。","respondent":"溝口都市開発課長","answer":"さらに今後のできた施設、建築物をどのように利用していくのか、そういったところの観点の中で、場合によっては外国人の居住とか、またサービスアパートメント、そういったものもできるのではないかというところで、もうまさに事業の中で事業者とともに検討している段階ですので。","voiceIndex":69,"id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"それとも、やはり話し合いの中で、建てていく中でそういうことがあり得る話なのか、あり得るとなったときには、そこに権利変換で等価交換で戻ってこられる方々もいらっしゃるので、そういう方々に対しての説明も必要になってくると思うんですけれど、その辺のことをどのように考えているのか、もう一度お伺いします。","respondent":"溝口都市開発課長","answer":"当然今後事業に国家戦略特区を使うに当たっては、権利者の方々を含めて十分説明しながら、実際の適用に当たっては進めていきたいと考えているものです。","voiceIndex":71,"id":"exchange-018"},{"speaker":"塚本委員","kind":"確認","question":"大井町の上空約３００ｍというお話を先ほど聞きまして、ただ実際本当に、ほかの委員からもいろいろお話が今までありましたけれども、それがどの程度のものなのか、今の飛行機が通ったときどの程度の騒音があるのか、やはり実際に体感してみないとどんなものか実感がなかなか湧かないところもありますので、この調査のスケジュールのところに、日時等はまだ出ていませんけれども。","respondent":"三ツ橋環境課長","answer":"必要に応じまして皆様にお知らせしていく予定ですので、実際にどのようになっていくのか、具体的にまだ詰めている段階ですので、スケジュールに関しては現段階でははっきりとは決まってございません。","voiceIndex":73,"id":"exchange-019"},{"speaker":"たけうち委員","kind":"確認","question":"国家戦略特区で確認なんですけれど、別紙３で特定事業が１から４までありますけれども、この中で大崎関係については先ほどのご説明で、６月中旬に認定を受けるということですよね。というのは、今後その跡地、またその跡施設をどうするかというのを検討していくに当たっても、まずそういう需要があるのかどうかということを区がどうつかんでいるかというのがあれば教えてください。","respondent":"柏原企画調整課長、中村都市計画課長","answer":"それから特定事業４につきましては、先ほどほかの委員からも出ましたけれども、この地域の開発の部分でどういった形で活用できるのかというのを含めて、検討しています。聞いたところでは音をやはり出すということは聞いているんですけれども、それが騒音を出すのか、あるいはディスプレイに何か説明のビデオを流すのか、その辺、音を出すらしいというところまでは聞いておりますが。","voiceIndex":75,"id":"exchange-020"},{"speaker":"たけうち委員","kind":"提案","question":"そうすると国家戦略特区のほうは、まだほかの３つは提案もまだしていないということですね。それから公有地はまた別の機会にしますけれど、羽田のほうは、今度の説明会で何かしら音を出すということなんですかね。","respondent":"柏原企画調整課長","answer":"東京都との具体的な調整にまだ入れていないというのが現状ですので、今年度国家戦略特区がテーマになってありますので、ぜひともご意見を伺いながらというふうに思ってあります。","voiceIndex":78,"id":"exchange-021"},{"speaker":"松永委員","kind":"質問・要望","question":"私は１点だけなんですけれども、羽田空港の説明会についてですが、このときに多分アンケート調査とかされると思うんですけれども、そのとき集計数とか意見というのは、国交省のほうにこちらが聞くことができるのか。もしその中で、万が一ですけれども反対意見が多かった場合、区の対応としてどっやって行うのか、教えていただきたいと思います。","respondent":"中村都市計画課長","answer":"賛成、反対、さまざまな意見は今ご指摘のとおりだと思いますけれども、ただどちらの意見が強かったからといって、それに対してじゃあすぐ何かを決定するのかということではなくて、まず国に対して、反対なら反対なりの対応。","voiceIndex":80,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"だから決してそれは悪いことではないと思うので、大阪のことのお話を今させていただきましたけれども、恐らく探せばいろいろなケースも、都市部にある空港はたくさんあるわけですから、同じような問題を当然抱えている。そことうまく連携をとって、これから想定されるであろうさまざまな課題に対して、品川区ができるところはきちんと回答をしていくなり、考えていくべきと思うんですが、いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"いろいろノウハウを本当に教えていただかないと、今後非常にいろいろな、こちらも勉強していかないといけないと考えていますので、それは引き続き対応していきたいと考えています。","voiceIndex":82,"id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"ここに空港をつくることで、ほかの委員がおっしゃったように、なかったところに飛行機が飛んでくるわけですから。そういうことを調整していくために、具体的に連絡会議といったらいいですかね、年に何回かでもいいんですけれども、そういう情報交換をしながらこの問題に対処していくべき、具体的なことをぜひ検討していってほしいと思うんですが、いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"実際にどのような状況で連絡会などを持っていくかは、今後考えなければいけないと思っておりまして、実際に４区、品川区、港区、目黒区、大田区、この４区で今現在のところ連絡会は持っております。","voiceIndex":84,"id":"exchange-024"},{"speaker":"大倉委員","kind":"提案","question":"先ほどほかの委員からも、特区の事業提案のところで、今、見込み予定であってほかのところはまだ段階に応じてこれから提案していく中で、私たちのこういった委員会を通じてもさまざまな意見を聞いていきたいということで理解しているところなんですが、このスケジュールというか、いつまでにそういった、特区の指定を受けているので、いつまでだったら追加で提案できるというところだけ。","respondent":"柏原企画調整課長","answer":"国家戦略特区の、特に東京圏の場合は、区域会議でそういったところを議論する形になるんですが、この区域会議がどのぐらいの頻度で、どういう形で進めるのかというのは、なかなかちょっと見えてこないところがございまして。","voiceIndex":86,"id":"exchange-025"},{"speaker":"大倉委員","kind":"提案","question":"わかりました。ではさまざまな意見をまとめる中で、諮問会議、区域会議に諮りながら、その状況に応じて提案が認可されていくような流れになっていると。はい、わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"土地の活用のことなんですけれども、先ほども旧荏原第四中学校跡地の話がありましたけれども、私のほうでは特別養護老人ホームにしてほしいとか、防災施設にしてほしいということを聞いているんですけれども、区としてどういった声をつかんでいるかということをお聞きしたいということと、国家戦略特区のことですけれども、目標で世界で一番ビジネスのしやすい環境とあるんですけれども。","respondent":"柏原企画調整課長","answer":"大まかですが、そういった意味合いを持っているというふうに思ってあります。","voiceIndex":89,"id":"exchange-027"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"１点だけ。そうなると、例えばいろいろなところが来て、最後は大井競馬場なら２００ｍぐらいまでになってしまうとか、そういうことも議会としてちゃんと文章にして、だから強くこれを要望するんだということで、まさに今言っていた騒音の影響、こういうことが想定されるんだと、だからこれについては、影響調査を細かく実施してと。可能な限り市街地に影響を及ぼさない方策も考えてと。","respondent":"中村都市計画課長","answer":"国が今この案に対して、地域への説明を進めていくに当たり、ここまでの過程の中で、区としての意見も申し上げると同時に、また当然国土交通省も、議会からも要望事項が出されたということは十分認識をしておりまして。","voiceIndex":91,"id":"exchange-028"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"要望だけしておきます。今、このオープンハウス方式という何かよくわからないですけれど説明をやると。だけど国交省がここまでやったら、まあ、いろいろ丁寧に国もやっているなとか、そういう感覚が伝わってこないと、なかなか我々も、ここまでみんな一生懸命頑張ってやっているんだなというぐらい感じられるように、ぜひやってほしいというぐらいは、ぜひ伝えていただきたいと。これだけは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-029"}]},{"id":"topic-02","title":"国家戦略特区に関すること","agenda":"国家戦略特区に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"今回の特例の適用で、しながわ夢さん橋でイベントもやっていますし、一定フラッグなどもあるんですけれども、オープンカフェということでも少しはスペースがあるんですが、これがどのように変わるのかちょっとよくわからないといいますか、規制を外すことで何が変わるのかというのを、もう少し説明いただきたいんですが。","respondent":"溝口都市開発課長","answer":"ですから、エリアマネジメント活動を持続的に発展できる、継続できる、そういったことを進めていくために、今回、国家戦略特区の道路法の特例を使って、しっかり法的にも位置づけた形のイベントにしていきたいという思いでやっているものです。","voiceIndex":100,"id":"exchange-030"}]},{"id":"topic-03","title":"公有地・跡地活用に関すること","agenda":"公有地・跡地活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"やはりこの地域、この貴重な公有地で、区境ということもありますので、やはり認可保育園ですとか公園ですとか、そういったことを軸にして取得して整備すべきだと私は思っておりますが、こうした認可保育園の整備に関する考え方、それとあわせて今、区が「行政需要等を勘案し」と書いてありますけれども、どのような活用方法を案として考えているのか、お伺いします。","respondent":"柏原企画調整課長","answer":"こういったところに対して手を打っていかなくてはいけないというところはありますけれども、そのどれがというところではないんですけれども、そういった需要を見ながらこの土地の活用がどうできるのか、できないのか、これにかかる費用であるとか。","voiceIndex":107,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"ぜひそういった地域のニーズなどもしっかり踏まえた上で、取得を検討していただければと考えていますけれども、待機児童の問題ですとやはりどの地域でも深刻ではあるんですが、特に保育園ですからどこにでも行けるわけではないので、この上大崎地域というところでどれだけの保育需要があるかというような需要調査みたいなものもしっかり分析した上で、それに対応するような施設。","respondent":"柏原企画調整課長","answer":"今、仮に待機児童というお話がありましたので、その部分でお話しいたしますと、待機児童を担当している部門がありますので、その部門と情報連携をとりながら、どういったニーズがあるのか確認をとりながら進めていくという状況です。","voiceIndex":109,"id":"exchange-032"},{"speaker":"横山委員","kind":"質問","question":"先ほどの概要の説明のところに、３ヶ月の間に待機児童の解消プラン、対策で使うことみたいな形で国のほうから、何か活用方法の制限もしくは有利な条件みたいなものがあるのかどうかというところと、あとそこに、すみません、ちょっと前後してしまったんですけれども、万が一待機児童の解消というところに何か有利な条件みたいなものがある場合には、この上大崎寮のエリアの需要ですとか。","respondent":"柏原企画調整課長","answer":"ただ１点だけ、例えば国にここを取得します、借りますという要望を出すときには、きちんと何に使いますというのを明記して出さなくてはいけないというところがありますので、この辺は仮に取得といったとき、途中で何か転用ということがどこまでできるのかというのは。","voiceIndex":111,"id":"exchange-033"},{"speaker":"横山委員","kind":"意見","question":"転用というお話もちょっと今していただいたんですけれども、現在待機児童の課題ですけれども、品川区のほうでいろいろ調査もしていただいておりまして、万一用地を取得した場合、３年後ぐらいには完成する形になるかと想定できるかと思うんですけれども、その頃にはある程度待機児童の問題が少し収束に向かっているような、そういった想定が今出されているのではないかと思うんですけれども。","respondent":"柏原企画調整課長","answer":"そこを考えますと、３年後がどうなっているかというのはなかなかちょっと判断が難しいところです。正直申し上げて、今年は人口動態調査も行うことにはしていますが、これの回答までにはちょっと間に合わないというところがあります。","voiceIndex":113,"id":"exchange-034"},{"speaker":"横山委員","kind":"質問","question":"先ほどのお話にあったんですけれども、優先的に案内をするという条件の中に、待機児童の対策というところのみということになるんでしょうか。それとも行政需要等を勘案して、保育園以外の活用みたいなところで申請を出す場合には、優先的には案内をしていただけないということになるんでしょうか。その辺を教えていただけたらと思います。","respondent":"柏原企画調整課長","answer":"ちょっと説明が足りなくて申し訳ございませんでした。","voiceIndex":115,"id":"exchange-035"},{"speaker":"たけうち委員","kind":"確認","question":"今の転用に関連してなんですけれど、そうすると確認ですけれど、待機児童対策で購入しませんか、活用しませんかというふうに来ているわけではないと。福祉だとか防災も含めてということですね。ここに１．の(1)で、南品川四丁目の国家公務員宿舎の跡を、これは同じ保育ですけれども定期借地で３０年でやっているんですけれど、この判断というんですか。あわせて教えてください。","respondent":"柏原企画調整課長","answer":"ですので、仮の話ですが、半分だけ民間事業者にやってもらうとかというふうになりますと、賃料を区がいただくことにはなろうかと思いますけれども、購入した分の賃料が民間の事業者からいただけるかというと、多分そうはならないだろうと。","voiceIndex":117,"id":"exchange-036"},{"speaker":"たけうち委員","kind":"質問","question":"ちょっと南品川のほうで引いてしまったんですけれど、環境が違うという話ですけれど、３０年というのは何か長いかなという感じがするので、定期借地にするかどうかわかりませんけれど、もうちょっと短いのがあればそういうのも視野に入れながらだと思うんですけれど、ちなみに購入した場合、ざっくりですけれど、このm2数でどれぐらい区から持ち出しが出るのかということと、例えばその中で、今。","respondent":"柏原企画調整課長","answer":"それから半分購入とか、一部購入ですけれど、これはかなりきつい交渉になってくると思います。小山台住宅みたいな大きな土地であればわかりませんけれど、この１,１００m2程度ですと、かなり厳しいのではないかと考えています。","voiceIndex":119,"id":"exchange-037"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。それは要望でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-038"},{"speaker":"伊藤委員","kind":"意見","question":"なので、一つの方向性としてはやはり買っていくほうがいいのかなと、私たちは思っています。それでこれが、例えば５年後の保育ニーズを勘案して、さらに別のものを企画していくなり、１０億円のお金を投入する予定であるとするならば、それを最大限行政の効果として活かしていく仕組みをつくっていくべきと思うのですが、改めて品川区のお考えをお聞かせください。","respondent":"柏原企画調整課長","answer":"ですので、なかなか難しい判断に最後はなってこようかと思いますけれども、仮にそういった動きになるということであれば、先を見た形で動きがとれるような工夫をしていかなければいけないと考えています。","voiceIndex":122,"id":"exchange-039"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"伊藤委員","kind":"意見","question":"去年も中塚委員長のもとでやらせていただきましたので、去年の資料を持ってきたんですけれど、昨年の行財政改革特別委員会では、具体的には例えば６月１０日に１年間のスケジュールを出していただいて、７月２日には跡地の概要、公有地等の視察等々、具体的なスケジュールを出していただいて、調査事項に基づいて何を検討するかということを決めていただいて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと公有地・跡地活用と基金に関することですが、こうした貯め込まれた基金の活用と、公有地の活用というのは、切実な特別養護老人ホームですとか認可保育園、あるいは公営住宅とかも含まれると思いますけれども、こうした増設実現に向けて大事な要素だと思いますので、この３番と４番に関してはそうした区民要望をいかに実現させるかという観点で、ぜひ審議していく必要があると私は思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-041"},{"speaker":"藤原委員","kind":"質問・要望","question":"伊藤委員からも出ましたけれど、委員長、副委員長にお任せして予定を出していただきたいと思います。さっき日程のことも出ていましたけれども、最後の１回はまとめ等があると思うので、そうするとあと８回、９回ぐらいですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5986#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":47580,"voices":132}},{"id":"h27-20150610-18","meetingId":"h27-cm06","date":"2015年6月10日","dateIso":"2015-06-10","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時２５分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"今、委員長のご発言のとおり、今後の方向性という観点で、今、お答えづらいことも当然ながらあると思うので、方向性とか抱負という観点から伺おうと思います。そのためには労力もそうですし、予算措置も含めて、相当な努力は議会を初め区民の多くの理解を得られると思っていますので、この辺に対しての現時点での抱負的なものを伺えればと思います。それと、３点目がエンブレムの話。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"こちらのバッジのときのように、皆さんに東京都から大量に配布されるという予定がないので、配布については、今、大変頭を悩ませているところではありますが、エンブレムの決定と同時に東京都の考え方も示されるということですので、東京都がどのような考え方を持って。","voiceIndex":32,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問・要望","question":"この辺は現実問題難しいかもしれないのですが、やはり行政の力によって、行政と一体になって、何かエンブレムほかロゴだとかオリンピックを表現できる工夫というのは、これは早くから東京都なり招致委員会と折衝して、やはり営利ではない点と、そうはいっても高いハードルの中で、ぜひとも地域活動に表現をしたいというところは無数にあると思うので、この辺の働きかけを強くされたいという要望として。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"エンブレムにつきましては、特にバッジはやはりかなりの効果があるということで、委員のご指摘のとおり、例えば区が買い取るとか、そういったようなことも選択の視野に入れて、今、検討しています。は東京都の出方を待ちたいです。","voiceIndex":34,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"この２０２０年オリンピック・パラリンピック大会が東京に招致されたということですけれども、それで準備がずっと始まっているわけですが、この大会の開催に当たってやはりコンセプトというのがあったと思うのですけれども、改めてそこを確認しておきたいと思うんです。１つがそれです。とりあえず、その２つをお願いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"大井ふ頭中央海浜公園のどの部分をホッケー競技場にするかというレイアウトについては、今、一から検討をし直しているということで、東京都が現在検討中であるということを聞いてあります。","voiceIndex":36,"id":"exchange-003"},{"speaker":"南委員","kind":"確認","question":"ホッケー場のほうから言いますと、大体公園の真ん中のところにある野球場６面を使うという話だったのだけれども、そこの位置も含めて、最初からレイアウトそのものを見直すことから始まるということでいいのですか。そうですか。ちょっとそれを確認したいのと、それからあと、やはり大会が終わった後は、ぜひ野球場も全部ではなくてもいいのですけれども、でもできたら全部がいいのかな。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"大井ふ頭中央海浜公園につきましては、東京都のほうでも再検討の着眼点として、「現存する野球場利用者への影響を極力抑制しつつ、ホッケー等の拠点として整備する」ということで、そういった資料も出されており、現存する野球場利用者への影響に配慮するということですので。","voiceIndex":38,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"どんなスポーツに関するところでも、やはり一時的にでもなくなるところがあるし、やはり代替施設はしっかりそれは確保していけるよう要望していきたいというお話なのですけれども、そういうあたりのことをどんなスポーツ競技場にしても、関係者の方々の意見も十分踏まえた上で、やはり必要な意見は必要なところからどんどん言っていくという立場を区としてはとっていただきたいと考えていますので。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"このオリンピック・パラリンピック推進特別委員会でも東京都に要望を出させていただいたところです。区といたしましても、区長会等を通じてきちんと要望はしていますので、これからもそういったことは区として言うべきことは言っていきたいと考えています。","voiceIndex":40,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"それで、予算がどのぐらいかかるかちょっと数字は忘れたのですけれども、ものすごい膨大な金額がかかると。しかし、どんなふうに考えていったらいいのかというところは、一定程度伺っておきたいと。それはさっき言ったように財政の使い方、それから後々悔いを残さないような地方財政のあり方も含めて、どういうふうに考えたらいいのかというところをちょっと伺っておきたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"先ほど申し上げましたアドバイザリー会議、レガシー委員会等々で、後利用に関しても真剣に取り組んでいるところですので、そうした検討の経緯をしっかりと見守っていきたいと考えています。","voiceIndex":42,"id":"exchange-006"},{"speaker":"筒井委員","kind":"質問・要望","question":"平成２７年度の主な品川区オリンピック・パラリンピック関連事業についてなのですけれども、この３番で、青少年ボランティアガイドとありますけれども、私としては青少年だけではなくて、ぜひとも高齢者のボランティアガイドの育成もしっかりと行っていただきたいと考えています。その点についてどのようにお考えなのかをお聞きしたいと思います。よろしくお願いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"当然高齢者の方がいろいろさまざまご活躍される場面が必要だということは区も承知をしておりますが、そうした方をどのように活躍していただく場面があるかとかいうことにつきましては、また東京都の動きを見守りつつ。","voiceIndex":44,"id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"その点についてお伺いしたいと思います。よろしくお願いします。","respondent":"間部文化観光課長","answer":"ちょっとしたおもてなしボランティアのような活用もちょうど考えているところですので、そのような機会を捉えまして考えて、実施になるべく近づけていくように調整してまいりたいと思いますので、よろしくお願いします。","voiceIndex":46,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"私がこれを見て気になるのは、災害のときで、例えば先週の土曜日に地震があって、電車がとまりましたね。もちろん、これも東京都や国の対応が主だと思いますけれども、もっと細かいレベルの例えば商店街での少しだけできる英語というものの中にその視点が入るのかとか、それから国や都へそういう働きかけを行うことがあるのかとか、その辺のお考えを伺いたいのが１点です。以上です。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういった競技の周知とともにパラリンピック自体も盛り上げるため、まちづくりからもバリアフリーに配慮するですとか、そういった案内表示をやさしくするですとか、そういったことはおもてなしの観点も含めて当然重要だと考えておりますので、そういった視点を盛り込みつつ。","voiceIndex":48,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"意見","question":"五輪憲章の中にも、開催国においてはその期間中に文化・芸術についても発信をすべきである、しなければならないというような憲章があったと思うのですけれども、この点、国のほうでも、特に東京都のほうで舛添都知事がさまざまな発言をされていますが、都だけではなくて、品川区としてこの品川の文化もそうなのですが、例えば芸術とかそういったものをどのように発信をしていくのか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"例えば芸術祭ですとか、そういったことをもう先駆けてやっているので、そういった充実も含め、まずは文化プログラムの策定の動きを見守りたいと考えています。","voiceIndex":50,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"意見","question":"来年３月に文化プログラムが策定されるということで、それを待つ前に区としてもいろいろな動きをされて、今現状やっているものも含めて今からいろいろ考えていらっしゃるということですけれども、スポーツでももう準備を始めているということですが、文化についてももう始めないと、付け焼刃のものになってしまってもおもしろくないというところもありますので、今。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-011"},{"speaker":"渡部委員","kind":"質問","question":"説明を伺って、区内は２カ所の会場があって、昨年度のこのオリンピック・パラリンピック推進特別委員会でも、視察に行ったりお話を伺ったりしました。そもそも大井ふ頭中央海浜公園とこの潮風公園については、当初の計画の１万何千人のスタンドがというのはわかっています。その辺のスケジュール的なところ、どのようなご報告が入っているかだけ教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"大井ホッケー競技場につきましての工期ですが、もともと平成２９年度から３１年度ということで、２７年度中に基本設計をするということになってあります。ですので、本年度は基本設計の年でございまして、それについての変更はないということで伺っています。","voiceIndex":53,"id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"そうしましたら、大井ふ頭中央海浜公園は現状のまま、平成２８年度中までは区民の方でも都民の方でも利用は続けられるということでよろしいのですか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおりです。","voiceIndex":55,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"そこの暑さ対策というのはどのように考えられているのかということと、あと禁煙対策、オリンピックが開催される国では、公共施設は禁煙が当たり前ということで進められていると思うのですけれども、品川区においての禁煙対策というのはどんなふうに考えているのかというのをちょっと教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"禁煙対策ですが、現在区としましては分煙が基本でございまして、きちんとした分煙対策をしているところでございまして、公共施設についても基本的には禁煙ですが、分煙の場合には、煙が飛ばないようにきちんと整備するという考え方でやっているものです。","voiceIndex":57,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"暑さ対策のところは会場等が主になってくると思うので、７月、８月にかけて大会が行われるというところで、どうされるのかなというのが素朴な疑問だったので伺ったのですけれども、大会組織委員会のほうでということですけれども、そこに向かうまでの間なども、そこは区内なわけですので、競技場がある地域というところではそこら辺も考えていくのかなと思って伺ったのです。","respondent":"小川オリンピック・パラリンピック準備課長、柏原企画調整課長","answer":"競技場に向かうまでの道のりですが、基本的には選手等はきちんと警備がついて、選手村から競技場まで行けるように、今、輸送計画でも練っているところですので、その間は例えば良好な環境できちんと競技場に向かえるように。今回のオリンピックの施設等に関しては、基準は今後東京都が示してくると思いますけれども、受動喫煙だとか、それから世界のいろいろな動きを見ながら、そういったところはこれから基準、考え方を示してくるのだろうと思ってあります。","voiceIndex":59,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。ちょっと雑駁な質問で申し訳ないのですけれども、あれば伺いたいと思います。","respondent":"柏原企画調整課長","answer":"それからあと、会場の近くの大井ホッケー場のところから、競馬場のあたりまで、電線の地中化の東京都の動きがありますけれども、それと合わせて、区のほうも一緒に事業を動かしていこうといったようなことも合わせてやったりだとか、オリンピック・パラリンピックに向けて。","voiceIndex":62,"id":"exchange-016"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"まとめて調整していただきまして、ありがとうあります。確認なのですけれども、先ほど、できるだけ時宜を捉えたような形で審議をしていきたいというところなのですが、下の９月下旬のところで黒丸が４つ並んでおりますが、これはこの順番でやるということではないのですか。例えば芸術の秋だからこういうことだとか、そうことではないのですか。","respondent":"本多委員長","answer":"このとおりの順番というわけではありません。先ほど資料もいただいたように、いろいろと周知される事業があります。そういった時期を極力同じ時期に委員会で取り上げるような、そういう工夫を何かしていきたいと考えています。","voiceIndex":67,"id":"exchange-017"},{"speaker":"あくつ委員","kind":"提案","question":"わかりました。例えばこういうところ、こういう施設が非常にいいのではないかという提案とか意見を述べたい場合には、これは会派を通じてまたお願いするということも可能なのでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"それと、今、あくつ委員がおっしゃった９月以降のここは、そのとき、そのときの状況で繰り上がって取り上げるとか、そういうふうに自由に時々の委員会のテーマを決めていくということで受け止めていいということなのだろうと思って聞いていたのですけれども、そういうことなのか、ちょっと最後に確認して、２つお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"この枠の上に書いてありますけれども、区に及ぼす効果や影響と、それらへの区としての対応について、今回このオリンピック・パラリンピック推進特別委員会で調査・研究するということが当然一つ大きな目的なので、そういう観点から見て、こういう建設予定地、いわゆる品川区外にある予定地でありますとか施設を見ることの必要性について、ちょっとお考えだけ確認させていただきたいかなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-020"},{"speaker":"若林委員","kind":"質問・要望","question":"わかりました。ぜひ区に参考になるという観点・重要性から見て、しっかり視察については組んでいただきたいと思って、やはり移動の時間等で大変時間がかかる場所が何カ所かあると思います。大変にそういう意味では効率的な委員会運営も必要という観点とか、そのほかにも重要な調査事項がもしかしたらその時点、その時宜であるかもしれませんので、そういった観点でまたよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-021"},{"speaker":"渡辺委員","kind":"提案","question":"追加への提案ということで、先ほど２０２０年後の後利用の調査とまず仮称したとします。そうしたときにどういうことが言えるかというと、区内競技場をその後どう使うか。それは区民のメリットにもつながるのではないかということで、後利用への調査の情報があれば、対東京都等に要望もしやすいのではないかという観点から、項目としての提案になります。これはぜひ正副で検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6472#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":26652,"voices":81}},{"id":"h27-20150612-10","meetingId":"h27-cm06","date":"2015年6月12日","dateIso":"2015-06-12","committee":"議会運営委員会","time":"午後 １時００分～午後 １時５５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"費用弁償","agenda":"費用弁償","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"共産党としては、平成２５年第４回定例会のときから、費用弁償を廃止すべきだということで、同時に条例提案をさせていただいておりまして、また、今回の第２回定例会に向けても、費用弁償廃止の条例を出す方向で検討しまして、各会派に共同提案をということで呼びかけをさせていただいていたところなのです。","respondent":"大沢議長","answer":"そこのところは、私も説明すればよかったのですが、そういうことで、これは三つということです。ただ、ぐちゃぐちゃにしてしまうと、材料にする場合に明確ではないので、あえて1)、2)、3)ということでわかりやすいと思ったので、そのような形にさせていただきました。","voiceIndex":15,"id":"exchange-001"},{"speaker":"須貝委員","kind":"提案","question":"今回、議長から提案があったのですけれども、その前に、先ほど局長から説明があったとおり、言い間違えだったら訂正していただきたいのですが、まず定額支給で、今までどおりにするのか、それとも全く出さない、ゼロ円にするのか、今言った、あらかじめ登録された交通手段の実費のみを支給するのか。その後、今、議長が提案された方法でどうなのですかという形でいかなければだめなのではないですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-002"},{"speaker":"須貝委員","kind":"意見","question":"一応、我々とすれば、実費ということは、金額的には下がるのですが、やはり区民感情、区民から区議会を見たときに、区民が納得できる対応を考えるならば、委員が議会に出る、委員会に出るのはごく当たり前のことなので、常勤ではなくて非常勤なので、私は、費用弁償はゼロ円にするのが、区民の目から見て、妥当ではないかと思いますので、我が会派としては、ゼロ円ということを主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-003"},{"speaker":"沢田委員","kind":"提案","question":"前議会のときから、費用弁償に関しては、４,０００円から２,０００円に下げて、いずれはなくしていくという方向が出ていたという話も聞いていますし、今回、費用弁償について、実費相当ということで議長からもお話がありましたけれども、一般企業でも、費用弁償を交通費と考えるならば、交通費が出ない会社はないわけですから、やはり実費に関しては出していくべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-004"},{"speaker":"塚本委員","kind":"提案","question":"公明党としても、費用弁償、いわゆる出会手当ということですけれども、これについては実費相当が妥当ではないか、現実に電車、バス等で来られている方については、それに相当するものを支給するのはいいのではないか。今、議長が提案されていた３点について、その線に沿って進めていただければと思っているところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-005"},{"speaker":"あべ委員","kind":"提案","question":"前期で大分決着がつくくらいの流れになってきたけれども、最後に２,０００円ということで、ある種、積み残しになっていた部分があると思います。ただ、テクニカルな部分で、いろいろ細かいことが出てくると思いますが、それはどこかで線引きしなければいけない、そこに多少のでこぼこがあっても、線引きするという意味では、議長のご提案の方法で妥当なところ、理解が得られるところかなと思います。","respondent":"原区議会事務局長","answer":"自治法のほうでは、することができる、条例で定めるという構図になっているかと考えています。現行の条例の中でも、議員が公務のため出会したときは、費用弁償として２,０００円を支給するという形になってあります。","voiceIndex":26,"id":"exchange-006"},{"speaker":"あべ委員","kind":"確認","question":"すみません、局長に再度確認したいのですけれども、支給するという規定になっていても、いや、私は半々だから要らないという選択肢も出てくるのか。それは事務的に、規定にかかわらず、登録を先にしなければいいだけの話なのか、その辺はどう解釈すればいいのでしょうか。","respondent":"原区議会事務局長","answer":"自転車の場合は、届出をいただかなくて、多分電車とバスを使う方は、こういうことで、どこからどこまで電車を使うから幾らですということで届け出ていただきますので、そこで届け出ていただかなければ、自転車、あるいはオートバイ。","voiceIndex":28,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"今回は自転車で来ました、今回は自家用車で来ましたと、それに対して誰が判断されるのか、承認をするのでしょうかということ。交通手段としては、現在、政務活動費でガソリン代として請求された方には、一人５,０００円を支給しているということを考えると、何かそこがバランス的に違和感を覚えるのですが、その辺はどうなのでしょうか。そちらは、現にもう交通費ということで出しているということですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"実際に、区民から見たら、いや、これから本会議に行くのですよと、自分の自家用車で行って、帰ってくる、それだけのときもあるかもしれないですよね。それは政務活動としては見なされないわけではないですか。そうしたら、あらかじめ５,０００円出しているというのは違和感がある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-009"}]},{"id":"topic-02","title":"標準市議会会議規則の一部改正に伴う品川区議会会議規則の一部改正","agenda":"標準市議会会議規則の一部改正に伴う品川区議会会議規則の一部改正","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"第２項で出産について条文を追加することについては、異論はありません。せっかくこの改正をするわけですから、先ほど局長からもご説明がありましたように、従来の条文の中では、事故という言葉に、出席を妨げる不可抗力全てを含んでいる表現になっていると思うので、いわゆる一般としての事故のほかに疾病ですとか、出産とか、そういったもろもろ全てを入れていったというのがこれまでの条文だと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、当然入れるべきものだと思いますので、そうしていただきたいと思います。今、あべ委員のほうからもありましたように、疾病で休むということが、ほとんど多くがそうなので、やはり事故という表現に加えて、疾病というものをつけ加えたほうがよりわかりやすいので、ぜひ改正にあたってそうしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-011"}]},{"id":"topic-03","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そういうところでは、いろいろ全国的にも、またこの間も、この意見書は国に対して上げられているところがどんどん増えていると思うのですけれども、ここの中で、ヘイトスピーチの問題で、ぜひ検討して意見書を上げていくという方向でできないかと思って、提案させていただきたいのです。","respondent":"渡辺委員長","answer":"受理されたり、いろいろ方法論の中で、今日のところは、取り扱いについて、委員長として答えようがないかと思います。それぞれ手続にのっとって、おのずと出てくるものかと考えております。今の個別案件という点も含めて。","voiceIndex":60,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私たちも、きのうのお昼くらいに初めていただいたところだったので、きのうの今日なので、もう少しゆっくりと検討していけばいいのでないかと思うのですが、各会派にそういうことが来たら、これからぜひ検討をしていけたらという意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5144#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":16832,"voices":64}},{"id":"h27-20150624-10","meetingId":"h27-cm06","date":"2015年6月24日","dateIso":"2015-06-24","committee":"議会運営委員会","time":"午前１０時３０分～午後 ０時１０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区議会議員の議員報酬、費用弁償及び期末手当に関する条例の一部改正","agenda":"品川区議会議員の議員報酬、費用弁償及び期末手当に関する条例の一部改正","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前回のところでは、バスと電車の往復について登録をしたことに対して、ということだったと思うのですけれども、この文言でそういうふうに読めるのか。それとも、登録をした人だけではなくて、例えば、いつもは自転車できているけれども、そのときは電車で来たとかいう、そういう単発のものも認められるのか、そこら辺の規定がこの文言でどうなっているのか、ちょっとご説明いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"条例の書き方としては、これでいいと思いますが、局長が今ご説明された実際の運用に関するルールは、何か細則のような形で明文化するのか、そういうものは全くなしで運用の手続に入るのか。もしそれをつくるとなると、８月１日までにつくることになると思うのですが、どういったスケジュールを考えていらっしゃるのか、教えてください。","respondent":"原区議会事務局長","answer":"運用というご説明をさせていただきましたけれども、要領とか要綱とか、そういったところで、様式等についてもまとめをさせていただきながら、そこの中で根拠をどこまで細かく書けるかという問題は、今、事務局のほうでも協議をしておりますけれども。","voiceIndex":19,"id":"exchange-002"},{"speaker":"あべ委員","kind":"質問・要望","question":"皆さんが合意できるように、できるだけ早いタイミングでということで、このような内容で条例を固めるということになったと思います。それはとてもいいことだと思うのですが、逆に言えば、一番微妙な違いが出てきたのも、その運用の部分ですので、どういった運用になるかということもできるだけわかるような形で進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-003"}]},{"id":"topic-02","title":"品川区議会会議規則の一部改正","agenda":"品川区議会会議規則の一部改正","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"欠席届の第２項の、出産のために出席できないときですけれども、日数を定めてというところについては、母性保護規定でしたか、産前産後というところに基づいてという考え方でいいのか、日数を定めてというところをどう考えられるのか、ちょっと教えてください。","respondent":"原区議会事務局長","answer":"日数を定めてというのは、通常の場合は、労働基準法が根拠で産前産後というものは決められておりますけれども、議員の場合は、それが即適用という形ではないところに、今までのここの条文をどうするかというところで、国会を含めて。","voiceIndex":28,"id":"exchange-004"}]},{"id":"topic-03","title":"議会の課題検討に係る議長諮問機関の設置","agenda":"議会の課題検討に係る議長諮問機関の設置","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"内容はこれでいいと思います。ただ、名前ですけれども、仮称ということで、議会改革検討委員会ということで、委員会というと常任委員会や特別委員会、そちらの委員会と同じような形にとられてしまうので、前議会のときも、議会のあり方検討会という形でやられていたかと思うのですけれども、議会改革検討会という形の名前のほうがいいのではないかと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-005"},{"speaker":"塚本委員","kind":"意見","question":"うちの会派も、この内容で了解ですので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"議会改革検討委員会をつくるということに対しては賛成するものなのですけれども、一つは、この議会改革検討委員会をつくる目的、どういう目的でこれをつくっていくのかというところをきちんとしてほしい、明記をしてほしいということが１点です。ここで出されている４項目ということでコンクリートするのではなくて、検討委員会の中で、改めて議論するという確認をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-007"},{"speaker":"渡辺委員長","kind":"質問","question":"私のほうから、まず……、先に一通り伺いましょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"私どもも、もちろんといいますか、この方向性に対しては賛成です。そういったことも含めて、それをここである程度イメージを固めていくのか、それとも、議会改革検討委員会が発足した後で、何を分科会で、どういったことは全体で話すのかということまでは議会運営委員会の中で組み立てていかなければいけないかというふうに考えております。これは、皆さんのご意見も伺いたいところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"我々は話し合って、議会改革として全員に参加を呼びかけるのはいいのかなと思うのですが、前回もお話ししましたが、我々の会派としては、議員の身分等に関しての議論はしたいと思うのですが、それ以外に関して、どういう内容になるかわからないのですが、中身によっては、やはり参加したくないということをお話ししたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"だから、今、須貝委員からもありましたけれども、みんなで議会改革として検討していくことが必要なのではないかという議論をしっかりとやって、この４項目でいいのかどうかも含めて、４項目をやっていくのかどうかも含めて、全部はじめから何をやっていくかという議論を始めてほしいということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ではもう１回確認ですけれども、この４項目をもう検討課題として決めたということではなくて、例えばこんなことということであって、これも含めて何を検討していくかということは、検討会の中ではじめに議論するということで確認させていただいていいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"もちろん決めるのは新たな会議体ではあるけれども、その中で、当然、ここに例示されてきたものも、ただ思いついたわけではなくて、これまでの議論の中で積み残しにしていたものが乗っていると、私は理解しておりますが、そんな感じでよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今まで出されてきて、ここの中で積み残したものがこれだというのも、すんなり理解できない部分があるので、そういうところも、今度の委員会の一番はじめのところになるのかもしれないのですけれども、こういうことで出されてきて、これが積み残っているというようなものも、資料としても出していただきながら、それで今何を検討していくことが必要なのかという議論にぜひしていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の話を聞いていると、４年前の議会のあり方検討会を開いていた意味が何もないように聞こえるのです。そこでもんで、各会派の代表に出ていただいて、そこの中で検討したうえで、最後のまとめをつくって、そこまでやっているわけです。さっきの３合目まで登ったものが出ているのですから、その辺の理解は共通していると、私は判断するのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これも実現した、これも実現した、これも改善されたというのがいっぱいあるなと思ったのです。そういうところでは、この検討会をし、議会運営委員会でも議論する中で、改革が確実に進んでいるというところは、私も本当に評価をしているところです。その中で、改めて、では積み残しているものがこれだというところが、私はこの中からはなかなか読み取れなかったのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-016"},{"speaker":"たけうち副委員長","kind":"質問","question":"だから、これを全く議論しないということではなくて、まずはここから何ができるのか議論したうえで、またさらに新たな課題があるなら、それも議論して決めればいいのではないですかということ。だからそこは踏まえたうえで、尊重したうえで、新たな課題があるなら検討委員会で出して、皆さんで決めればいいのではないですかという、こういうことだと思いますが、どうですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"わかりました。これもコンクリートされてなくて、そこの議論の中で決めていくということで確認をします。そのときに、今までの、議会運営委員会のときにも、こういうところで、こういうふうに取り組んできたと整理したものを出していただいたではないですか、そこら辺の資料なども出していただけたら、よりわかりやすいかという思いがします。","respondent":"渡辺委員長","answer":"もう１点、言わせていただくと、冒頭に私も、話の進め方は説明したのですね。全て今日決めるものではないですよと、内容については整理して検討会でしていくと、冒頭に説明したので、しっかりそれを聞いていただけるとありがたいと思います。","voiceIndex":57,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"だから、今、鈴木ひろ子委員がおっしゃったとおり、それなら、こういう検討会をつくるということを明確にしないで、ただ、分けましたよと、そこでこれからこういう話をしますというのではなくて、あらかじめこういうことを検討していきたいということを明確にして、そこに集う人、そこに入りたい人を入れていくと、それで検討しているのが筋ではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-019"},{"speaker":"たけうち副委員長","kind":"意見","question":"今、須貝委員がおっしゃいましたけれども、なんで須貝委員の会派が情報発信をどうでもいいと思うのか、逆に我々も知りたいと思うのです。我々はそれを議会のお金をつけてやっていこうと取り組むわけだから、それが須貝委員からしたら無駄だと思うわけでしょう。みんながみんな賛成意見ではないのだから。そういうことを拒否するというのは、議員としての態度が少しおかしいと思いますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-020"},{"speaker":"須貝委員","kind":"提案","question":"これは意見だけなのですが、今、もともと区民が政治離れしているという状況を見たときに、根本的に、本来なら、何を我々は議会改革をするのかということを考えていって、提案していくというのが筋でしょう。そうではなくて、議員がこれとこれはやるべきだと、それは果たして区民要望なのですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-021"},{"speaker":"本多委員","kind":"意見","question":"たけうち副委員長と全く同趣旨のことを発言します。我々区議会議員というのは、区民の負託を受けて区議会議員をやっておりますので、全ての会議体に責任を持って、期待に応えていかなければいけないと思います。例えばカレーライスを食べるときに、カレーは好きだけどニンジンは嫌だとか、ピーマンは嫌だとか、全くそういうことだと思うので、真剣にやったほうがいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"意見","question":"私は、平成２３年１２月から議会のあり方検討会の途中から参加をさせていただいて、また、昨年度まで議会運営委員会で議論させていただいたので、やはり流れをしっかりと引き継いで、新しい方にもわかっていただいて議論を進めていくのが大事だと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-023"},{"speaker":"渡辺委員長","kind":"提案","question":"それはもう、皆さん聞いていますので、わかるかと思います。それから、名称にかかわる、改革というものが全てかというご提案も、私としても少し感じるところがあったので、そこは全体の、後ほど、名称を確認するときにもかかわってくるかと思います。以上、先ほど一通りご質疑等をいただいたものがあったかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"だから、今回の議会改革を何を目的にやっていくのかということなのですけれども、そこのところは、わかっているということだったら、そのわかっているものを明記してほしいということです。改革をすることが目的ではなくて、何のために議会改革が必要なのか、どういう議会にしていくために議会改革をしていくのかという、その目的をはっきりさせて、この改革の委員会をつくっていきたいということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-025"},{"speaker":"あべ委員","kind":"意見","question":"本来、委員長からお話があることだと思うのですけれども、前の議会のあり方検討会のときにも、やはり一つ大きなテーマというか、価値として見出していたのは、より開かれた議会、区民から議会が見えにくいというのは、さっき須貝委員もおっしゃっていたように、議員活動、議会活動が区民からなかなか見えにくいというところを、より改善していく。そういったようなことです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"その目的というのは、今、あべ委員からありましたように、議会が議会として役割を果たすことができるような、そういう議会の改革にしていくということで、その中身としては、一つは区民に開かれた議会、区民の意見が反映されるような議会、それから議会が行政をきちんとチェック、監視できる、そういう議会。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"本来の議会の役割というところがその二つだと思うのです。だから、そのためにも議会改革になるというところを、私は目的として確認したいということなのです。そこはちょっと議長にもお伺いしたいところです。","respondent":"大沢議長","answer":"だから、検討委員会をつくる目的は、各論で言えば、ここに挙げられた部分に関して、スピード感を持って解決をしていくのが、今回、諮問をする検討会の目的、役割だと考えています。","voiceIndex":74,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、その目的というところでは、２点言わせていただきましたけれども、多分、それは議員必携の中にも書かれているものではないかと、個人的な主観で言っているのではなくて、議会とはこうある目的だと書かれているものだと思うのです。そういうところで、何の目的でこれを設置するのかというあたりは、もう少し議論をしたいし、それから、その中ではっきりとさせていただきたいという思いです。","respondent":"渡辺委員長","answer":"今の今では難しいということであって、ただそこを明文化しなくても、設置を優先しましょうという皆さんの流れがあればいいのではないかというのが、今現在までの私の考えでした。そういう意味で、答えに歯切れが悪いと思っていただければと思います。","voiceIndex":76,"id":"exchange-029"},{"speaker":"たけうち副委員長","kind":"質問","question":"今、鈴木ひろ子委員がおっしゃった目的、私も当然そうだと思っていますし、多分、ここにいらっしゃる皆さん、そうだと思っているのですよ。それをどこにどう明記するかというのは、それを検討しなければいけないという話で、そのために改革をしようというのは共通認識だと思っていただいていいと思いますので、どこに明記するかというのは、また検討していけばいいのではないですか、今ここではなくて。","respondent":"渡辺委員長","answer":"そのうえで、会議体の設置というのが、前回からの流れでしたので、優先事項で、それもスピード感というものをさんざん皆さんで言っていただいたので。では、先ほどの目的のところは、１回、委員長預かりにさせていただいて、正副委員長で検討させてください。","voiceIndex":78,"id":"exchange-030"},{"speaker":"あべ委員","kind":"意見","question":"今の件で。目的や、大体、皆さんの共通理解が必要だろうと、その気持ちは非常にわかります。ただ、議会基本条例も、すぐに、では条例だとつくり始めるわけではないので、多分、その周辺の状況や、そもそもこういったものの歴史みたいなところから入っていくのでしょうけれども、それはまた新たな検討会や分科会に任せることとして、今は、大まかな合意でスタートできるかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-031"},{"speaker":"あべ委員","kind":"意見","question":"そうですね、改革という言葉とこの内容と、どうなのでしょう、それは皆さんの感覚や、端から見て、改革と言っていて、ＩＣＴ化って改革なのかと思われると、少し気恥ずかしさみたいなものがあるのですけれども。でも、それで皆さんがゴーということであれば、名称にはこだわりは別にないです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":82,"id":"exchange-032"}]},{"id":"topic-04","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"一つ目が、オリンピック・パラリンピックへ向けた事前キャンプの誘致に関する要望ということで、要望内容は書いてあるとおりなのですけれども、競技開催地として、しっかりとオリンピック・パラリンピックの事前キャンプを東京都で誘致していただきたいということです。国土交通省は東京都とも、２３区近隣ともしっかりと連携をしていっていただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-033"},{"speaker":"塚本委員","kind":"提案","question":"一つ目が、資料１８で、高齢者施設に関する要望ということで、いわゆる団塊世代が７５歳以上になる２０２５年問題、これに向けて、今、都市部における施設の逼迫ということが話題になっている中で、計画的に整備を進めていただきたいということで３点、特別養護老人ホーム開設のための用地確保、また、高齢者施設で働く介護従事者の処遇改善、そして、高齢者の住まいの確保のための空き家の利用ということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１点目は、国民健康保険、介護保険の国庫負担引き上げの要望ということで、国民健康保険が毎年値上げされて、本当に高い国民健康保険料が大きな問題になっているわけです。それから、５点目は、少人数学級の実現を求める要望ということで、教員の多忙化も大変な状況がありますけれども、全学年で３５人学級の実施に取り組めるように要望書を出していただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-035"},{"speaker":"あべ委員","kind":"質問・要望","question":"私どものほうでは、一つは児童相談所。これは東京都に言っていくしかないものですから、ぜひと考えています。それから、三つ目が教員人事権。これも、品川区くらいの規模であれば、中核都市にも教員人事権が下りているところもありますので、ぜひこういったことも、東京都のほうでしっかりと取り組んでいただきたいということで要望に挙げさせていただいています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"次の次の羽田空港の機能強化による地域活性化についての要望ということですけれども、この件名だと、地域活性化ということで書かれているのですけれども、下を見ると、不安の払拭と周辺整備ということで、地域活性化の意味がどういうことなのかお聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-037"},{"speaker":"本多委員","kind":"意見","question":"最初のところだけ、私からお話しします。５年間も清掃に関することでしか使えない、本当に縛られてしまっているので、その縛りを解除してほしいということ。そんなことを言うのだったら、無償で譲渡しないとか、東京都からそういう発言がないように、あえて無償で品川区が新しい企画で使えるようなことにしてほしいと、そういうことです。次のことはほかの委員からお答えします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-038"},{"speaker":"渡部委員","kind":"質問・要望","question":"ここで、地域活性化についても要望していますが、やはりその地域ごとに必要になってくるであろう措置もあるのかと考えていますし、地域の中でさまざまかかわりを持っていただいて、大田区等もそうなのですけれども、羽田空港はさまざまな地域とのかかわりが生まれておりますので、しっかりとそのような形の中で、品川区にもかかわりを持っていただきたいというような思いで要望させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今の段階では検討もできない。もう１カ所で言うと海浜公園があるのですけれども、あそこの脇も中継の施設で、あの土地も、公園の中の一角にあれがあっても使えない状況で、それこそもう２０年間無駄になっているので、無駄と言っては失礼ですが、今も一部やっているのですけれども、それの活用も十分に可能なはずなのに、それができないということも含めて、検討材料にはなると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"羽田の問題は、私たちとしては、上空を飛ぶことによって危険性がある、そういうものはやめるべきだという立場なので、少し違うかというところですけれども、では何を統一で出していくのかというところでは、私は、高齢者施設に関する要望で公明党と共産党の要望は一致できると思っていますので、ぜひ、待機児童と高齢者のところを入れていただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-041"},{"speaker":"塚本委員","kind":"意見","question":"基本的には、今、委員長がおっしゃられた議長判断というところに委ねるものではありますけれども、多くの会派の方々から出ているところを優先していくということが、一つの考え方として、我々としては納得できると、考え方としては持っております。去年１２月に出した意見書に沿って、趣旨に沿うようなものであれば、ありかなとは思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-042"},{"speaker":"あべ委員","kind":"提案","question":"資料３０の上からいきます。オリンピック・パラリンピック、これは多分出していただくことになるのではないかと思うのですけれども、それぞれ提案している内容、いろいろある中で、これは国に対する要望ですので、できるだけ国のレベルに合ったスケール感といいますか、内容で、あまり細かい話は出さないほうがいいかと思っていますので、そういったものを提案していけたらいいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-043"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"その他ではないのですけれども、先ほどの議長会の要望事項について、１点だけ確認させていただきたいのです。４会派からの要望が挙がってきていますけれども、ほかの会派はなかったということで、よろしいのですか。それから、議会運営委員会に出ていない会派については、聴取はされているのでしょうか。そこだけ確認したいと思います。","respondent":"原区議会事務局長","answer":"期日までに出された分だけ、今日はご案内をさせていただいた。それから、無所属議員にも、こういったことでという説明は、いつも議会運営委員会の報告をしますので、そのときにもご案内をしているです。","voiceIndex":113,"id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5146#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":32504,"voices":117}},{"id":"h27-20150629-6","meetingId":"h27-cm06","date":"2015年6月29日","dateIso":"2015-06-29","committee":"区民委員会","time":"午前１０時００分～午後 ０時２３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５７号議案、品川区手数料条例の一部を改正する条例","agenda":"第５７号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"幾つかあるのですけれども。一つはこの弁当等というところですけれども。人力販売業者というのは、例えばどのような形態の、あるいはどのくらいの実態があるのか、ちょっとそのあたりを教えていただきたいと思います。それからあと。ちょっととりあえず、それだけ別々に。","respondent":"高山生活衛生課長","answer":"弁当等人力販売業、行商の実態ですが、例えば現行ですと、現実に行商の定義というのは、人力で移行しながら、１人で持てる分の荷物を持って移行販売するということが定義なのですが、実態をごらんいただきますと、例えば昼時に、プラスチックケースにお弁当などを詰めて。","voiceIndex":7,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"新しくなる改正では５年に１回ということなのですけれども。５０人の方がいらっしゃると、こういう数字をどういうふうに見たらいいのかと。それがちょっと一つ伺いたいのと。人力で可能、人力というところなので、何というのでしょうか。事業所規模としては、どのような方、どのような状況をちょっと想定したらいいのかを、ちょっと教えていただきたいと思います。","respondent":"高山生活衛生課長","answer":"それを売るに当たっての届け出ということでございましたので、何と申しますか。１施設でつくって、複数人で売り歩くというようなものですので。規模そのものは、それほど大きなものではないというふうにお考えいただければと思います。","voiceIndex":9,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"わかりました。まだね。そういう状況があるので。その辺のところが、もう１回ちょっと、どういうことでこの時期かということは、ちょっと伺いたいと思います。これから。そういう中で、区民にどのような影響が考えられるのかというところを一つ伺いたいのと。そのあたりのことを、どういうふうに区が捉えていらっしゃるのかを、まず伺いたいと思います。そこも合わせて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"もちろん、委員長のそういうサジェスションは受け止めておきたいというふうに思うし、もちろんそういうことで認識しているつもりなのですけれども。でも基本的なところが、きちんとされていかないと、この条例に対して、本当に賛成の立場で捉えていいのかどうか、そこが不明確になりますので、ちょっと聞かせていただいているということを、ちょっと了解していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"南委員","kind":"提案","question":"もう一つ伺いたかったことは、こういう個人情報、現実的に、年金の情報が流出した、そういう事実はあるわけで、しかもその数というのが１２５万件ということで、６月１５日の年金支給日に、今のところ、年金が入っていないよみたいな情報というのは、ちょっとなかなか接していないので、どれだけのものかというのはちょっとわからないですけれども。その点についてのことを、ちょっと見解を伺いたいのと。","respondent":"井浦戸籍住民課長","answer":"１点目の、年金機構の事件に関連してのことですけれども、品川区としましては、まず、国のシステムとして、きっちりとセキュリティーが強化された形のものをしっかりと行っていく。","voiceIndex":16,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"今、お話伺ったわけですけれども。しかし、縦のところというところは、それぞれの関係機関のところで情報をきちんとつくると、そういうシステムだというところは、それはそれでわかりますけれども。しかし１２桁の、一人ひとりにつけられたその番号で、例えばこの人の税情報はどうなのかというふうに使っていけばわかるわけですよね。こういうふうに思います。私は、こういう、何ていうのですかね。これは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-006"},{"speaker":"藤原委員","kind":"提案","question":"３つの課からこういう形で提案されているのですけれども。改めて、手数料の金額が決まってくるわけではないですか。その金額の、手数料の金額の算出の仕方、どういう計算式に入れてこの金額が出ているのか、それぞれ３つの課の課長のお話をいただきたいのと。歩道で、いわゆる、こういう申請といいますか、すれば、そもそも誰でもできるのですかと。５年ですよね。５年というのはなぜですかということと。","respondent":"井浦戸籍住民課長、高山生活衛生課長、鈴木建築課長","answer":"ちなみに、マイナンバー、番号カードの８００円のほうにつきましては、原価が７００円ということで、国から８００円という形での基準が示されているです。台帳類の整備でありますとか、書類の整理、許可証の交付などの事務上の手続きに、おおむね１５０分程度の時間を見込んでおりまして、そうした人件費と。ご質問の、認定手数料の算定根拠ですが、基本的には、認定に当たりましては、申請の書類に基づいて、先ほどご説明しました防火上。","voiceIndex":20,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"個人番号カードと弁当のことについて聞きたいのですけれども。近隣区との手数料の差は、大体どのくらいか。財政規模が同じぐらいのところとの違いを教えていただきたいというのと。そうですね。その比較を教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-008"},{"speaker":"たけうち委員","kind":"質問・要望","question":"１０月５日に発行される、紙ベースだと思うのですけれども。あれは何ですかね。麺類等と。それを教えていただきたいのと。交通上、安全上、防災上、避難上問題ないよと認めたときに、その曳家工法をやる方が、公道を使う場合に、例えば警察への届けだとか、そういうのはまた別にかかってくるのか、それとももう区が認めれば、そこは何か一括で区のほうでやってくれるのか、その辺もちょっと教えてください。","respondent":"井浦戸籍住民課長、高山生活衛生課長、鈴木建築課長","answer":"２点目の、希望しない選択です。１０月の通知カードにつきましては、皆様にもれなく簡易書留で送られてまいります。ちょっとその辺のところは、監視などの過程で、違反があれば、摘発といいますか、指導などをできる限り考えていきたいと思います。実際、認定がおりた後の使用、道路使用、あるいは道路占用等の許可等については、それぞれ個別で、道路管理者、警察のほうで行っていただくですが。","voiceIndex":33,"id":"exchange-009"},{"speaker":"たけうち委員","kind":"意見","question":"ここで、人力で移行しながら食品ということで、この括弧の中に、弁当類、そう菜類、豆腐類と書いてあるので。豆腐、よく今、名前はあれだけれども、よく、時々、豆腐の方も人力で歩いてくる人いますけれども。それは、ここでやらなければいけないということでいいのですね。","respondent":"高山生活衛生課長","answer":"これが許可制へ移行するということでございまして。ここに挙げさせていただいた、例えば豆腐類とかゆで麺類等を売る場合については、従前の行商ということで、届け出のまま存続するです。ちょっと説明が足りなくて申し訳ございませんでした。","voiceIndex":39,"id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問","question":"個人番号のほうのことで１点伺います。住民基本台帳カードのほう、これまでの交付が終了するという中で、これまでの総数、実績ですかね。もう１点は、今回、通知カードにしろ、個人番号カードにしろ、先ほど来の質疑の中で、希望しないケースも、カードのほうは、個人番号カードのほうはあるとなっていますが、対象がすごく広いではないですか。全区民という中でね。その２点をお願いします。","respondent":"井浦戸籍住民課長","answer":"なかなか、再交付の想定の数字は難しいところですが、現在の住基カードの再交付につきましては０.５％前後という形で、年間１５０件前後ですので、個人番号カードを１月以降取得された方が、さまざまな形での紛失というものも、ほぼこの数値が参考になるのかと考えています。","voiceIndex":42,"id":"exchange-011"},{"speaker":"渡辺委員","kind":"確認","question":"住基カードにしろ、今、再交付の需要といいますか、そうやって、僕の感触だと、結構な数あるのだなと。その点は、どのような受付対応を、これまでの範囲内なのか、何か特殊に考えられているのかを確認で一点と。大体こういうことが再交付理由でとどまるのか、あと、再交付理由の中で、項目といいますか、こんなこともあるのだというのがあれば教えてください。それで終わります。","respondent":"井浦戸籍住民課長","answer":"受付ですね。再交付の受付の体制ですけれども。これまでの住基の体制では、やはり到底、対応できないかというふうに考えてございまして。","voiceIndex":44,"id":"exchange-012"},{"speaker":"松永委員","kind":"質問・要望","question":"私もちょっとこの手数料の、通知カードと個人番号カードの再発行についてなのですが。すぐ、なくしてしまってすぐ必要だという人に対して、事務的な時間なのですが、どのぐらい期間がかかるのか教えていただきたいと思います。番号が、何か、新たな番号が変わるということだったので、結構時間がかかるのではないかと思いまして、質問させていただきました。","respondent":"井浦戸籍住民課長","answer":"１週間、２週間、そのあたりのところについては、まだ国のほうから詳しいことは、情報は入っていないです。","voiceIndex":47,"id":"exchange-013"},{"speaker":"南委員","kind":"意見","question":"うちは、建築基準法の一部改正に伴う事務手数料、これについては賛成です。食品製造業等の、弁当等の、これについては、８,８００円というのが、事業所規模にしてみて、５年間の金額なのですけれども、やはりもしかしたら、５年間続かなくて途中で廃業になってしまうかもしれないと、そういうことも考えたときに、やはりちょっと負担は重いという気はするのです。今のまだ技術的には。反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"弁当のことなのですけれども、都内で統一している額ということなのですけれども。なるべく、やりたいなと思っても、弁当のことをやりたいなと思っても、少し高いなと思う方もいらっしゃると思うので。なるべく安くなったらいいなと思いつつ、賛成です。そういう意見があったということは、はい。聞いていただきたいなと。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-015"}]},{"id":"topic-02","title":"第５５号議案、平成２７年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第５５号議案、平成２７年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そういう、脅迫的なメールが届いたりする、私もこの間、３件くらいあって。全然身に覚えのないものですから、放ってあるのですけれども。そういうことに対する消費者への啓発というのですかね。ここについては、ちょっと、だから、質問ですから。そういう対応について、どういうふうに見解を持っておられて、どういうふうにやろうとしていらっしゃるのか、実態も含めて、ちょっとあったら教えてください。","respondent":"山崎商業・ものづくり課長","answer":"これは警察の部分とも連携しながら、そういったネット被害に対して、集中的に防止するような方策も考えて、近年では相談業務に取り組んでいるというような状況です。","voiceIndex":62,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"国から全てお金が来るとはいっても、さっきも言ったように、システム上、まだまだ技術的には、何と言うのでしょうかね。大量の情報が流出したという具体的な事実もある中で、やはり急ぐべきではないし、やはり、国からおりてくるからやるのだとか、受託事務だからやむを得ないというところもあるとは思うのだけれども、それにしてもやはりやめるべきだということを、勇気を持って言っていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-017"},{"speaker":"たけうち委員","kind":"質問・要望","question":"質問でいいのですよね。それからこの地方公共団体情報システム機構というのが、これ勉強不足で、教えていただきたいのですけれども。全国レベルの組織だということなのですが。もしわかればで結構ですので、教えていただきたいと思います。そうすると、これを見ますと、月２日、勤務量を増やして年２４日ということで、この５３万３,０００円というふうになっていますので。その辺のところを教えてください。","respondent":"井浦戸籍住民課長、山崎商業・ものづくり課長","answer":"それから２点目のシステム機構ですが、こちらは昭和４５年に財団法人地方自治情報センターという形で、財団法人という形でできておりまして、いわゆる地方行政の電算化、コンピューター化を推進するための研修ですとか。専門相談員のほうですけれども。時給に直しますと２,６００円です。","voiceIndex":66,"id":"exchange-018"},{"speaker":"藤原委員","kind":"質問・要望","question":"戸籍住民課のほうに関しては、まず、法定受託事務という関係ですから、間違いが起きないように、行政としてやっていただきたいという思いがあります。相談が。行政がやっているのですから。それともう一つは、民民ですから、最後は弁護士等に相談をしなくてはいけない等々も出てくると思うのですけれども、その辺については、それは山崎課長に答弁していただきたいのですけれども。","respondent":"井浦戸籍住民課長、山崎商業・ものづくり課長、濱田生活安全担当課長","answer":"頑張ります。しっかりとやっていきます。そうしたモデルで実施したエリアについては、高齢者の消費者被害が、そのエリアは大分減ったりとかということがあって、最近は、区内全域に。ですので、そういったものが、区民から上がれば、それは随時管轄する警察署に情報提供して対応します。","voiceIndex":70,"id":"exchange-019"},{"speaker":"松永委員","kind":"質問・要望","question":"私からちょっと、平成２７年度一般会計補正予算のところで、事業内容の(2)の1)に。消費者育成および支援の。この消費者センターの案内が掲載された回覧板を全町会・自治会分を作成して配付とあります。その下の、事業予算の(2)の2)ですか。これは消費者センター周知用回覧板購入費と書いてあるのですが、これ、私的にはちょっとわからないのですが。ちょっとそこは教えていただきたい。","respondent":"山崎商業・ものづくり課長","answer":"街頭などで設置するふれあい掲示板とかというものではなくて、よくお知らせなどを挟み込む板のような、バインダーといいますか。","voiceIndex":75,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"今、緑の看板、ありますよね。回覧板。あれが新しくなるということは、プラスアルファでまた来るということですか。","respondent":"山崎商業・ものづくり課長","answer":"一定、その消費者センターのＰＲが掲げられているバインダーのほうと、併用して使っていただくようなことで、町会ごとに要望、ご希望をとりまして、私どもは、広くそういうふうな、日常に目に触れていただく機会をつくりたいなというようなことで、今回、補正で。","voiceIndex":77,"id":"exchange-021"}]},{"id":"topic-03","title":"平成２７年度品川区民まつりの予定","agenda":"平成２７年度品川区民まつりの予定","exchanges":[{"speaker":"南委員","kind":"質問","question":"ホッケー体験ということが、今あったのですけれども。設営、どういう内容なのですかね。設営とか、そのようなことって、出てくるのかなとちょっと思って。それは、どのような、誰がどういうふうにするのかなと、ちょっとそこだけ伺いたいのですが。","respondent":"久保田地域活動課長","answer":"基本的には、それぞれの設営については、各地区が、行われている場所をお借りしてやるものですので、私ども地域活動課の職員もお手伝いをしますが、ホッケー協会、そしてそれぞれの地区の方々と、実行委員の方々と協力しながら、設営・運営をしていくという予定です。","voiceIndex":92,"id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"私は、八潮でもホッケー体験というふうに書いてあるので、どんなものが具体的に見られ、楽しみにしているところですけれども、例えば、さっきおっしゃった、会場を設営してドリブル、シュート。そういう体験もできるとなると、それは区民の方がやるわけですよね。ちょっとその辺がわからなくて、そこも伺いたいのですけれども。","respondent":"久保田地域活動課長","answer":"実際の運営につきましては、ホッケー協会が、基本的には行っていただきます。それで、それの手伝いとして、私どもの地域活動課、また地域センターの職員等も、一緒に協力をしながら、ホッケーの啓発に努めていくといった予定です。","voiceIndex":94,"id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"毎回、こういうふうに報告していただくのですが。一番今回変わったの、このホッケーという形だと思うのですけれども。まさに２０２０年、オリンピック・パラリンピックという形で、せっかくこのホッケーという形になっているので、啓発も含めて、準備課長は、どういう形で携わって、どういうお考えがあるのか、教えていただけますか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"昨年から、区民まつりについては、ホッケーのみならず、スポーツ協会と協働をしまして、ホッケーだけでなくブラインドサッカー、あるいはビーチバレーのボールを展示したりということで、３競技の普及には努めてきたところです。","voiceIndex":97,"id":"exchange-024"}]},{"id":"topic-04","title":"平成２７年国勢調査","agenda":"平成２７年国勢調査","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"結構、国勢調査って、細かいことまで質問しているではないですか。１点。それともう１点は、個人の権利という意味でお伺いしたいのですけれども、私の記憶違いかもしれないのですけれども、この国勢調査の最後のところに、この国勢調査に答えなければ、記憶違いかもしれないけれども、何か、ちょっと、罰則までは書いていなかったけれども、それに似たような文章があったと思うのですね。","respondent":"久保田地域活動課長","answer":"ちょっと詳細が今、手元にないのですけれども。こういったものに協力をしないと、何とかの、あります、というような、そういった規定は確かにありますから、あくまでも個人の方に強制をするものではなくて、調査にご協力いただくという形で、今は進めているところです。","voiceIndex":103,"id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"ほかにもあるのですよというお話ですけれども。その文章の書き方等もあると思うのですよね。ちょっとその辺も、どうしても質問したかったので、させていただいたのですけれども。そのバランス等も考えて、担当の課長は、いろいろな思いがあると思うのですけれども、やっていっていただきたいなと、今日は思いまして、質問させていただいたので。何か、ありますか。","respondent":"久保田地域活動課長","answer":"ですから、例えば何度も足を運んで、制度の趣旨を理解していただいて、相手が納得をした上でご提出をしていただくようにお願いをしますということで、指導していますので。そういった心を常に忘れずに、今後も国勢調査の実施に当たっていきたいというふうに考えてあります。","voiceIndex":105,"id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"今回、毎回、５年に１回行われる国勢調査って、やはり調査員の方々の負担がすごく重くて。今回初めてですよね。そういう、ちょっとそれ、いつから始まったか、では教えてください。どのくらい、こういうインターネットによる回答が来るというふうに予想しているのか、ちょっとそこも２点目として伺いたいと思います。そのあたり、どのように見ていらっしゃるのかを、ちょっと伺いたいと思います。","respondent":"久保田地域活動課長","answer":"インターネット回答ですけれども、前回の平成２２年から、東京都で先行実施したです。今回は全国で行うということになってあります。","voiceIndex":107,"id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"インターネットで回答する方。例えば、私がインターネットで回答しましたということは、調査員には、どういう形でわかるのですか。その、わかる時期と、わかる方法と。結局、わからなければ、全戸訪問せざるを得ないではないですかね。調査票届けに。そういう、そのあたりの判別というのは、調査の方々にとってみれば、いつごろ、どういうふうな形でわかるのかなというのが、ちょっとわからなかったので。","respondent":"久保田地域活動課長","answer":"資料の裏面をごらんいただけますでしょうか。その、主な日程の流れが書いてありますが。インターネット回答が、期限が９月２０日までになりますので、その後、９月２０日までにインターネット回答のなかった方の、名簿というのでしょうか。","voiceIndex":109,"id":"exchange-028"},{"speaker":"たけうち委員","kind":"質問","question":"ちょっと直接関係ないのですけれども。２番の(2)の調査区数のところに、一般調査区というのと、特別と、水面とあるのですけれども。これはどういうことですか。","respondent":"久保田地域活動課長","answer":"水面というのは、外国籍の船が港に着いたときに、日本の国内におりないで、船の中で生活をするという方がいらっしゃいますので、そういった方については、水面調査区という形で分けているというものなので、そういう方々にも調査は行うという予定です。","voiceIndex":113,"id":"exchange-029"},{"speaker":"たけうち委員","kind":"質問","question":"ああ、そうではない。ちょっと待ってください。これ見ると、今、何かさっき、特別調査区は品川区にはないとかっておっしゃっていたので。これ、８９って書いてあるので。品川区の中で、３,５８１の調査区がある中で、特別が８９と水面が１あると、こういう理解なのでしょうか。","respondent":"久保田地域活動課長","answer":"説明が足りませんでした。申し訳ございません。先ほど、品川区にはないと言ったのが、その山岳地帯とか森林地帯のことを言ったものでございまして。","voiceIndex":117,"id":"exchange-030"},{"speaker":"渡部副委員長","kind":"質問","question":"すみません。何点かお伺いしたいと思うのですけれども。そして、日程のところなのですけれども。世代的に。これ、どういうふうにするのかというのを、ちょっと教えてください。これ、郵送か何かですか。それともこれ、調査員がポスティングをかけるのでしょうか。全然そういうのも、別にインターネットですから、どこから送られたって構わないと思うのですけれども。ちょっと合わせて、その辺教えてください。","respondent":"久保田地域活動課長","answer":"多大なる、本当にご協力をいただいているということで、感謝しています。次に説明会ですが、全部で７９回予定してございまして、それぞれの地域センターのほうに、区の職員が出向いて説明会を行います。","voiceIndex":121,"id":"exchange-031"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"必ず出ていただけるように、これは指導をしっかりしていただきたいのと。もう１件。配布期間、１０日から１２日のインターネット関係書類は、これは、訪問というのは、会わなければいけないのですか。ポスティングでいいのですか。３日間で。それもまた、ちょっと見解があれば教えていただきたいのと。１０日から１２日の、３日間での訪問なのか、ポスティングでいいのかというのは、教えてください。","respondent":"久保田地域活動課長","answer":"ただ、会えなかった場合には、やはり最後はポスティングもやむを得ないというふうに思ってございまして。それにつきましても、この説明会の中できちんとご説明をしていきたいと思ってあります。","voiceIndex":123,"id":"exchange-032"}]},{"id":"topic-05","title":"に、所管事務調査","agenda":"に、所管事務調査","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"ちょっと、うちの会派から出したものについては、あまり触れられていなかったので、残念かなと思いますが。それはそれで、委員長、副委員長に、お任せしたいと思います。その上で、この町会なのですが。町会、区との協働ということで、いいと思うのですけれども。その部分での、総務委員会との仕切りみたいなのは、大丈夫なのでしょうか。","respondent":"石田（し）委員長","answer":"仕切りは、その点に関して、そこの部分に関しては、総務委員会でと。それ以外について、支援策をここで議論ができればと考えていますので、よろしくお願いいたします。","voiceIndex":132,"id":"exchange-033"},{"speaker":"たけうち委員","kind":"提案","question":"あり方、その研究委員会の、いわゆる、細かい内容ですとか、そういうのはもう、総務委員会でやっていただくと。ただ、あくまで町会支援について、今まで出てきたあり方研究委員会の中で行われた議論なんかを読み込んだ中での、それについての答弁はこちらではないのかもしれないけれども、その中でこういう提案が出ていて、それについては、例えば、個人的に非常にいいと思うと。興味があると。","respondent":"石田（し）委員長","answer":"大きな枠での、あり方研究委員会の検討事項等は、総務委員会での仕切りになっていますので、そこについては、こちらで議論をすることはできませんけれども、それ以外のことについては、たくさん、支援策というのもありますし。","voiceIndex":134,"id":"exchange-034"},{"speaker":"南委員","kind":"確認","question":"さっき委員長が発言されたことを、ちょっと私、聞き漏らしてしまったので、確認したいと思ったのですけれども。その他のテーマについては、この数年、検討してきているというところ。ああ、中小企業。ごめんなさい。ちょっと、そこを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-035"},{"speaker":"石田（し）委員長","kind":"質問・要望","question":"私から、では、お答えをしますが。中小企業の支援について、何会派からか、ご要望をいただいだのですが、この間、５年間のうち４年間で、中小企業の支援について等は、調査を行ってきたので、今年は、その辺については、今までの経緯を見守る期間というか、どのように進んでいくかというのを見ていきたいということで、所管事務調査からは外させていただいて、この２項目で進めていきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"そういう判断であれば、それはそれとして伺っておきたいと思います。その後に、これからの議題として行政視察についてがあるので、やはりこの区民委員会で、中小企業というのは、大きな比重を占める項目だというふうに思いますので、ぜひ、所管事務調査にはないけれども、私たち、意識的に、積極的に取り上げて、いろいろと調査研究をするべきかなというふうに、ちょっと思っていますので。","respondent":"石田（し）委員長","answer":"次の議題、出たので。視察の件でありますので。そのときにまたお話ししますけれども。そういったものも含めて、検討させていただければというふうに思います。ほかに。","voiceIndex":139,"id":"exchange-037"}]},{"id":"topic-06","title":"の４、行政視察","agenda":"の４、行政視察","exchanges":[{"speaker":"渡部副委員長","kind":"提案","question":"今回、この所管事務調査、上がった中で、実は、その町会・自治会の支援等についてですと、なかなかその行政視察の範囲も狭まってくるのかなというところもありまして。先ほど南委員からも、おっしゃったように、やはり例えば商店街の活性化ですとか、ものづくり。ああ、どういうふうにやったら、というところで。すみません。そのようなイメージの場所をもっともっと探して、提案させていただければと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":143,"id":"exchange-038"},{"speaker":"たけうち委員","kind":"質問","question":"私のほうは、ちょっと所管事務のほうで、協働というのを出していたものですから、そこを、所管事務と直接、視察はかぶらなくていいと思うのですが。それから、この間の、初日の本会議の質問で、自・未さんの横山議員が、金沢市の協働の中から、市民によるごみの収集のことが出ていましたけれども。それから、あともう１つ。去年、龍馬を縁にした、８都市間の、品川区を含めた協定結びましたよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"２３区と。だから。だけど、視察そのものは否定しないことですから、それは行きたいと思うけれども、別に、飛行機に乗って遠くまで行かなくたって、近隣のところで十分あるわけですよ。だから、結構、今、皆さんが出された具体的な都市は遠いではないですかね。いろいろ、やはり２泊３日ではなければいけないということはあり得ないわけですから。そういうことも含めて、ぜひ検討していただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-040"},{"speaker":"松永委員","kind":"意見","question":"私は、ちょっと商店街の活性化事業として、地域の子どもたちと商店街がタッグを組んでいる団体があって。それは実は静岡県です。以前も言っていたのですけれども、「１０円商店街」というのです。そういったところのそういった事業を見てみたいというのはあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":151,"id":"exchange-041"},{"speaker":"藤原委員","kind":"質問・要望","question":"全てが、やはり品川区にどう活用できるかというのを思いつつ、私も１６年間、議員をさせていただいてまいりました。いつも不思議だなと思うのは、この委員会、構成されたとき、今年の行政視察はどこへ行くかというお話が出るではないですか。だから、先駆的な品川区ということを確認に行くための行政視察ではないと思うので。それで、町会・自治会の支援と、都市型観光って出ているではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-042"},{"speaker":"南委員","kind":"提案","question":"１１月のこの週は、ちょっと、申し訳ないですけれども。委員長、それで、２泊３日という提案なのですけれども。場合ならばという提案だけれども、やはりあまりそこにこだわらずに、さっき皆さんから出た意見、そこ本当に考慮、私も含めて、２泊３日も含めて、あと先進都市ということ、地方都市ということも含めて、やはりいろいろな意見がありますので。ちょっとくどいので、申し訳ないですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2724#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":47901,"voices":161}},{"id":"h27-20150629-7","meetingId":"h27-cm06","date":"2015年6月29日","dateIso":"2015-06-29","committee":"厚生委員会","time":"午前１０時００分～午前１１時５３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"常任委員会へ出席している関係上、予定表記載の審査順について一部変更させていただくことをご容赦ください。 それでは、まず(2)の第５５号議案","agenda":"常任委員会へ出席している関係上、予定表記載の審査順について一部変更させていただくことをご容赦ください。 それでは、まず(2)の第５５号議案","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"IIIの６月補正予算（案）の中、「会議参加者謝礼」と書いてありますけれども、２２９万６,０００円、謝礼というのがわからないのですが、例えば費用弁償というのか、謝礼という表現が、２００万円で謝礼とは何なのだろう、しかも、会議合計で単体の会議が３回、２回、３回なわけですから、それほど多いわけでもないので、どのような感じで組まれたのかを教えてください。","respondent":"永尾高齢者福祉課長","answer":"報酬につきましては、責任を持った検討が行われるように、きちんと報酬の規定に基づいた金額で設定しています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"やる気があるなら当初予算からでもいいわけで、ここら辺の説明がないから、なぜというふうになって、内容自体は非常にいいのですけれども、そこら辺の説明をもう一度していただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"この事業を検討するに当たって、補助金は最初からということではございませんでした。","voiceIndex":9,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこら辺のところをはっきりさせないと。これとの整合性はどうとるのか。今、伺っただけですと、声をかけた今のメンバーはそれほど変わらないのです。一つぐっとそこのメンバーがあるのであれば、そこで詰めてやったほうが効果的ではないかという気もしますが、そこら辺の連携はどうお考えになっているのかお聞かせ願いたい。","respondent":"永尾高齢者福祉課長","answer":"ただ、その認知症ケアパスの作成の検討会議だけが先行してしまっても困りますので、きちんと医療と福祉の連携の会議体と情報共有しながら進めていきたいと考えております。","voiceIndex":11,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問","question":"個人情報は出せませんとなるわけですから。本人の個人情報を出してくれるならいいですけれども、これは役所としては出てこないはずなのです。そうすると、これは非常にアバウト過ぎて、もっとポイントで認知症の方ご本人を地域でも支えよう、家族でも支えよう、行政でも支えようというのであれば、もう少し開示が必要なのではないかと思いますけれども、そこら辺の考えだけは最後に伺っておきます。","respondent":"永尾高齢者福祉課長","answer":"実際に地域の方が例えば認知症の方を見守るとき、確かに個人情報が大きな壁にはなっていますけれども、これからの議論の中で決めていくことではありますけれども、そのときにご本人・ご家族にどのような形で同意をとっていくべきなのか、どこまでの同意が必要なのか。","voiceIndex":13,"id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、この認知症対策プロジェクト支援業務が６００万円ですが、この６００万円はどのような中身なのかについてもお聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"プロジェクト支援業務の６００万円の内訳ですけれども、こちらにつきましては、専門のコンサルタントにお願いをする経費です。","voiceIndex":15,"id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"認知症に対しての対応はこれからも充実させていかなければいけない分野だという思いがあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"改めてそこの確認と、それからこの事項別明細を見せていただいたのですけれども、この中では詳しい謝礼ですとか、その内訳も書いてありますけれども、医療分野の方が１万３,０００円掛ける３回で１８人分、そして、さらに１万３,０００円掛ける２回で９人分、そして福祉分野の方が１万円掛ける２回が４０人で、１万円掛ける２回で２８人ということで事項別明細にありますけれども。","respondent":"永尾高齢者福祉課長","answer":"ケアパスの完成は平成２８年１２月になっているのですけれども、今年度につきましては、先ほどご説明したとおり合同会議と関係者会議、それぞれやっていくような形になっております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"横山委員","kind":"質問・要望","question":"１点だけ詳しく教えていただきたいのですけれども、連携のイメージの中で、地域組織、ＮＰＯ、民間企業、教育と書いてありますけれども、合同会議の中には、地域組織であったり、民間企業であったり、ＮＰＯであったり、また教育の視点の意見を反映するような仕組みというか、会議の設定はされているのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"その中で当事者のご意見等を反映できればと考えています。福祉関係者の中にはＮＰＯ法人も入れる予定にしております。民生委員も入れますので、民生委員もふだん、日常の中でいろいろなお声を地域で聞いておりますので、そこが反映できたらと考えています。","voiceIndex":20,"id":"exchange-008"},{"speaker":"横山委員","kind":"質問","question":"民間企業というところで、もし入っていればと思ったのですけれども、例えばＩＴ関係、システムのようなものを利用してという視点でのご意見をとることはお考えでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ケアパスにつきましては、今のところ、まだシステムまでは考えていないのですけれども、ただ、認知症対策プロジェクトという大きい計画につきましては、システム化も議論になる予定にしておりますので、それは今後の話し合いの中で決めていきたいと考えています。","voiceIndex":22,"id":"exchange-009"},{"speaker":"新妻委員","kind":"意見","question":"今回、この認知症対策プロジェクトの名称をくるみぷらんと品川区はつけていただいているのですが、これが定着をしていくと、また地域の皆様も認知症の意識も高まってくるのかなと思いますが、くるみぷらんに至った名称のいきさつ、また、この思いを込められた部分もあるかと思いますので、お話しいただけるとありがたいです。","respondent":"永尾高齢者福祉課長","answer":"くるみぷらんですけれども、うちの新しい係のメンバーが３人で話し合って決めたのですけれども、ぜひこれからの認知症対策をしっかりやっていきたいという思いが、このくるみぷらんという名称の中に入っていると考えています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"先ほどの会議ですけれども、これはぜひ傍聴したいと思いますけれども、公開される予定はあるのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"まだそこまでの検討は、今、補正予算の提案なので、考えてはいなかったのですけれども、現状では傍聴は考えていないです。","voiceIndex":26,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほど、既存の会議との整合性というご質問が石田委員からございましたけれども、その中で、ケアパスの会議が先行しても困るというニュアンスのご答弁があったのですが、平成２８年１２月を目指すということで、当然、地域包括ケアシステムの中でも、今回、認知症ケアパスに特化した対策をプロジェクトに基づいてやっていくということで、先行という意味がよくわからなかったので、当然、先行して特化して。","respondent":"永尾高齢者福祉課長","answer":"作成後のお話になりますけれども、このケアパスをつくって終わりということではなく、区としては、そのケアパスをつくるところがまず始まりという認識を持っておりますので、まずはそこから取りかかり、これから先。","voiceIndex":29,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"もしかしたら、目線の違いによって２つのパターンとか、３つのパターンはないと思いますけれども、そのようなつくり方もある、あれを本人がお一人で手にすることはなくて、そこら辺のフォローはまたしっかり連携のあり方の中でということだと思いますけれども、例えば町田市が先行してつくられたのを見ると、どうなのでしょうか、見方、目線が違うという、私はさらっと見ただけですけれども、ぜひ先行して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-013"},{"speaker":"横山委員","kind":"質問","question":"大きなところで、ウォーキングマップアプリケーションの導入、地域医療資源検索システム構築支援ですけれども、資料は、今回はないのでしょうか。","respondent":"川島健康課長","answer":"ウォーキングマップはそれほど複雑な話ではないと思ったのですが、記者発表の資料にはつけさせていただいたのですが、地域医療連携のほうの医療資源検索システムも、区の構築するシステムではなかったので、あえて今回は資料から外させていただいて。","voiceIndex":36,"id":"exchange-014"},{"speaker":"のだて委員","kind":"意見","question":"これまで、「私の散歩道」のもとのものがあったと思いますけれども、これは１００円で販売していると思いますが、これまでどれだけ売れたのかと、これまでどのように使ってきたのかをお聞かせください。","respondent":"川島健康課長","answer":"今回、改訂するタイミングでこれを活用して、健康づくりにいろいろと活かしていきたいと考えております。","voiceIndex":38,"id":"exchange-015"},{"speaker":"のだて委員","kind":"意見","question":"今回、その改訂に合わせてアプリケーションを作成するということですけれども、アプリケーションをつくった場合、無料になるのか、有償になるのかということと、このアプリケーションはたぶん委託されると思いますけれども、委託先がどういったところになるのか、サーバーを使うと事項別明細に書いてあったのですけれども、ランニングコストはどういった形になってくるのかお聞かせください。","respondent":"川島健康課長","answer":"アプリケーションは、無料でダウンロードできる形式を考えております。それから、業者はまだこれから予算が認められまして契約するということなので、決定はしておりませんので、どの業者になるかはお答えができないところです。","voiceIndex":40,"id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問","question":"個人情報です。いろいろなところに品川区に関するアプリケーションが出て氾濫してしまうと、何が本物なのかがわからなくなってきてしまって、これはあくまでも品川区がつくるというのだけれども、管理しているところは恐らく違うところに委託してやるので、イメージ的に最終的な着地点というのですか、これで終わりなのか、これから先、もっとどんどん進化していくものなのかを、今の段階でお願いします。","respondent":"川島健康課長","answer":"ほかのアプリケーションとの連携というところでは、まず１つ観光情報につきましては、観光協会のアプリケーションがありますので、その辺と少し情報をうまく折り合いがつくような形で連携して、今、進めるように準備しているところであります。","voiceIndex":42,"id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ほかとリンクすることは、たぶん、携帯電話の中でＧＰＳを使っていること自体、恐らく完結しないと思うので、個人情報についてはしっかりやっていただきたいと思います。そういうものは全く除外された中でこのシステムが構築されるものなのか、本当に品川区にある全てのクリニックや全ての医療関係がここで検索できるのか、そこだけ教えていただけますか。","respondent":"川島健康課長","answer":"そのほかの関係だと、またお答えが変わってくると思いますが、このシステムに関しては、その辺にも調査をかけて、掲載できるかどうかを調査します。","voiceIndex":44,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"「私の散歩道」ですけれども、要望だけしておきたいと思いますが、インターネットで見たときに、「私の散歩道」の紙面を見ることができなかったので、ぜひ公開していただいて、多くの方に知っていただいて、散歩のときなどに活用していただけたらと思います。","respondent":"川島健康課長","answer":"１つ大きくなってきているのが、現状、医師会で受け持っていただいていますかかりつけ医の紹介事業の中の相談が、在宅診療に特化したような話にかなり高度化してきているということで、その地域の医療資源、医者、それから診療所、薬局。","voiceIndex":46,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは要望だけしておきます。お金を出されて医師会が勝手にやってくれるならいいけれども、それはお金を出すほうなのですから、しっかりそこら辺は区の方針、区民目線から見た方針、これはしっかり言って、ここまでは必ずやってくださいと言うのが当たり前だと思いますけれども、そこら辺の考え方だけ教えてください。","respondent":"川島健康課長","answer":"ただいまのご指摘の部分ですが、まず、区の関与は地域医療連携会議の中の下部組織がありますが、その会議の中で出てきた話でもありますので、進行管理も含めてしっかりチェックをして、それから、どこまで区民の方の要望が取り入れられるかという視点もありますが。","voiceIndex":48,"id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほど区民の皆さんからこういう問い合わせもふえてきたし、在宅の医療も非常に難題が多くなってきている、訪問診療も含めて、２４時間なりいろいろなことも含めて、問い合わせも多くなっているから、区もしっかりそういう対応をしていきます、今度そのシステムをやっていくということですから、そうすると、ある程度、区がしっかりそれを踏まえた中で補助もしてやりますということですから。","respondent":"川島健康課長","answer":"今、私の説明が不十分だったと思いますが、地域医療連携会議の下部組織の中で出てきたのは、課題です。今、地域医療連携を進めるための課題として何が足りないかを、その地域医療資源の情報共有ができていないことがまず第一歩だというふうに上がってきたところです。","voiceIndex":50,"id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"ただいまのお話で疑問点がありましたので、詳細をお聞きしたいのですけれども、地域医療資源の情報共有ができていないというところで、こちらのご説明の中では、医療関係者や薬剤の方の会員の方が検索できるシステムとお聞きしたのですけれども、こちらは医療の関係者だけということになるのでしょうか。","respondent":"川島健康課長","answer":"ですので、歯科、それから薬局の方も、当然、検索できるような形になっていくということです。そこでお互いのわからない情報を検索して共有していくという考え方になっております。","voiceIndex":52,"id":"exchange-022"}]},{"id":"topic-02","title":"の第６０号議案、品川区プールの管理に関する条例の一部を改正する条例","agenda":"の第６０号議案、品川区プールの管理に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"今回、認定こども園ができることによって届出で済むようにするということですけれども、許可と届出の違い、衛生面と安全面とあると思いますけれども、そこをお聞かせ願いたいということと、区はそれにどうやってかかわっていくのか、お願いします。","respondent":"高山生活衛生課長","answer":"実際に届出プールよりもより細やかな水質の基準であるとか、あるいは設備面に関しましてのハードルが上がっておりまして、そういったものを確認させていただいて、条例に適合しない場合には罰則などの適用も考えられるという違いがあります。","voiceIndex":65,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"今のご説明ですと、届出のほうが基準が低いというような話ですけれども、衛生面はそういった基準も届出のほうが緩くなっているということでよろしいのでしょうか。","respondent":"高山生活衛生課長","answer":"具体的には、換気、採光、そして温度、あるいは清潔であるかどうかということに関しましては、学校保健安全法に定めます学校環境衛生基準で衛生状態を担保していこうですので、もちろん比較すれば軽重はあろうかと思いますが、一定の安全性。","voiceIndex":67,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"大体、同じぐらいの基準でやられているということで、安心しました。安全面ですけれども、以前に排水溝のふたが外れた事故がありましたので、しっかりと安全面に注意していただいて、やっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-025"}]},{"id":"topic-03","title":"平成２７年請願第１１号、看護師等の大幅増員と夜勤改善で安全・安心の医療・介護を求める請願","agenda":"平成２７年請願第１１号、看護師等の大幅増員と夜勤改善で安全・安心の医療・介護を求める請願","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"６局長通知のほうでも、看護師等の雇用の質の向上に関する省内プロジェクトチーム報告書を作成して、看護職員を中心とした医療スタッフの勤務環境の改善に関するさまざまな取り組みを進めてきたとありますけれども、品川区として実態をどう捉えているかをお聞かせ願いたいと思います。","respondent":"川島健康課長","answer":"ただいまのご質問にありました厚生労働省の通知が出るのは、非常に大きなことだと捉えております。重要な課題だと国も認識して動いているという捉え方です。","voiceIndex":82,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"そこで、私が実際の看護師の方からお話を伺いまして、今、認知症の入院されている方が多いということで、いろいろ徘徊ですとか、勝手につながれているコードを抜いてしまうという実態で、常に看護師長にはナースコールが鳴るとＰＨＳに連絡が来て、ひっきりなしに鳴っているという状況で、大変忙しい状況になっておりまして、１日の初めも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"私も大病院で働いているときも、重度の患者の病棟に行ったときは、８時から申し送りだったのですけれども、７時半には全員が仕事につかないとやり終わらないので、点滴の準備を７時半から始めてしまって、それで８時から申し送りを受けて、結局、１日中ずっと神経も使いながら走り回って、１２時間労働が当たり前という状況で、子育てと看護師の仕事を両立させるのは本当に困難。","respondent":"川島健康課長","answer":"直接、看護師の労働の状況について、私どもは知る立場にないのがお答えになると思いますが、単純に看護師統計を見てみますと、看護師は数だけはふえているというのが、私どもが調べてわかった範囲のお答えになります。","voiceIndex":85,"id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから、ここに喫緊の課題と書いてありますけれども、みんなでここのところの認識をぜひ国民的な認識にまでしていって改善していく、そしてまた患者の命にかかわる大事な職場ですから、そういうところで働きがいを持って潰されないような働き方ができる職場に変えていくことが求められていると思っているところです。看護師や介護士の離職率もわかったら、ぜひお聞かせいただけたらと思います。","respondent":"川島健康課長","answer":"申しわけございません、離職率は把握しておりませんが、看護師の総数、平成２５年度は１５７万１,６４７人です。前年度が１５３万７,８１３人で、３万人ほど数だけで言うとふえている状況にあるという、これはいろいろな実態があるとは思いますが、そういう統計が出てあります。","voiceIndex":87,"id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"小泉構造改革のときに、毎年、毎年、２,２００億円ずつ加えて２,２００億円というふうなことで２００億円ずつ削減してきて、今の医療の大変な実態をつくってきたということがあると思いますけれども、それに加えて今度の安倍内閣のもとで、今、出されているのが、自然増に対して３,０００億円から５,０００億円ぐらい削減していくという方向が出されていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"課題はもちろんあるけれども、この基準自体については、相当、当時とは違いますと。ですから、そういう根拠を示すことが困難な状況にあるものについて、一自治体として基準についての意見書を出す立場にはないと考えていますので、これについては、課題はあるとは思っていますけれども、この意見書を出すという請願については不採択と言わざるを得ないというのが我々の今の立場であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-031"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１点だけお伺いしたいのですけれども、５局長通知や６局長通知は、都道府県知事に厚生労働省が出して、その後、こういうものが各市町村へおりてきて、どのような流れでこういうものがやってきて、それを受けた市町村は何をするのか、要は５局長通知や６局長通知の書類的な流れを教えていただきたいのです。","respondent":"川島健康課長","answer":"先ほどのナースセンターの１０月から登録制が始まりますという通知が、６月に東京都の福祉保健局から区に通知がおりてきておりましたので、厚生労働省から通知が出たものが都道府県のこういった関係だと福祉保健局におりてきて、その後。","voiceIndex":91,"id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問・要望","question":"あまり理解できないのですが、その配慮してくださいというその配慮は、どこに配慮するのか、来て地域でやられている医療機関には、こういった文書はもちろん行っているものなのですか。その辺はどういう請願なのかが全く理解できない自分がここにいるのですけれども、説明できませんよね。どうですか。課長、すみませんでした。結論からいうと、私も何件か病院やいろいろ確認をしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-033"},{"speaker":"若林委員","kind":"意見","question":"２番目のこの医師、看護師、介護職員等を大幅にふやすということを区議会から国に意見書を上げるのは、先ほどの１番目もそうですけれども、今度は逆にこれは大幅にふやすことという、請願の理由の中でもつまびらかにはわからないところもありますので、そういう言い方は国に対して地方議会として言う意見の言い方ではないということで、私も意見書を出すことには至らないという思いがします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この日本医療労働組合連合会で要望として出しているのは、３交代夜勤で月６日、これくらいだったら、私は２交代で月５日の夜勤をやっていたのですけれども、だから、３交代にすると月１０回くらいの夜勤でずっとやっていたのですけれども、そういうことだと、本当にきついです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"みんな、そういう思いでやっていますけれども、そのやりがいのあるいい仕事を続けられる労働条件にしてほしい、そのためには、看護師をふやして、３交代で夜勤はせめて月６回ぐらいまでで週休２日ということで続けられるようにしてほしい。そういうところでは先進国並みにと、そういうところで、私はぜひとも皆さんにこの議会からやっぱり声を上げようと改めて訴えさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"質問","question":"きょう結論を出してください。１つつけ加えすると、これは非常に国も課題に感じているからこそ局長通知を出している。そうすると、今はそれこそ３交代もあるし、子育ての部分も配慮していると。だけれども、ここで、では、この２項目で請願を区として国に上げるかというと、私は、その立場にはないと思っているので、ここの請願には不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-037"},{"speaker":"のだて委員","kind":"意見","question":"きょうは結論を出すということで、好きな仕事も忙し過ぎて続けられないと。自分が死ぬか、患者を殺してしまうかという状況でやめることになっているという話もありますので、ぜひこれは採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-038"},{"speaker":"いながわ委員","kind":"意見","question":"本日結論を出すということで、先ほど申し上げたとおりであります。ただ、１点言えるのは、医療の充実は大切なことでありますので、だからこそこういった通知が出ていると考えていますので、特に品川区からこういった請願を出す必要性はないと考えていますので、請願には賛成することはできません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-039"}]},{"id":"topic-04","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、厚生委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、厚生委員会にかかわる項目","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これはフォロー質問ができるのかも含めてお聞きしたいのですけれども、自民党・子ども未来の横山由香理議員が質問した旗の台駅周辺バリアフリー計画についてですけれども、策定協議会をつくり、平成２９年度に取りまとめをしていくということでの本会議でのご答弁だったのですけれども、この旗の台駅周辺バリアフリー計画についての進め方のスケジュールですとか、主な内容。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"質問","question":"今のは、鈴木副委員長がおっしゃっているのは、それでいいのですけれども、たぶん鈴木副委員長もご心配されているのは、その質問の中で旗の台駅周辺は品川区立心身障害者福祉会館があるから、その部分のバリアフリー化という部分はいいのですが、全体のこととなると、所管がこの委員会ではなくなってしまうのではないですか。それは委員長に言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3418#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":30790,"voices":115}}]);
